--
-- Name: _capture_db_health_snapshot_impl(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._capture_db_health_snapshot_impl(p_source text DEFAULT 'manual'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_id uuid;
BEGIN
  INSERT INTO public.db_health_snapshots(source, captured_by)
  VALUES (COALESCE(NULLIF(p_source,''), 'manual'), auth.uid()) RETURNING id INTO v_id;

  INSERT INTO public.db_health_objects(snapshot_id,object_type,object_schema,object_name,detail)
  SELECT v_id,'table',n.nspname,c.relname,
         jsonb_build_object('rls_enabled',c.relrowsecurity,
                            'row_estimate',GREATEST(c.reltuples,0)::bigint,
                            'size_bytes',pg_total_relation_size(c.oid))
  FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
  WHERE n.nspname='public' AND c.relkind='r';

  INSERT INTO public.db_health_objects(snapshot_id,object_type,object_schema,object_name,detail)
  SELECT v_id,'view',n.nspname,c.relname,jsonb_build_object('materialized',c.relkind='m')
  FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
  WHERE n.nspname='public' AND c.relkind IN ('v','m');

  INSERT INTO public.db_health_objects(snapshot_id,object_type,object_schema,parent_name,object_name,detail)
  SELECT v_id,'column',c.table_schema,c.table_name,c.column_name,
         jsonb_build_object('data_type',c.data_type,'is_nullable',c.is_nullable,
                            'column_default',c.column_default,'ordinal',c.ordinal_position)
  FROM information_schema.columns c WHERE c.table_schema='public';

  INSERT INTO public.db_health_objects(snapshot_id,object_type,object_schema,parent_name,object_name,detail)
  SELECT v_id,'policy',p.schemaname,p.tablename,p.policyname,
         jsonb_build_object('cmd',p.cmd,'permissive',p.permissive,'roles',p.roles,
                            'qual',p.qual,'with_check',p.with_check)
  FROM pg_policies p WHERE p.schemaname='public';

  INSERT INTO public.db_health_objects(snapshot_id,object_type,object_schema,object_name,detail)
  SELECT v_id,'function',n.nspname,p.oid::regprocedure::text,
         jsonb_build_object('security_definer',p.prosecdef,'language',l.lanname,'kind',p.prokind)
  FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
  JOIN pg_language l ON l.oid=p.prolang WHERE n.nspname='public';

  INSERT INTO public.db_health_objects(snapshot_id,object_type,object_schema,parent_name,object_name,detail)
  SELECT v_id,'trigger',n.nspname,c.relname,t.tgname,jsonb_build_object('enabled',t.tgenabled)
  FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid
  JOIN pg_namespace n ON n.oid=c.relnamespace
  WHERE NOT t.tgisinternal AND n.nspname='public';

  INSERT INTO public.db_health_objects(snapshot_id,object_type,object_schema,parent_name,object_name,detail)
  SELECT v_id,'index',i.schemaname,i.tablename,i.indexname,jsonb_build_object('definition',i.indexdef)
  FROM pg_indexes i WHERE i.schemaname='public';

  INSERT INTO public.db_health_objects(snapshot_id,object_type,object_schema,parent_name,object_name,detail)
  SELECT v_id,'foreign_key',n.nspname,c.relname,con.conname,
         jsonb_build_object('definition',pg_get_constraintdef(con.oid))
  FROM pg_constraint con JOIN pg_class c ON c.oid=con.conrelid
  JOIN pg_namespace n ON n.oid=c.relnamespace
  WHERE con.contype='f' AND n.nspname='public';

  INSERT INTO public.db_health_objects(snapshot_id,object_type,object_schema,object_name,detail)
  SELECT v_id,'enum',n.nspname,t.typname,
         jsonb_build_object('labels',(SELECT jsonb_agg(e.enumlabel ORDER BY e.enumsortorder)
                                      FROM pg_enum e WHERE e.enumtypid=t.oid))
  FROM pg_type t JOIN pg_namespace n ON n.oid=t.typnamespace
  WHERE t.typtype='e' AND n.nspname='public';

  INSERT INTO public.db_health_objects(snapshot_id,object_type,object_schema,object_name,detail)
  SELECT v_id,'sequence',n.nspname,c.relname,'{}'::jsonb
  FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
  WHERE n.nspname='public' AND c.relkind='S';

  INSERT INTO public.db_health_objects(snapshot_id,object_type,object_schema,object_name,detail)
  SELECT v_id,'extension',COALESCE(n.nspname,'-'),e.extname,jsonb_build_object('version',e.extversion)
  FROM pg_extension e LEFT JOIN pg_namespace n ON n.oid=e.extnamespace;

  BEGIN
    INSERT INTO public.db_health_objects(snapshot_id,object_type,object_schema,object_name,detail)
    SELECT v_id,'cron_job','cron',j.jobname,
           jsonb_build_object('schedule',j.schedule,'active',j.active,'command',j.command)
    FROM cron.job j;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'db_health: cron.job not readable (%)', SQLERRM;
  END;

  UPDATE public.db_health_snapshots s SET
    table_count              = (SELECT count(*) FROM db_health_objects o WHERE o.snapshot_id=v_id AND o.object_type='table'),
    view_count               = (SELECT count(*) FROM db_health_objects o WHERE o.snapshot_id=v_id AND o.object_type='view'),
    column_count             = (SELECT count(*) FROM db_health_objects o WHERE o.snapshot_id=v_id AND o.object_type='column'),
    rls_policy_count         = (SELECT count(*) FROM db_health_objects o WHERE o.snapshot_id=v_id AND o.object_type='policy'),
    rls_enabled_table_count  = (SELECT count(*) FROM db_health_objects o WHERE o.snapshot_id=v_id AND o.object_type='table' AND (o.detail->>'rls_enabled')::boolean),
    rls_disabled_table_count = (SELECT count(*) FROM db_health_objects o WHERE o.snapshot_id=v_id AND o.object_type='table' AND NOT (o.detail->>'rls_enabled')::boolean),
    function_count           = (SELECT count(*) FROM db_health_objects o WHERE o.snapshot_id=v_id AND o.object_type='function'),
    trigger_count            = (SELECT count(*) FROM db_health_objects o WHERE o.snapshot_id=v_id AND o.object_type='trigger'),
    index_count              = (SELECT count(*) FROM db_health_objects o WHERE o.snapshot_id=v_id AND o.object_type='index'),
    foreign_key_count        = (SELECT count(*) FROM db_health_objects o WHERE o.snapshot_id=v_id AND o.object_type='foreign_key'),
    enum_count               = (SELECT count(*) FROM db_health_objects o WHERE o.snapshot_id=v_id AND o.object_type='enum'),
    sequence_count           = (SELECT count(*) FROM db_health_objects o WHERE o.snapshot_id=v_id AND o.object_type='sequence'),
    extension_count          = (SELECT count(*) FROM db_health_objects o WHERE o.snapshot_id=v_id AND o.object_type='extension'),
    cron_job_count           = (SELECT count(*) FROM db_health_objects o WHERE o.snapshot_id=v_id AND o.object_type='cron_job'),
    cron_job_active_count    = (SELECT count(*) FROM db_health_objects o WHERE o.snapshot_id=v_id AND o.object_type='cron_job' AND (o.detail->>'active')::boolean),
    total_row_estimate       = (SELECT COALESCE(sum((o.detail->>'row_estimate')::bigint),0) FROM db_health_objects o WHERE o.snapshot_id=v_id AND o.object_type='table'),
    db_size_bytes            = pg_database_size(current_database())
  WHERE s.id=v_id;

  RETURN v_id;
END $$;



--
-- Name: _post_credit_note_to_ledger(uuid, uuid, numeric, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._post_credit_note_to_ledger(p_cn_id uuid, p_retailer_id uuid, p_amount numeric, p_primary_order uuid, p_actor uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_collection uuid; v_pending numeric; v_apply numeric := 0; v_left numeric;
begin
  if coalesce(p_amount,0) <= 0 then perform public.recompute_retailer_pending(p_retailer_id); return; end if;
  insert into retailer_payment_collections (retailer_id, amount, payment_method, collected_by_user_id, notes)
  values (p_retailer_id, p_amount, 'credit_note', p_actor, 'Credit note '||p_cn_id::text)
  returning id into v_collection;
  if p_primary_order is not null then
    select coalesce(credit_pending_amount,0) into v_pending from orders where id=p_primary_order for update;
    v_apply := least(p_amount, v_pending);
    if v_apply > 0 then
      update orders set credit_paid_amount=coalesce(credit_paid_amount,0)+v_apply,
        credit_pending_amount=coalesce(credit_pending_amount,0)-v_apply,
        payment_status=case when coalesce(credit_pending_amount,0)-v_apply<=0 then 'paid' else 'partial' end
      where id=p_primary_order;
      insert into retailer_payment_allocations (collection_id, order_id, retailer_id, amount_applied)
      values (v_collection, p_primary_order, p_retailer_id, v_apply);
    end if;
  end if;
  v_left := public.reflow_allocation_fifo(p_retailer_id, v_collection, p_amount - coalesce(v_apply,0), p_primary_order);
  if v_left > 0 then
    insert into credit_ledger (retailer_id, amount, type, reference_id, created_by)
    values (p_retailer_id, -v_left, 'return_credit', p_cn_id, p_actor);
  end if;
  perform public.recompute_retailer_pending(p_retailer_id);
end; $$;



--
-- Name: _safe_uuid(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._safe_uuid(p text) RETURNS uuid
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
  SELECT CASE
    WHEN p IS NULL THEN NULL
    WHEN p ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN p::uuid
    ELSE NULL
  END;
$_$;



--
-- Name: activity_visit_action(uuid, uuid, text, uuid, double precision, double precision, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.activity_visit_action(p_visit_id uuid, p_activity_event_id uuid, p_action text, p_actor uuid, p_lat double precision DEFAULT NULL::double precision, p_lng double precision DEFAULT NULL::double precision, p_outcome text DEFAULT NULL::text, p_summary text DEFAULT NULL::text, p_voice_url text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_ci       timestamptz;
  v_dur      integer;
  v_owner    uuid;
  v_actor    uuid;
  v_is_owner boolean;
begin
  select user_id into v_owner from activity_events where id = p_activity_event_id;
  v_actor := coalesce(auth.uid(), p_actor);
  v_is_owner := (v_owner is null or v_actor is null or v_actor = v_owner);

  if p_action = 'check_in' then
    update visits set check_in_time = coalesce(check_in_time, now()), status = 'in-progress'
     where id = p_visit_id;

    if v_is_owner then
      update activity_events set check_in_time = coalesce(check_in_time, now()), status = 'active',
        check_in_latitude = coalesce(p_lat, check_in_latitude),
        check_in_longitude = coalesce(p_lng, check_in_longitude),
        start_latitude = coalesce(p_lat, start_latitude),
        start_longitude = coalesce(p_lng, start_longitude)
       where id = p_activity_event_id;
    end if;

  elsif p_action in ('check_out', 'complete') then
    select check_in_time into v_ci from activity_events where id = p_activity_event_id;
    v_dur := case when v_ci is not null
                  then greatest(0, round(extract(epoch from (now() - v_ci)) / 60))::int
             end;

    update visits set check_out_time = now(),
      status = case when p_outcome in ('productive','unproductive') then p_outcome else 'productive' end
     where id = p_visit_id;

    if v_is_owner then
      update activity_events set check_out_time = now(), status = 'closed', completed_at = now(),
        duration_minutes = coalesce(v_dur, duration_minutes),
        completion_summary = coalesce(p_summary, completion_summary),
        voice_note_url = coalesce(p_voice_url, voice_note_url),
        end_latitude = coalesce(p_lat, end_latitude),
        end_longitude = coalesce(p_lng, end_longitude)
       where id = p_activity_event_id;
    end if;

  else
    return jsonb_build_object('success', false, 'error', 'unknown action');
  end if;

  return jsonb_build_object('success', true, 'action', p_action, 'closed_event', v_is_owner);
end;
$$;



--
-- Name: add_carry_forward_to_plan(uuid, date, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_carry_forward_to_plan(p_user uuid, p_date date, p_retailer_ids uuid[] DEFAULT NULL::uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_count integer := 0;
BEGIN
  IF p_user <> auth.uid() AND NOT public.is_subordinate_of(auth.uid(), p_user) THEN
    RETURN 0;
  END IF;

  WITH targets AS (
    SELECT * FROM public.get_carry_forward_retailers(p_user, p_date) g
    WHERE p_retailer_ids IS NULL OR g.retailer_id = ANY(p_retailer_ids)
  ), ins AS (
    INSERT INTO public.visits (user_id, retailer_id, planned_date, status, is_carry_forward, carried_from_date)
    SELECT p_user, t.retailer_id, p_date, 'planned', true, t.cancelled_on
    FROM targets t
    WHERE NOT EXISTS (
      SELECT 1 FROM public.visits v
      WHERE v.user_id = p_user
        AND v.retailer_id = t.retailer_id
        AND v.planned_date = p_date
        AND v.status = 'planned'
    )
    RETURNING 1
  )
  SELECT count(*)::int INTO v_count FROM ins;

  RETURN v_count;
END;
$$;



--
-- Name: admin_deactivate_all_products(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_deactivate_all_products() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_products integer := 0;
  v_variants integer := 0;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.user_has_permission(v_uid, 'admin_product_mgmt', 'can_modify_all') THEN
    RAISE EXCEPTION 'Your profile does not have permission to perform this action.'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  UPDATE public.products SET is_active = false WHERE is_active = true;
  GET DIAGNOSTICS v_products = ROW_COUNT;
  UPDATE public.product_variants SET is_active = false WHERE is_active = true;
  GET DIAGNOSTICS v_variants = ROW_COUNT;
  RETURN jsonb_build_object('success', true,
    'deactivated_products', v_products, 'deactivated_variants', v_variants);
END; $$;



--
-- Name: allocate_inventory_batches(uuid, uuid, integer, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.allocate_inventory_batches(p_distributor_id uuid, p_product_id uuid, p_required_qty integer, p_strategy text DEFAULT 'FEFO'::text, p_warehouse_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_batch RECORD;
  v_remaining INTEGER := p_required_qty;
  v_alloc_qty INTEGER;
  v_allocations JSONB := '[]'::JSONB;
  v_total_allocated INTEGER := 0;
  v_available INTEGER;
BEGIN
  FOR v_batch IN
    SELECT id, batch_no, expiry_date, quantity, reserved_qty
    FROM inventory_batches
    WHERE distributor_id = p_distributor_id
      AND product_id = p_product_id
      AND (quantity - reserved_qty) > 0
      AND (expiry_date IS NULL OR expiry_date > CURRENT_DATE)
      AND (p_warehouse_id IS NULL OR warehouse_id = p_warehouse_id)
    ORDER BY
      CASE WHEN p_strategy = 'FEFO' THEN expiry_date END ASC NULLS LAST,
      CASE WHEN p_strategy = 'FIFO' THEN created_at END ASC,
      CASE WHEN p_strategy = 'LIFO' THEN created_at END DESC
  LOOP
    EXIT WHEN v_remaining <= 0;

    v_available := v_batch.quantity - v_batch.reserved_qty;
    v_alloc_qty := LEAST(v_available, v_remaining);

    v_allocations := v_allocations || jsonb_build_object(
      'batch_id', v_batch.id,
      'batch_no', v_batch.batch_no,
      'expiry_date', v_batch.expiry_date,
      'allocated_qty', v_alloc_qty,
      'available_qty', v_available
    );

    v_total_allocated := v_total_allocated + v_alloc_qty;
    v_remaining := v_remaining - v_alloc_qty;
  END LOOP;

  RETURN jsonb_build_object(
    'allocations', v_allocations,
    'total_allocated', v_total_allocated,
    'shortfall_qty', GREATEST(0, v_remaining)
  );
END;
$$;



--
-- Name: allocate_payment_fifo(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.allocate_payment_fifo(p_payment_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_retailer uuid; v_remaining numeric(14,2); v_amount numeric(14,2); rec record; v_take numeric(14,2);
BEGIN
  SELECT retailer_id, amount INTO v_retailer, v_amount FROM public.distributor_payments WHERE id = p_payment_id;
  DELETE FROM public.payment_allocations WHERE payment_id = p_payment_id;
  v_remaining := v_amount;
  FOR rec IN SELECT id, balance_due FROM public.distributor_secondary_invoices WHERE retailer_id = v_retailer AND COALESCE(balance_due,0) > 0 ORDER BY invoice_date ASC, created_at ASC LOOP
    EXIT WHEN v_remaining <= 0;
    v_take := LEAST(v_remaining, rec.balance_due);
    IF v_take > 0 THEN
      INSERT INTO public.payment_allocations(payment_id, invoice_id, allocated_amount, allocation_type, created_by) VALUES (p_payment_id, rec.id, v_take, 'fifo', auth.uid());
      v_remaining := v_remaining - v_take;
    END IF;
  END LOOP;
END $$;



--
-- Name: allocate_payment_manual(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.allocate_payment_manual(p_payment_id uuid, p_allocations jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE rec jsonb; v_amount numeric(14,2); v_sum numeric(14,2) := 0; v_pay_amt numeric(14,2); v_distributor uuid; v_allow_unalloc boolean;
BEGIN
  SELECT amount, distributor_id INTO v_pay_amt, v_distributor FROM public.distributor_payments WHERE id = p_payment_id;
  SELECT COALESCE(allow_unallocated_amount, true) INTO v_allow_unalloc FROM public.distributor_collection_policy WHERE distributor_id = v_distributor;
  FOR rec IN SELECT * FROM jsonb_array_elements(p_allocations) LOOP
    v_amount := (rec->>'amount')::numeric;
    IF v_amount > 0 THEN v_sum := v_sum + v_amount; END IF;
  END LOOP;
  IF v_sum > v_pay_amt THEN RAISE EXCEPTION 'Allocation sum (%) exceeds payment amount (%)', v_sum, v_pay_amt; END IF;
  IF COALESCE(v_allow_unalloc, true) = false AND v_sum < v_pay_amt THEN RAISE EXCEPTION 'Unallocated amount not permitted by distributor policy'; END IF;
  DELETE FROM public.payment_allocations WHERE payment_id = p_payment_id;
  FOR rec IN SELECT * FROM jsonb_array_elements(p_allocations) LOOP
    v_amount := (rec->>'amount')::numeric;
    IF v_amount > 0 THEN
      INSERT INTO public.payment_allocations(payment_id, invoice_id, allocated_amount, allocation_type, created_by) VALUES (p_payment_id, (rec->>'invoice_id')::uuid, v_amount, 'manual', auth.uid());
    END IF;
  END LOOP;
END $$;



--
-- Name: apply_event_stock_for_order(uuid, uuid, date, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_event_stock_for_order(p_visit_id uuid, p_order_id uuid, p_order_date date, p_items jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_event_id uuid;
  v_day_id   uuid;
  v_user     uuid := auth.uid();
  v_product  uuid;
  v_qty      numeric;
  v_row      record;
  v_claim_id uuid;
  v_updated  int := 0;
  v_skipped  int := 0;
  v_warnings jsonb := '[]'::jsonb;
begin
  if v_user is null then
    raise exception 'Not authenticated';
  end if;
  if p_visit_id is null or p_items is null then
    return jsonb_build_object('updated',0,'skipped',0,'warnings','[]'::jsonb);
  end if;

  select id into v_event_id from public.activity_events where visit_id = p_visit_id limit 1;
  if v_event_id is null then
    return jsonb_build_object('updated',0,'skipped',0,'warnings',jsonb_build_array('No event linked to visit'));
  end if;

  select id into v_day_id from public.event_stock_days
   where event_id = v_event_id and date = p_order_date limit 1;
  if v_day_id is null then
    select id into v_day_id from public.event_stock_days
     where event_id = v_event_id order by day_number asc limit 1;
  end if;
  if v_day_id is null then
    return jsonb_build_object('updated',0,'skipped',0,'warnings',jsonb_build_array('No stock day initialized for event'));
  end if;

  for v_product, v_qty in
    select (item->>'product_id')::uuid, sum(coalesce((item->>'quantity')::numeric, 0))
      from jsonb_array_elements(p_items) item
     where (item->>'product_id') is not null
     group by 1
  loop
    if v_qty <= 0 then continue; end if;

    -- The trigger runs first, always — synchronously, inside the same
    -- transaction that inserts order_items. If it has already recorded THIS
    -- product for THIS order, trust it completely: applying this RPC's own
    -- aggregate on top would double the sale.
    if exists (
      select 1 from public.event_stock_audit
       where order_id = p_order_id and product_id = v_product and order_item_id is not null
    ) then
      continue;
    end if;

    select id, stock_taken, sold_qty into v_row
      from public.event_stock_items
     where event_stock_day_id = v_day_id and product_id = v_product
     for update;

    if not found then
      v_skipped := v_skipped + 1;
      v_warnings := v_warnings || jsonb_build_array(jsonb_build_object('product_id', v_product, 'reason', 'No stock row'));
      continue;
    end if;

    insert into public.event_stock_audit(
      event_stock_item_id, event_id, event_stock_day_id, product_id,
      order_id, visit_id, user_id, delta_qty, prev_sold_qty, new_sold_qty, source
    ) values (
      v_row.id, v_event_id, v_day_id, v_product,
      p_order_id, p_visit_id, v_user, v_qty, v_row.sold_qty, v_row.sold_qty + v_qty, 'order_submit'
    )
    on conflict (order_id, product_id) where order_item_id is null do nothing
    returning id into v_claim_id;

    if v_claim_id is null then
      continue;
    end if;

    update public.event_stock_items
       set sold_qty = v_row.sold_qty + v_qty, updated_at = now()
     where id = v_row.id;

    if (v_row.sold_qty + v_qty) > v_row.stock_taken then
      v_warnings := v_warnings || jsonb_build_array(jsonb_build_object('product_id', v_product, 'reason', 'Sold exceeds stock taken'));
    end if;

    v_updated := v_updated + 1;
  end loop;

  return jsonb_build_object(
    'updated', v_updated, 'skipped', v_skipped,
    'event_id', v_event_id, 'event_stock_day_id', v_day_id, 'warnings', v_warnings
  );
end;
$$;



--
-- Name: apply_regularization_to_attendance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_regularization_to_attendance() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_attendance_id uuid;
  v_check_in timestamptz;
  v_check_out timestamptz;
  v_total_hours numeric;
BEGIN
  IF NEW.status = 'approved' AND (OLD.status IS DISTINCT FROM 'approved') THEN
    SELECT id, check_in_time, check_out_time 
    INTO v_attendance_id, v_check_in, v_check_out
    FROM attendance 
    WHERE user_id = NEW.user_id AND date = NEW.attendance_date
    LIMIT 1;

    v_check_in := COALESCE(NEW.requested_check_in_time, v_check_in);
    v_check_out := COALESCE(NEW.requested_check_out_time, v_check_out);
    
    IF v_check_in IS NOT NULL AND v_check_out IS NOT NULL THEN
      v_total_hours := ROUND(EXTRACT(EPOCH FROM (v_check_out - v_check_in)) / 3600.0, 2);
    END IF;

    IF v_attendance_id IS NOT NULL THEN
      UPDATE attendance SET
        check_in_time = v_check_in,
        check_out_time = v_check_out,
        total_hours = v_total_hours,
        status = 'regularized',
        regularized_request_id = NEW.id,
        updated_at = now()
      WHERE id = v_attendance_id;
    ELSE
      INSERT INTO attendance (user_id, date, check_in_time, check_out_time, total_hours, status, regularized_request_id)
      VALUES (NEW.user_id, NEW.attendance_date, v_check_in, v_check_out, v_total_hours, 'regularized', NEW.id);
    END IF;
  END IF;
  RETURN NEW;
END;
$$;



--
-- Name: apply_retailer_payment_fifo(uuid, numeric, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_retailer_payment_fifo(p_retailer_id uuid, p_amount numeric, p_collection_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_remaining numeric := p_amount; v_allocations jsonb := '[]'::jsonb; v_new_pending numeric := 0; v_apply numeric; v_order RECORD; v_already_allocated numeric;
BEGIN
  IF p_amount IS NULL OR p_amount <= 0 THEN RAISE EXCEPTION 'Amount must be positive'; END IF;
  SELECT COALESCE(SUM(amount_applied), 0) INTO v_already_allocated FROM public.retailer_payment_allocations WHERE collection_id = p_collection_id;
  IF v_already_allocated > 0 THEN
    v_new_pending := public.recompute_retailer_pending(p_retailer_id);
    RETURN jsonb_build_object('already_applied', true, 'allocated_amount', v_already_allocated, 'unallocated_amount', GREATEST(p_amount - v_already_allocated, 0), 'new_pending_amount', v_new_pending,
      'allocations', (SELECT COALESCE(jsonb_agg(jsonb_build_object('order_id', order_id, 'applied_amount', amount_applied)), '[]'::jsonb) FROM public.retailer_payment_allocations WHERE collection_id = p_collection_id));
  END IF;
  PERFORM 1 FROM public.retailers WHERE id = p_retailer_id FOR UPDATE;
  FOR v_order IN SELECT id, COALESCE(credit_pending_amount, 0) AS pending, COALESCE(credit_paid_amount, 0) AS paid, total_amount FROM public.orders
    WHERE retailer_id = p_retailer_id AND is_credit_order = true AND COALESCE(status, '') <> 'cancelled' AND COALESCE(credit_pending_amount, 0) > 0
    ORDER BY order_date ASC NULLS LAST, created_at ASC FOR UPDATE SKIP LOCKED
  LOOP
    EXIT WHEN v_remaining <= 0;
    v_apply := LEAST(v_remaining, v_order.pending);
    UPDATE public.orders SET credit_paid_amount = COALESCE(credit_paid_amount, 0) + v_apply, credit_pending_amount = COALESCE(credit_pending_amount, 0) - v_apply,
      payment_status = CASE WHEN COALESCE(credit_pending_amount, 0) - v_apply <= 0 THEN 'paid' ELSE 'partial' END WHERE id = v_order.id;
    INSERT INTO public.retailer_payment_allocations (collection_id, order_id, retailer_id, amount_applied) VALUES (p_collection_id, v_order.id, p_retailer_id, v_apply);
    v_allocations := v_allocations || jsonb_build_object('order_id', v_order.id, 'applied_amount', v_apply, 'remaining_after', v_order.pending - v_apply);
    v_remaining := v_remaining - v_apply;
  END LOOP;
  v_new_pending := public.recompute_retailer_pending(p_retailer_id);
  RETURN jsonb_build_object('already_applied', false, 'allocated_amount', p_amount - v_remaining, 'unallocated_amount', v_remaining, 'new_pending_amount', v_new_pending, 'allocations', v_allocations);
END; $$;



--
-- Name: assign_activity(uuid[], text, date, integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assign_activity(p_subordinate_ids uuid[], p_activity_type text, p_activity_date date, p_expected_duration_minutes integer DEFAULT NULL::integer, p_half_day_type text DEFAULT NULL::text, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_mgr uuid := auth.uid(); v_uid uuid; v_visit uuid; v_created int := 0; v_skipped int := 0; v_all boolean;
begin
  if v_mgr is null then return jsonb_build_object('success',false,'error','not authenticated'); end if;
  if not public.user_has_permission(v_mgr,'action_activity_assign','can_create') then
    return jsonb_build_object('success',false,'error','no permission to assign activities'); end if;
  v_all := public.user_has_permission(v_mgr,'activity_team_view','can_view_all');
  foreach v_uid in array p_subordinate_ids loop
    if not v_all and not exists (
      with recursive dl(uid) as (
        select e.user_id from employees e where e.manager_id = v_mgr
        union select e2.user_id from employees e2 join dl on e2.manager_id = dl.uid
      ) select 1 from dl where uid = v_uid
    ) then v_skipped := v_skipped + 1; continue; end if;

    insert into public.visits (user_id, planned_date, status, visit_type)
      values (v_uid, p_activity_date, 'planned', 'activity') returning id into v_visit;

    insert into public.activity_events
      (visit_id, user_id, activity_type, visit_category, activity_date, duration_type,
       expected_duration_minutes, half_day_type, assigned_by, assignment_note, status)
      values (v_visit, v_uid, p_activity_type, p_activity_type, p_activity_date, 'single_day',
       p_expected_duration_minutes, p_half_day_type, v_mgr, p_note, 'upcoming');
    v_created := v_created + 1;
  end loop;
  return jsonb_build_object('success',true,'created',v_created,'skipped',v_skipped);
end; $$;



--
-- Name: assign_beat_cover(text, date, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assign_beat_cover(p_beat_id text, p_date date, p_absent_user uuid, p_cover_user uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_moved integer := 0;
  v_beat_name text;
BEGIN
  IF NOT public.is_subordinate_of(auth.uid(), p_absent_user) THEN
    RAISE EXCEPTION 'Not authorized to reassign visits for this user';
  END IF;

  WITH moved AS (
    UPDATE public.visits v
    SET user_id = p_cover_user,
        covered_for_user_id = p_absent_user,
        updated_at = now()
    WHERE v.user_id = p_absent_user
      AND v.planned_date = p_date
      AND v.status = 'planned'
      AND v.retailer_id IN (SELECT id FROM public.retailers WHERE beat_id = p_beat_id)
      AND NOT EXISTS (
        SELECT 1 FROM public.visits v2
        WHERE v2.user_id = p_cover_user
          AND v2.planned_date = p_date
          AND v2.status = 'planned'
          AND v2.retailer_id = v.retailer_id
      )
    RETURNING 1
  )
  SELECT count(*) INTO v_moved FROM moved;

  SELECT beat_name INTO v_beat_name FROM public.beats WHERE beat_id = p_beat_id LIMIT 1;
  IF v_beat_name IS NULL THEN
    v_beat_name := p_beat_id;
  END IF;

  INSERT INTO public.beat_coverage_assignments (
    primary_user_id, coverage_user_id, beat_id, beat_name,
    start_date, end_date, reason, is_active, assigned_by
  ) VALUES (
    p_absent_user, p_cover_user, p_beat_id, v_beat_name,
    p_date, p_date, 'AI leave cover', true, auth.uid()
  );

  RETURN v_moved;
END;
$$;



