--
-- Name: auto_seed_system_admin_permissions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_seed_system_admin_permissions() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Skip if the inserting profile is already a system profile
  IF EXISTS (SELECT 1 FROM security_profiles WHERE id = NEW.profile_id AND is_system = true) THEN
    RETURN NEW;
  END IF;

  -- Auto-insert for all system admin profiles if not already present
  INSERT INTO profile_object_permissions (
    profile_id, object_name, permission_type, parent_module,
    can_read, can_create, can_edit, can_delete, can_view_all, can_modify_all
  )
  SELECT
    sp.id, NEW.object_name, NEW.permission_type, NEW.parent_module,
    true, true, true, true, true, true
  FROM security_profiles sp
  WHERE sp.is_system = true
    AND NOT EXISTS (
      SELECT 1 FROM profile_object_permissions pop
      WHERE pop.profile_id = sp.id
        AND pop.object_name = NEW.object_name
        AND pop.permission_type = NEW.permission_type
    );

  RETURN NEW;
END;
$$;



--
-- Name: auto_update_visit_status_on_order(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_update_visit_status_on_order() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  target_visit_id uuid;
  has_items       boolean;
  is_activity     boolean;
begin
  if new.status = 'confirmed' then
    select exists (select 1 from order_items where order_id = new.id) into has_items;

    if not has_items then
      raise log 'auto_update_visit_status_on_order: skipping order % - no items yet', new.id;
      return new;
    end if;

    target_visit_id := new.visit_id;

    if target_visit_id is null and new.retailer_id is not null and new.user_id is not null then
      select id into target_visit_id
        from visits
       where retailer_id = new.retailer_id
         and user_id = new.user_id
         and planned_date = new.order_date
         and status in ('planned', 'in-progress', 'unproductive')
       order by created_at desc
       limit 1;
    end if;

    if target_visit_id is not null then
      select (coalesce(v.visit_type, '') = 'activity' or v.activity_event_id is not null)
        into is_activity
        from visits v where v.id = target_visit_id;

      if is_activity then
        raise log 'auto_update_visit_status_on_order: visit % is an activity, leaving its status alone', target_visit_id;
        return new;
      end if;

      update visits
         set status = 'productive',
             check_out_time = coalesce(check_out_time, new.created_at),
             no_order_reason = null,
             updated_at = now()
       where id = target_visit_id
         and status in ('planned', 'in-progress', 'unproductive');
    end if;
  end if;

  return new;
end;
$$;



--
-- Name: auto_update_visit_status_on_order_items(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_update_visit_status_on_order_items() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order RECORD;
  target_visit_id UUID;
BEGIN
  -- Look up the parent order
  SELECT id, status, visit_id, retailer_id, user_id, order_date, created_at
  INTO v_order
  FROM orders
  WHERE id = NEW.order_id;

  IF v_order.id IS NULL OR v_order.status <> 'confirmed' THEN
    RETURN NEW;
  END IF;

  -- Resolve target visit
  target_visit_id := v_order.visit_id;

  IF target_visit_id IS NULL AND v_order.retailer_id IS NOT NULL AND v_order.user_id IS NOT NULL THEN
    SELECT id INTO target_visit_id
    FROM visits
    WHERE retailer_id = v_order.retailer_id
      AND user_id = v_order.user_id
      AND planned_date = v_order.order_date
      AND status IN ('planned', 'in-progress', 'unproductive')
    ORDER BY created_at DESC
    LIMIT 1;
  END IF;

  IF target_visit_id IS NOT NULL THEN
    UPDATE visits
    SET 
      status = 'productive',
      check_out_time = COALESCE(check_out_time, v_order.created_at),
      no_order_reason = NULL,
      updated_at = NOW()
    WHERE id = target_visit_id
      AND status IN ('planned', 'in-progress', 'unproductive');
  END IF;

  RETURN NEW;
END;
$$;



--
-- Name: award_retailer_points(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.award_retailer_points(p_retailer_id uuid, p_activity text, p_points integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE rep uuid;
BEGIN
  SELECT COALESCE(created_by, user_id) INTO rep FROM public.retailers WHERE id = p_retailer_id;
  IF rep IS NULL THEN RETURN; END IF;
  INSERT INTO public.retailer_creation_points(retailer_id, user_id, activity, points)
  VALUES (p_retailer_id, rep, p_activity, p_points)
  ON CONFLICT (retailer_id, user_id, activity) DO NOTHING;
END; $$;



--
-- Name: backfill_retailer_payment_allocations(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.backfill_retailer_payment_allocations() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_retailer RECORD;
  v_collection RECORD;
  v_processed int := 0;
  v_skipped int := 0;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.user_roles
    WHERE user_id = auth.uid() AND role = 'admin'
  ) THEN
    RAISE EXCEPTION 'Only admins may run backfill';
  END IF;

  FOR v_collection IN
    SELECT c.id, c.retailer_id, c.amount
    FROM public.retailer_payment_collections c
    WHERE NOT EXISTS (
      SELECT 1 FROM public.retailer_payment_allocations a WHERE a.collection_id = c.id
    )
    ORDER BY c.created_at ASC
  LOOP
    BEGIN
      PERFORM public.apply_retailer_payment_fifo(
        v_collection.retailer_id, v_collection.amount, v_collection.id
      );
      v_processed := v_processed + 1;
    EXCEPTION WHEN OTHERS THEN
      v_skipped := v_skipped + 1;
    END;
  END LOOP;

  RETURN jsonb_build_object('processed', v_processed, 'skipped', v_skipped);
END;
$$;



--
-- Name: backfill_system_profile_permissions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.backfill_system_profile_permissions() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.is_system IS DISTINCT FROM true THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.profile_object_permissions
    (profile_id, object_name, permission_type, parent_module,
     can_read, can_create, can_edit, can_delete, can_view_all, can_modify_all)
  SELECT NEW.id, x.object_name, x.permission_type, MAX(x.parent_module),
         true, true, true, true, true, true
  FROM public.profile_object_permissions x
  GROUP BY x.object_name, x.permission_type
  ON CONFLICT (profile_id, object_name, permission_type) DO UPDATE
    SET can_read = true, can_create = true, can_edit = true,
        can_delete = true, can_view_all = true, can_modify_all = true;

  RETURN NEW;
END;
$$;



