-- Name: beat_has_history(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.beat_has_history(p_beat_id text) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (SELECT 1 FROM orders                    WHERE beat_id = p_beat_id)
      OR EXISTS (SELECT 1 FROM retailers                 WHERE beat_id = p_beat_id)
      OR EXISTS (SELECT 1 FROM retailer_beat_assignments WHERE beat_id = p_beat_id);
$$;



--
-- Name: beats_autofill_owner(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.beats_autofill_owner() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_name text;
BEGIN
  IF NEW.owner_id IS NULL AND NEW.created_by IS NOT NULL THEN NEW.owner_id := NEW.created_by; END IF;
  IF NEW.user_id  IS NULL AND NEW.created_by IS NOT NULL THEN NEW.user_id  := NEW.created_by; END IF;
  IF COALESCE(NEW.owner_name,'') = '' AND NEW.owner_id IS NOT NULL THEN
    SELECT full_name INTO v_name FROM public.profiles WHERE id = NEW.owner_id;
    NEW.owner_name := v_name;
  END IF;
  RETURN NEW;
END; $$;



--
-- Name: bump_unverified_order_count(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bump_unverified_order_count() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_verified boolean;
BEGIN
  IF NEW.retailer_id IS NULL THEN RETURN NEW; END IF;
  SELECT verified INTO v_verified FROM public.retailers WHERE id = NEW.retailer_id;
  IF v_verified IS DISTINCT FROM true THEN
    UPDATE public.retailers SET unverified_order_count = COALESCE(unverified_order_count, 0) + 1 WHERE id = NEW.retailer_id;
  END IF;
  RETURN NEW;
END; $$;



--
-- Name: calc_transaction_balance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calc_transaction_balance() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_prev_balance INTEGER;
  v_inward BOOLEAN;
  v_movement INTEGER;
BEGIN
  v_movement := COALESCE(NEW.balance_qty, 0);

  SELECT running_balance INTO v_prev_balance
  FROM public.distributor_inventory_transactions
  WHERE distributor_id = NEW.distributor_id
    AND product_id = NEW.product_id
    AND COALESCE(warehouse_id::text, '') = COALESCE(NEW.warehouse_id::text, '')
    AND id != NEW.id
  ORDER BY created_at DESC, id DESC
  LIMIT 1;

  v_prev_balance := COALESCE(v_prev_balance, 0);

  v_inward := NEW.transaction_type IN ('GRN', 'OPENING_STOCK', 'RETURN', 'ADJUSTMENT_IN', 'RELEASE');

  IF v_inward THEN
    NEW.running_balance := v_prev_balance + ABS(v_movement);
  ELSE
    NEW.running_balance := v_prev_balance - ABS(v_movement);
  END IF;

  RETURN NEW;
END;
$$;



--
-- Name: calculate_beat_adherence(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_beat_adherence(p_user_id uuid, p_start date, p_end date) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  planned_count INTEGER;
  actual_count INTEGER;
BEGIN
  SELECT COUNT(*) INTO planned_count
  FROM public.beat_plans bp
  WHERE bp.user_id = p_user_id AND bp.plan_date BETWEEN p_start AND p_end;
  
  SELECT COUNT(DISTINCT v.id) INTO actual_count
  FROM public.visits v
  JOIN public.beat_plans bp ON v.beat_id = bp.beat_id AND v.planned_date = bp.plan_date
  WHERE v.user_id = p_user_id AND v.planned_date BETWEEN p_start AND p_end
    AND v.status IN ('productive', 'unproductive');
  
  IF planned_count = 0 THEN RETURN 0; END IF;
  RETURN ROUND((actual_count::NUMERIC / planned_count::NUMERIC) * 100, 2);
END;
$$;



--
-- Name: calculate_leave_days(date, date, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_leave_days(p_start_date date, p_end_date date, p_leave_type_id uuid, p_is_half_day boolean DEFAULT false) RETURNS TABLE(total_days numeric, sandwich_days integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_sandwich_enabled BOOLEAN;
  v_base_days NUMERIC;
  v_sandwich_count INTEGER := 0;
BEGIN
  -- Get sandwich rule setting
  SELECT COALESCE(sandwich_rule_enabled, false) INTO v_sandwich_enabled
  FROM leave_policy WHERE leave_type_id = p_leave_type_id AND is_active = true;
  
  -- Calculate base days
  v_base_days := (p_end_date - p_start_date + 1);
  
  IF p_is_half_day THEN
    v_base_days := 0.5;
  END IF;
  
  -- If sandwich rule enabled, count weekends/holidays between
  IF v_sandwich_enabled AND NOT p_is_half_day THEN
    SELECT COUNT(*) INTO v_sandwich_count
    FROM generate_series(p_start_date, p_end_date, '1 day'::interval) d
    LEFT JOIN holidays h ON h.holiday_date = d::DATE
    WHERE EXTRACT(DOW FROM d) IN (0, 6) OR h.id IS NOT NULL;
  END IF;
  
  RETURN QUERY SELECT v_base_days, v_sandwich_count;
END;
$$;



--
-- Name: calculate_new_retailers(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
