--
-- Name: calculate_retailer_quality_score(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_retailer_quality_score(p_retailer_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  r public.retailers%ROWTYPE;
  score integer := 0;
  has_first_visit boolean := false;
  has_first_order boolean := false;
BEGIN
  SELECT * INTO r FROM public.retailers WHERE id = p_retailer_id;
  IF NOT FOUND THEN RETURN 0; END IF;

  IF r.name IS NOT NULL AND length(trim(r.name)) > 1 THEN score := score + 5; END IF;
  IF r.phone IS NOT NULL AND length(regexp_replace(r.phone, '\D', '', 'g')) >= 10 THEN score := score + 10; END IF;
  IF r.address IS NOT NULL AND length(trim(r.address)) > 3 THEN score := score + 5; END IF;
  IF r.category IS NOT NULL THEN score := score + 5; END IF;
  IF r.gst_number IS NOT NULL THEN score := score + 5; END IF;
  IF r.latitude IS NOT NULL AND r.longitude IS NOT NULL THEN score := score + 5; END IF;
  IF r.verification_address = true THEN score := score + 5; END IF;
  IF r.photo_url IS NOT NULL THEN score := score + 5; END IF;
  IF r.shop_front_visible = true THEN score := score + 5; END IF;
  IF r.owner_name IS NOT NULL THEN score := score + 5; END IF;
  IF r.alternate_phone IS NOT NULL THEN score := score + 3; END IF;
  IF r.distributor_id IS NOT NULL THEN score := score + 5; END IF;
  IF r.beat_id IS NOT NULL THEN score := score + 3; END IF;
  IF r.retail_type IS NOT NULL THEN score := score + 4; END IF;
  IF r.whatsapp_verified = true THEN score := score + 10; END IF;
  IF r.retailer_confirmed = true THEN score := score + 10; END IF;
  IF r.verified = true THEN score := score + 2; END IF;

  has_first_visit := r.first_visit_completed OR EXISTS (SELECT 1 FROM public.visits v WHERE v.retailer_id = r.id LIMIT 1);
  has_first_order := r.first_order_placed OR EXISTS (SELECT 1 FROM public.orders o WHERE o.retailer_id = r.id LIMIT 1);
  IF has_first_visit THEN score := score + 5; END IF;
  IF has_first_order THEN score := score + 5; END IF;

  score := greatest(0, least(100, score));

  UPDATE public.retailers
     SET verification_score = score,
         quality_last_calculated_at = now()
   WHERE id = p_retailer_id;

  RETURN score;
END;
$$;



--
-- Name: calculate_revenue_contribution(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_revenue_contribution(p_user_id uuid, p_start date, p_end date) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(SUM(total_amount), 0)
  FROM public.orders
  WHERE user_id = p_user_id
    AND status IN ('confirmed', 'delivered')
    AND order_date BETWEEN p_start AND p_end;
$$;



--
-- Name: calculate_user_kpi_actual(uuid, text, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_user_kpi_actual(p_user_id uuid, p_kpi_key text, p_start date, p_end date) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  CASE p_kpi_key
    WHEN 'revenue_contribution' THEN 
      RETURN calculate_revenue_contribution(p_user_id, p_start, p_end);
    WHEN 'new_retailer_addition' THEN 
      RETURN calculate_new_retailers(p_user_id, p_start, p_end);
    WHEN 'productive_visits' THEN 
      RETURN calculate_productive_visits(p_user_id, p_start, p_end);
    WHEN 'beat_adherence' THEN 
      RETURN calculate_beat_adherence(p_user_id, p_start, p_end);
    WHEN 'visit_completion_rate' THEN
      RETURN calculate_visit_completion_rate(p_user_id, p_start, p_end);
    ELSE 
      RETURN 0;
  END CASE;
END;
$$;



--
-- Name: calculate_visit_completion_rate(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_visit_completion_rate(p_user_id uuid, p_start date, p_end date) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  planned_count INTEGER;
  completed_count INTEGER;
BEGIN
  SELECT COUNT(*) INTO planned_count
  FROM public.visits
  WHERE user_id = p_user_id AND planned_date BETWEEN p_start AND p_end;
  
  SELECT COUNT(*) INTO completed_count
  FROM public.visits
  WHERE user_id = p_user_id 
    AND planned_date BETWEEN p_start AND p_end
    AND status IN ('productive', 'unproductive');
  
  IF planned_count = 0 THEN RETURN 0; END IF;
  RETURN ROUND((completed_count::NUMERIC / planned_count::NUMERIC) * 100, 2);
END;
$$;



