--
-- Name: can_access_object(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_access_object(user_id_param uuid, object_name_param text, permission_type text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  has_permission BOOLEAN := false;
  is_admin BOOLEAN;
BEGIN
  -- Admins have full access
  SELECT has_role(user_id_param, 'admin'::app_role) INTO is_admin;
  IF is_admin THEN
    RETURN true;
  END IF;
  
  -- Check profile permissions
  SELECT CASE permission_type
    WHEN 'read' THEN COALESCE(pop.can_read, false)
    WHEN 'create' THEN COALESCE(pop.can_create, false)
    WHEN 'edit' THEN COALESCE(pop.can_edit, false)
    WHEN 'delete' THEN COALESCE(pop.can_delete, false)
    WHEN 'view_all' THEN COALESCE(pop.can_view_all, false)
    WHEN 'modify_all' THEN COALESCE(pop.can_modify_all, false)
    ELSE false
  END INTO has_permission
  FROM profile_object_permissions pop
  JOIN user_profiles up ON up.profile_id = pop.profile_id
  WHERE up.user_id = user_id_param
    AND pop.object_name = object_name_param;
  
  RETURN COALESCE(has_permission, false);
END;
$$;



--
-- Name: can_access_packing_list(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_access_packing_list(_packing_list_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_dist_id uuid;
BEGIN
  v_dist_id := public.get_distributor_id_for_auth_user();
  IF v_dist_id IS NULL THEN RETURN true; END IF;
  RETURN EXISTS (SELECT 1 FROM public.packing_lists pl WHERE pl.id = _packing_list_id AND (pl.distributor_id = v_dist_id OR pl.distributor_id IN (SELECT id FROM public.distributors WHERE parent_id = v_dist_id)));
END; $$;



--
-- Name: can_backdate_order(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_backdate_order(p_date date) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_enabled  boolean;
  v_max_days integer;
BEGIN
  SELECT backdate_enabled, backdate_max_days
    INTO v_enabled, v_max_days
    FROM public.operations_config
   WHERE id = 1;

  IF NOT COALESCE(v_enabled, false) THEN
    RETURN false;
  END IF;

  IF NOT public.user_has_permission(auth.uid(), 'order_backdate', 'can_create') THEN
    RETURN false;
  END IF;

  IF p_date > CURRENT_DATE THEN
    RETURN false;
  END IF;

  IF p_date >= (CURRENT_DATE - (COALESCE(v_max_days, 0) || ' days')::interval)::date THEN
    RETURN true;
  END IF;

  RETURN EXISTS (
    SELECT 1
      FROM public.order_backdate_date_grants
     WHERE user_id = auth.uid()
       AND order_date = p_date
  );
END;
$$;



--
-- Name: can_delete_beat(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_delete_beat(p_beat_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  reasons text[] := ARRAY[]::text[];
  cnt int;
BEGIN
  SELECT count(*) INTO cnt FROM public.retailers
  WHERE beat_id = p_beat_id;
  IF cnt > 0 THEN reasons := reasons ||
    format('%s retailer(s) currently assigned', cnt); END IF;

  SELECT count(*) INTO cnt FROM public.retailer_beat_assignments
  WHERE beat_id = p_beat_id;
  IF cnt > 0 THEN reasons := reasons ||
    format('%s historical retailer assignment(s)', cnt); END IF;

  SELECT count(*) INTO cnt
  FROM public.visits v
  JOIN public.retailers r ON r.id = v.retailer_id
  WHERE r.beat_id = p_beat_id;
  IF cnt > 0 THEN reasons := reasons ||
    format('%s visit record(s)', cnt); END IF;

  IF to_regclass('public.orders') IS NOT NULL THEN
    BEGIN
      EXECUTE 'SELECT count(*) FROM public.orders WHERE beat_id = $1'
      INTO cnt USING p_beat_id;
      IF cnt > 0 THEN reasons := reasons ||
        format('%s order record(s)', cnt); END IF;
    EXCEPTION WHEN undefined_column THEN NULL;
    END;
  END IF;

  SELECT count(*) INTO cnt FROM public.beat_plans
  WHERE beat_id = p_beat_id;
  IF cnt > 0 THEN reasons := reasons ||
    format('%s beat plan record(s)', cnt); END IF;

  SELECT count(*) INTO cnt FROM public.daily_beat_plans
  WHERE beat_id = p_beat_id;
  IF cnt > 0 THEN reasons := reasons ||
    format('%s tour-plan record(s)', cnt); END IF;

  SELECT count(*) INTO cnt FROM public.joint_sales_sessions
  WHERE beat_id = p_beat_id;
  IF cnt > 0 THEN reasons := reasons ||
    format('%s joint sales session(s)', cnt); END IF;

  SELECT count(*) INTO cnt FROM public.route_execution_history
  WHERE beat_id = p_beat_id;
  IF cnt > 0 THEN reasons := reasons ||
    format('%s route execution record(s)', cnt); END IF;

  RETURN jsonb_build_object(
    'deletable', array_length(reasons, 1) IS NULL,
    'reasons', reasons
  );
END
$_$;



--
-- Name: can_edit_order(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_edit_order(p_order_id uuid, p_actor uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cfg operations_config%ROWTYPE;
  v_order orders%ROWTYPE;
  v_uid uuid := p_actor;
BEGIN
  IF v_uid IS NULL THEN RETURN false; END IF;

  SELECT * INTO v_cfg FROM operations_config WHERE id = 1;
  IF NOT FOUND OR COALESCE(v_cfg.edit_enabled, false) = false THEN
    RETURN false;
  END IF;

  IF NOT public.user_has_permission(v_uid, 'order_edit', 'can_edit') THEN
    RETURN false;
  END IF;

  SELECT * INTO v_order FROM orders WHERE id = p_order_id;
  IF NOT FOUND THEN RETURN false; END IF;

  IF v_cfg.edit_who = 'own' THEN
    IF v_order.user_id <> v_uid THEN RETURN false; END IF;
  ELSIF v_cfg.edit_who = 'own_team' THEN
    IF v_order.user_id <> v_uid AND NOT public.is_subordinate_of(v_uid, v_order.user_id) THEN
      RETURN false;
    END IF;
  ELSIF v_cfg.edit_who = 'view_all' THEN
    IF NOT public.user_has_permission(v_uid, 'order_edit', 'can_view_all') THEN
      RETURN false;
    END IF;
  END IF;

  IF v_cfg.edit_lock_point = 'invoiced' THEN
    IF v_order.invoice_generated_at IS NOT NULL THEN RETURN false; END IF;
  ELSIF v_cfg.edit_lock_point = 'dispatched' THEN
    IF v_order.dispatched_at IS NOT NULL THEN RETURN false; END IF;
  ELSIF v_cfg.edit_lock_point = 'same_day' THEN
    IF v_order.created_at::date <> current_date THEN RETURN false; END IF;
  ELSIF v_cfg.edit_lock_point = 'hours' THEN
    IF now() - v_order.created_at > (COALESCE(v_cfg.edit_lock_hours, 0) || ' hours')::interval THEN
      RETURN false;
    END IF;
  END IF;

  IF COALESCE(v_cfg.edit_max_edits, 0) > 0
     AND COALESCE(v_order.edit_count, 0) >= v_cfg.edit_max_edits THEN
    RETURN false;
  END IF;

  RETURN true;
END;
$$;



--
-- Name: can_view_distributor(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_view_distributor(_distributor_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (SELECT 1 FROM public.distributors WHERE id = _distributor_id AND (id = public.get_distributor_id_for_auth_user() OR parent_id = public.get_distributor_id_for_auth_user()))
$$;



--
-- Name: can_view_employee(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_view_employee(_target_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Own record
  IF auth.uid() = _target_user_id THEN
    RETURN true;
  END IF;
  
  -- System admin
  IF is_system_admin(auth.uid()) THEN
    RETURN true;
  END IF;
  
  -- Check if target user is a subordinate (any level) of current user
  IF EXISTS (
    SELECT 1 FROM public.get_all_subordinates(auth.uid()) 
    WHERE subordinate_user_id = _target_user_id
  ) THEN
    RETURN true;
  END IF;
  
  RETURN false;
END;
$$;



--
-- Name: can_view_profile(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_view_profile(_target_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN (auth.uid() = _target_user_id) 
    OR is_system_admin(auth.uid());
END;
$$;



--
-- Name: can_view_retailer_ledger(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_view_retailer_ledger(p_retailer_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    public.is_system_admin(auth.uid())
    OR public.user_has_permission(auth.uid(), 'admin_credit_mgmt', 'can_read')
    OR EXISTS (SELECT 1 FROM public.retailers r
               WHERE r.id = p_retailer_id
                 AND (r.user_id = auth.uid()
                      OR public.user_has_beat_access(auth.uid(), r.beat_id)))
    OR EXISTS (SELECT 1 FROM public.visits v
               WHERE v.retailer_id = p_retailer_id AND v.user_id = auth.uid())
    OR EXISTS (SELECT 1 FROM public.orders o
               WHERE o.retailer_id = p_retailer_id AND o.user_id = auth.uid());
$$;



--
-- Name: cancel_order_atomic(uuid, text, uuid, text, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_order_atomic(p_order_id uuid, p_reason text, p_cancelled_by uuid, p_settlement_method text DEFAULT NULL::text, p_settlement_amount numeric DEFAULT 0, p_van_stock_action text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order RECORD;
  v_visit RECORD;
  v_credit_reversed NUMERIC := 0;
  v_gamification_points_reversed NUMERIC := 0;
  v_loyalty_points_reversed NUMERIC := 0;
  v_invoice_cancelled BOOLEAN := false;
  v_visit_reverted BOOLEAN := false;
  v_other_confirmed_orders INT;
  v_gam_row RECORD;
  v_loyalty_row RECORD;
  v_item RECORD;
  v_van_stock RECORD;
  v_van_stock_item RECORD;
  v_invoice RECORD;
  v_cn_id uuid;
  v_cn_number text;
  v_cn_prefix text;
  v_cn_count int;
  v_fy_start int;
  v_fy_end int;
  v_now timestamptz := now();
  v_kpi_id uuid;
  v_settlement_recorded boolean := false;
  v_new_pending numeric;
  v_alloc_freed numeric := 0;
  v_paid_settle numeric := 0;
  v_carry_leftover numeric := 0;
  v_left numeric := 0;
  v_cf_collection uuid;
  v_alloc RECORD;
BEGIN
  SELECT * INTO v_order FROM orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order not found');
  END IF;

  IF v_order.status = 'cancelled' THEN
    v_new_pending := public.recompute_retailer_pending(v_order.retailer_id);
    RETURN jsonb_build_object('success', true, 'already_cancelled', true, 'retailer_pending', v_new_pending);
  END IF;

  IF v_order.status NOT IN ('confirmed', 'pending') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Cannot cancel order with status: ' || v_order.status);
  END IF;

  UPDATE orders SET
    status = 'cancelled',
    cancelled_at = v_now,
    cancellation_reason = p_reason,
    cancelled_by = p_cancelled_by,
    updated_at = v_now
  WHERE id = p_order_id;

  SELECT * INTO v_invoice FROM invoices WHERE order_id = p_order_id AND status != 'cancelled' LIMIT 1;
  IF FOUND THEN
    UPDATE invoices SET
      status = 'cancelled',
      cancelled_at = v_now,
      cancellation_reason = p_reason,
      updated_at = v_now
    WHERE id = v_invoice.id;
    v_invoice_cancelled := true;
  END IF;

  IF v_order.is_credit_order AND COALESCE(v_order.credit_pending_amount, 0) > 0 THEN
    v_credit_reversed := v_order.credit_pending_amount;
    INSERT INTO credit_ledger (retailer_id, amount, type, reference_id, created_by)
    VALUES (v_order.retailer_id, -v_credit_reversed, 'order_cancel', p_order_id, p_cancelled_by);
  END IF;

  SELECT COALESCE(SUM(amount_applied), 0) INTO v_alloc_freed
    FROM retailer_payment_allocations WHERE order_id = p_order_id;
  v_paid_settle := CASE WHEN v_alloc_freed > 0
                        THEN v_alloc_freed
                        ELSE COALESCE(v_order.credit_paid_amount, 0) END;

  IF v_order.is_credit_order AND v_paid_settle > 0 THEN
    IF p_settlement_method = 'carry_forward' THEN
      IF v_alloc_freed > 0 THEN
        FOR v_alloc IN
          SELECT collection_id, SUM(amount_applied) AS amt
          FROM retailer_payment_allocations
          WHERE order_id = p_order_id
          GROUP BY collection_id
        LOOP
          v_left := public.reflow_allocation_fifo(
                      v_order.retailer_id, v_alloc.collection_id, v_alloc.amt, p_order_id);
          v_carry_leftover := v_carry_leftover + v_left;
        END LOOP;
        DELETE FROM retailer_payment_allocations WHERE order_id = p_order_id;
      ELSE
        INSERT INTO retailer_payment_collections
          (retailer_id, amount, payment_method, collected_by_user_id, notes)
        VALUES
          (v_order.retailer_id, v_paid_settle, 'carry_forward', p_cancelled_by,
           'Carry-forward from cancelled order ' || COALESCE(v_order.invoice_number, p_order_id::text))
        RETURNING id INTO v_cf_collection;

        v_carry_leftover := public.reflow_allocation_fifo(
                              v_order.retailer_id, v_cf_collection, v_paid_settle, p_order_id);
      END IF;

      IF v_carry_leftover > 0 THEN
        INSERT INTO credit_ledger (retailer_id, amount, type, reference_id, created_by)
        VALUES (v_order.retailer_id, -v_carry_leftover, 'cancel_carry_forward', p_order_id, p_cancelled_by);
      END IF;
      v_settlement_recorded := true;

    ELSIF p_settlement_method = 'refund' THEN
      DELETE FROM retailer_payment_allocations WHERE order_id = p_order_id;
      INSERT INTO credit_ledger (retailer_id, amount, type, reference_id, created_by)
      VALUES (v_order.retailer_id, -v_paid_settle, 'cancel_refund', p_order_id, p_cancelled_by);
      v_settlement_recorded := true;

    ELSIF p_settlement_method = 'credit_note' THEN
      DELETE FROM retailer_payment_allocations WHERE order_id = p_order_id;

      v_fy_start := CASE WHEN EXTRACT(MONTH FROM v_now) >= 4
                         THEN EXTRACT(YEAR FROM v_now)::int
                         ELSE EXTRACT(YEAR FROM v_now)::int - 1 END;
      v_fy_end := v_fy_start + 1;
      v_cn_prefix := 'CN/' || RIGHT(v_fy_start::text, 2) || '-' || RIGHT(v_fy_end::text, 2) || '/';
      SELECT COUNT(*) INTO v_cn_count FROM credit_notes WHERE credit_note_number LIKE v_cn_prefix || '%';
      v_cn_number := v_cn_prefix || LPAD((v_cn_count + 1)::text, 3, '0');

      INSERT INTO credit_notes (
        credit_note_number, credit_note_date, retailer_id, retailer_name,
        reason, reason_notes, sub_total, sgst_total, cgst_total,
        total_amount, status, created_by
      ) VALUES (
        v_cn_number, v_now::date, v_order.retailer_id,
        (SELECT name FROM retailers WHERE id = v_order.retailer_id),
        'order_cancellation',
        'Cancellation of order ' || COALESCE(v_order.invoice_number, p_order_id::text) || ': ' || p_reason,
        v_paid_settle, 0, 0, v_paid_settle, 'issued', p_cancelled_by
      ) RETURNING id INTO v_cn_id;

      FOR v_item IN SELECT * FROM order_items WHERE order_id = p_order_id LOOP
        INSERT INTO credit_note_items (
          credit_note_id, original_order_id, original_invoice_number, product_id,
          product_name, hsn_code, unit, quantity, rate, total,
          taxable_amount, sgst_amount, cgst_amount
        ) VALUES (
          v_cn_id, p_order_id, v_order.invoice_number, v_item.product_id,
          v_item.product_name, v_item.hsn_code, v_item.unit,
          v_item.quantity, v_item.rate, v_item.total,
          COALESCE(v_item.total - COALESCE(v_item.sgst_amount,0) - COALESCE(v_item.cgst_amount,0), v_item.total),
          COALESCE(v_item.sgst_amount, 0), COALESCE(v_item.cgst_amount, 0)
        );
      END LOOP;
      v_settlement_recorded := true;

    ELSE
      DELETE FROM retailer_payment_allocations WHERE order_id = p_order_id;
      INSERT INTO credit_ledger (retailer_id, amount, type, reference_id, created_by)
      VALUES (v_order.retailer_id, -v_paid_settle, 'cancel_carry_forward', p_order_id, p_cancelled_by);
      v_settlement_recorded := true;
    END IF;
  END IF;

  IF p_van_stock_action IS NOT NULL AND p_van_stock_action <> 'not_collected' THEN
    SELECT * INTO v_van_stock FROM van_stock
      WHERE user_id = v_order.user_id AND stock_date = v_order.order_date
      ORDER BY created_at DESC LIMIT 1;
    IF FOUND THEN
      FOR v_item IN SELECT product_id, product_name, quantity, unit FROM order_items WHERE order_id = p_order_id LOOP
        SELECT * INTO v_van_stock_item FROM van_stock_items
          WHERE van_stock_id = v_van_stock.id AND product_id = v_item.product_id::text
          LIMIT 1;
        IF FOUND THEN
          IF p_van_stock_action = 'collected' THEN
            UPDATE van_stock_items SET
              ordered_qty = GREATEST(0, COALESCE(ordered_qty,0) - v_item.quantity::int),
              left_qty    = COALESCE(left_qty,0) + v_item.quantity::int,
              updated_at  = v_now
            WHERE id = v_van_stock_item.id;
          ELSIF p_van_stock_action = 'damaged' THEN
            UPDATE van_stock_items SET
              ordered_qty = GREATEST(0, COALESCE(ordered_qty,0) - v_item.quantity::int),
              updated_at  = v_now
            WHERE id = v_van_stock_item.id;
          END IF;
        END IF;
        IF p_van_stock_action = 'damaged' THEN
          INSERT INTO van_stock_adjustments (
            van_stock_id, adjustment_type, product_id, product_name,
            quantity, reason, created_by
          ) VALUES (
            v_van_stock.id, 'damage', v_item.product_id::text, v_item.product_name,
            v_item.quantity::int,
            'Order ' || COALESCE(v_order.invoice_number, p_order_id::text) || ' cancelled (write-off): ' || p_reason,
            p_cancelled_by
          );
        END IF;
      END LOOP;
    END IF;
  END IF;

  UPDATE retailers SET
    last_order_date = (
      SELECT MAX(order_date) FROM orders
      WHERE retailer_id = v_order.retailer_id
        AND status = 'confirmed'
        AND id != p_order_id
    ),
    updated_at = v_now
  WHERE id = v_order.retailer_id;

  IF v_order.visit_id IS NOT NULL THEN
    SELECT * INTO v_visit FROM visits WHERE id = v_order.visit_id;
    IF FOUND AND v_visit.status = 'productive' AND COALESCE(v_visit.completion_source, 'order') = 'order' THEN
      SELECT COUNT(*) INTO v_other_confirmed_orders
      FROM orders
      WHERE visit_id = v_order.visit_id AND id != p_order_id AND status = 'confirmed';
      IF v_other_confirmed_orders = 0 THEN
        UPDATE visits SET status='planned', completion_source=NULL, updated_at=v_now WHERE id = v_order.visit_id;
        v_visit_reverted := true;
      END IF;
    END IF;
  END IF;

  FOR v_gam_row IN
    SELECT game_id, user_id, action_id, SUM(points) AS points_to_reverse
    FROM gamification_points
    WHERE reference_id = p_order_id AND reference_type = 'order' AND points > 0
    GROUP BY game_id, user_id, action_id
  LOOP
    INSERT INTO gamification_points (game_id, user_id, action_id, points, reference_type, reference_id, earned_at, metadata)
    VALUES (v_gam_row.game_id, v_gam_row.user_id, v_gam_row.action_id,
            -v_gam_row.points_to_reverse, 'order', p_order_id, v_now,
            jsonb_build_object('type','order_cancellation_reversal','order_id', p_order_id));
    v_gamification_points_reversed := v_gamification_points_reversed + v_gam_row.points_to_reverse;
  END LOOP;

  FOR v_loyalty_row IN
    SELECT program_id, retailer_id, action_id,
           COALESCE(awarded_by_user_id, p_cancelled_by) AS awarded_by_user_id,
           SUM(points) AS points_to_reverse
    FROM retailer_loyalty_points
    WHERE reference_id = p_order_id AND points > 0
    GROUP BY program_id, retailer_id, action_id, COALESCE(awarded_by_user_id, p_cancelled_by)
  LOOP
    INSERT INTO retailer_loyalty_points (program_id, retailer_id, action_id, points, reference_type, reference_id,
                                         earned_at, awarded_by_user_id, metadata, description, visit_id)
    VALUES (v_loyalty_row.program_id, v_loyalty_row.retailer_id, v_loyalty_row.action_id,
            -v_loyalty_row.points_to_reverse, 'order', p_order_id, v_now, v_loyalty_row.awarded_by_user_id,
            jsonb_build_object('type','order_cancellation_reversal','order_id', p_order_id),
            'Order cancellation reversal', v_order.visit_id);
    v_loyalty_points_reversed := v_loyalty_points_reversed + v_loyalty_row.points_to_reverse;
  END LOOP;

  UPDATE gamification_retailer_sequences
    SET consecutive_orders = GREATEST(0, consecutive_orders - 1), updated_at = v_now
    WHERE user_id = v_order.user_id AND retailer_id = v_order.retailer_id;

  UPDATE gamification_daily_tracking
    SET count = GREATEST(0, count - 1), updated_at = v_now
    WHERE user_id = v_order.user_id AND tracking_date = v_order.order_date;

  SELECT id INTO v_kpi_id FROM target_kpi_definitions WHERE kpi_key = 'revenue_contribution' LIMIT 1;
  IF v_kpi_id IS NOT NULL AND v_order.user_id IS NOT NULL THEN
    UPDATE user_period_targets upt
    SET actual_value = public.calculate_revenue_contribution(v_order.user_id, upt.period_start, upt.period_end),
        achievement_percent = CASE WHEN target_value > 0
          THEN ROUND((public.calculate_revenue_contribution(v_order.user_id, upt.period_start, upt.period_end) / target_value) * 100, 2)
          ELSE 0 END,
        last_calculated_at = v_now
    WHERE upt.user_id = v_order.user_id
      AND upt.kpi_id = v_kpi_id
      AND v_order.order_date BETWEEN upt.period_start AND upt.period_end;
  END IF;

  v_new_pending := public.recompute_retailer_pending(v_order.retailer_id);

  INSERT INTO order_cancellation_log (order_id, reason, cancelled_by, reversal_summary)
  VALUES (
    p_order_id, p_reason, p_cancelled_by,
    jsonb_build_object(
      'credit_reversed', v_credit_reversed,
      'paid_settled', v_paid_settle,
      'carry_leftover', v_carry_leftover,
      'gamification_points_reversed', v_gamification_points_reversed,
      'loyalty_points_reversed', v_loyalty_points_reversed,
      'invoice_cancelled', v_invoice_cancelled,
      'visit_reverted', v_visit_reverted,
      'retailer_id', v_order.retailer_id,
      'order_date', v_order.order_date,
      'settlement_method', p_settlement_method,
      'settlement_amount', COALESCE(p_settlement_amount, 0),
      'settlement_recorded', v_settlement_recorded,
      'credit_note_id', v_cn_id,
      'credit_note_number', v_cn_number,
      'van_stock_action', p_van_stock_action,
      'retailer_pending_after', v_new_pending
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'credit_reversed', v_credit_reversed,
    'paid_settled', v_paid_settle,
    'carry_leftover', v_carry_leftover,
    'gamification_points_reversed', v_gamification_points_reversed,
    'loyalty_points_reversed', v_loyalty_points_reversed,
    'invoice_cancelled', v_invoice_cancelled,
    'visit_reverted', v_visit_reverted,
    'retailer_id', v_order.retailer_id,
    'order_date', v_order.order_date,
    'settlement_method', p_settlement_method,
    'settlement_amount', COALESCE(p_settlement_amount, 0),
    'settlement_recorded', v_settlement_recorded,
    'credit_note_id', v_cn_id,
    'credit_note_number', v_cn_number,
    'van_stock_action', p_van_stock_action,
    'retailer_pending', v_new_pending
  );
END;
$$;



--
-- Name: capture_db_health_snapshot(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.capture_db_health_snapshot(p_source text DEFAULT 'manual'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_id uuid;
BEGIN
  IF auth.uid() IS NOT NULL
     AND NOT public.user_has_permission(auth.uid(), 'admin_db_health', 'can_read') THEN
    RAISE EXCEPTION 'Your profile does not have permission to capture a DB health snapshot';
  END IF;
  SELECT public._capture_db_health_snapshot_impl(p_source) INTO v_id;
  RETURN v_id;
END $$;



--
-- Name: check_duplicate_competitor(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_duplicate_competitor(competitor_name_param text) RETURNS TABLE(is_duplicate boolean, competitor_id uuid, competitor_name text, competitor_image_url text, product_details text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT 
    TRUE as is_duplicate,
    ci.id as competitor_id,
    ci.competitor_name,
    ci.competitor_image_url,
    ci.product_details
  FROM public.competition_insights ci
  WHERE LOWER(TRIM(ci.competitor_name)) = LOWER(TRIM(competitor_name_param))
  LIMIT 1;
$$;



--
-- Name: check_rls_drift(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_rls_drift() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE r record; v_drift int := 0; v_missing text[];
BEGIN
  FOR r IN SELECT table_name, policy_names FROM public.rls_baseline LOOP
    IF EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'public' AND c.relname = r.table_name AND c.relkind = 'r') THEN
      IF NOT (SELECT relrowsecurity FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'public' AND c.relname = r.table_name) THEN
        EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', r.table_name);
        INSERT INTO public.securityaudit_events(event_type, schema_name, table_name, object_identity, ddl_command, session_user_name) VALUES ('RLS_DRIFT_REENABLED', 'public', r.table_name, format('public.%I', r.table_name), 'auto re-enabled RLS (was disabled)', session_user);
        v_drift := v_drift + 1;
      END IF;
      SELECT array_agg(pn) INTO v_missing FROM unnest(r.policy_names) pn WHERE pn NOT IN (SELECT policyname FROM pg_policies WHERE schemaname = 'public' AND tablename = r.table_name);
      IF v_missing IS NOT NULL AND array_length(v_missing, 1) > 0 THEN
        INSERT INTO public.securityaudit_events(event_type, schema_name, table_name, policy_name, object_identity, ddl_command, session_user_name) VALUES ('RLS_POLICY_MISSING', 'public', r.table_name, array_to_string(v_missing, ','), format('public.%I', r.table_name), 'baseline policy missing', session_user);
        v_drift := v_drift + 1;
      END IF;
    END IF;
  END LOOP;
  RETURN v_drift;
END $$;



--
-- Name: clamp_inventory_batch_available(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clamp_inventory_batch_available() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_max INTEGER;
BEGIN
  v_max := GREATEST(0, COALESCE(NEW.quantity,0) - COALESCE(NEW.reserved_qty,0));
  IF NEW.available_qty IS NULL OR NEW.available_qty > v_max THEN
    NEW.available_qty := v_max;
  END IF;
  IF NEW.available_qty < 0 THEN
    NEW.available_qty := 0;
  END IF;
  RETURN NEW;
END;
$$;



--
-- Name: cleanup_expired_coverage(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_expired_coverage() RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  UPDATE beat_coverage_assignments
     SET is_active = false, updated_at = now()
   WHERE is_active = true AND end_date < CURRENT_DATE;

  UPDATE beat_user_access
     SET is_active = false, updated_at = now()
   WHERE is_active = true AND effective_to IS NOT NULL AND effective_to < now();

  UPDATE coverage_permission_assignments
     SET is_active = false
   WHERE is_active = true AND end_date < CURRENT_DATE;
$$;



--
-- Name: cleanup_expired_insights(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_expired_insights() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  DELETE FROM ai_insights 
  WHERE expires_at IS NOT NULL 
    AND expires_at < now();
  
  -- Also delete old dismissed insights (older than 7 days)
  DELETE FROM ai_insights 
  WHERE is_dismissed = true 
    AND created_at < now() - interval '7 days';
END;
$$;



--
-- Name: cleanup_expired_recommendations(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_expired_recommendations() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE public.recommendations
  SET is_active = false
  WHERE expires_at < now() AND is_active = true;
END;
$$;



--
-- Name: cleanup_expired_reset_tokens(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_expired_reset_tokens() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  DELETE FROM public.password_reset_tokens
  WHERE expires_at < now() OR used = true;
END;
$$;



--
-- Name: cleanup_old_execution_logs(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_old_execution_logs() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  DELETE FROM public.push_content_execution_log
  WHERE execution_time < NOW() - INTERVAL '30 days';
END;
$$;



--
-- Name: create_approval_request(text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_approval_request(p_entity_type text, p_entity_id uuid, p_requester_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_request_id uuid;
  v_total_levels int := 0;
  v_max_levels int := 10;
BEGIN
  SELECT ac.max_levels INTO v_max_levels
  FROM approval_config ac
  WHERE ac.entity_type = p_entity_type
  LIMIT 1;
  v_max_levels := COALESCE(v_max_levels, 10);

  SELECT COUNT(*) INTO v_total_levels
  FROM get_reporting_chain(p_requester_id)
  WHERE level <= v_max_levels;

  IF v_total_levels = 0 THEN
    IF p_entity_type = 'leave' THEN
      UPDATE leave_applications SET status = 'approved' WHERE id = p_entity_id;
    ELSIF p_entity_type = 'regularization' THEN
      UPDATE regularization_requests SET status = 'approved', approved_at = now() WHERE id = p_entity_id;
    END IF;
    RETURN NULL;
  END IF;

  INSERT INTO approval_requests (entity_type, entity_id, requester_id, current_level, total_levels, status)
  VALUES (p_entity_type, p_entity_id, p_requester_id, 1, v_total_levels, 'pending')
  RETURNING id INTO v_request_id;

  INSERT INTO approval_steps (approval_request_id, level, approver_id, status)
  SELECT v_request_id, rc.level, rc.manager_id, 'pending'
  FROM get_reporting_chain(p_requester_id) rc
  WHERE rc.level <= v_max_levels;

  INSERT INTO approval_audit_log (approval_request_id, entity_type, entity_id, action, performed_by, level)
  VALUES (v_request_id, p_entity_type, p_entity_id, 'submitted', p_requester_id, 0);

  RETURN v_request_id;
END;
$$;



--
-- Name: create_approval_workflow(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_approval_workflow(user_id_param uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    approver_rec RECORD;
BEGIN
    -- Insert approval records for each level
    FOR approver_rec IN 
        SELECT user_id as approver_id, approver_level 
        FROM public.approvers 
        WHERE is_active = true 
        ORDER BY approver_level
    LOOP
        INSERT INTO public.user_approvals (user_id, approver_id, approval_level)
        VALUES (user_id_param, approver_rec.approver_id, approver_rec.approver_level);
    END LOOP;
END;
$$;



--
-- Name: create_invoice_on_order_confirmed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_invoice_on_order_confirmed() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_invoice_id uuid; v_invoice_no text; v_company_id uuid; v_sub_total numeric := 0; v_total_tax numeric := 0; v_total_amount numeric := 0; v_existing uuid;
BEGIN
  IF NEW.status IS DISTINCT FROM 'confirmed' THEN RETURN NEW; END IF;
  IF TG_OP = 'UPDATE' AND OLD.status = 'confirmed' THEN RETURN NEW; END IF;
  BEGIN
    SELECT id INTO v_existing FROM public.invoices WHERE order_id = NEW.id LIMIT 1;
    IF v_existing IS NOT NULL THEN RETURN NEW; END IF;
    v_invoice_no := public.generate_invoice_number();
    SELECT id INTO v_company_id FROM public.companies ORDER BY created_at NULLS LAST LIMIT 1;
    SELECT COALESCE(SUM(oi.quantity * oi.rate), 0), COALESCE(SUM(COALESCE(oi.cgst_amount,0) + COALESCE(oi.sgst_amount,0) + COALESCE(oi.igst_amount,0) + COALESCE(oi.cess_amount,0)), 0)
      INTO v_sub_total, v_total_tax FROM public.order_items oi WHERE oi.order_id = NEW.id;
    v_total_amount := COALESCE(NEW.total_amount, v_sub_total + v_total_tax);
    INSERT INTO public.invoices (invoice_number, company_id, customer_id, order_id, invoice_date, sub_total, total_tax, total_amount, status, created_by, owner_id_snapshot)
    VALUES (v_invoice_no, v_company_id, NULL, NEW.id, COALESCE(NEW.order_date::date, CURRENT_DATE), v_sub_total, v_total_tax, v_total_amount, 'generated', NEW.user_id, NEW.user_id)
    RETURNING id INTO v_invoice_id;
    INSERT INTO public.invoice_items (invoice_id, description, hsn_sac, quantity, unit, price_per_unit, gst_rate, taxable_amount, cgst_amount, sgst_amount, total_amount)
    SELECT v_invoice_id, oi.product_name, oi.hsn_code, oi.quantity, oi.unit, oi.rate,
      COALESCE(oi.tax_rate_snapshot, COALESCE(oi.cgst_rate,0) + COALESCE(oi.sgst_rate,0) + COALESCE(oi.igst_rate,0), 0),
      oi.quantity * oi.rate, COALESCE(oi.cgst_amount,0), COALESCE(oi.sgst_amount,0),
      (oi.quantity * oi.rate) + COALESCE(oi.cgst_amount,0) + COALESCE(oi.sgst_amount,0) + COALESCE(oi.igst_amount,0) + COALESCE(oi.cess_amount,0)
    FROM public.order_items oi WHERE oi.order_id = NEW.id;
    IF NEW.invoice_number IS NULL OR NEW.invoice_number = '' THEN UPDATE public.orders SET invoice_number = v_invoice_no WHERE id = NEW.id; END IF;
  EXCEPTION WHEN OTHERS THEN RAISE WARNING 'create_invoice_on_order_confirmed failed for order %: %', NEW.id, SQLERRM;
  END;
  RETURN NEW;
END; $$;



--
-- Name: create_report_subscription(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_report_subscription(p_definition jsonb, p_subscription jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_def_id UUID;
  v_sub_id UUID;
  v_uid UUID := auth.uid();
BEGIN
  IF NOT public.is_admin_or_manager() THEN
    RAISE EXCEPTION 'Only admins/managers can create report subscriptions';
  END IF;

  INSERT INTO public.report_definitions (name, dataset_key, layout, config, created_by)
  VALUES (
    p_definition->>'name',
    p_definition->>'dataset_key',
    p_definition->>'layout',
    COALESCE(p_definition->'config', '{}'::jsonb),
    v_uid
  ) RETURNING id INTO v_def_id;

  INSERT INTO public.report_subscriptions (
    name, report_definition_id, cadence, fire_day, fire_time, timezone,
    recipient_user_ids, attachment_format, push_to_phone, scope, status, created_by,
    recipient_mode
  )
  VALUES (
    p_subscription->>'name',
    v_def_id,
    p_subscription->>'cadence',
    p_subscription->>'fire_day',
    COALESCE((p_subscription->>'fire_time')::time, '08:00'::time),
    COALESCE(p_subscription->>'timezone', 'Asia/Kolkata'),
    COALESCE(
      ARRAY(SELECT jsonb_array_elements_text(p_subscription->'recipient_user_ids'))::uuid[],
      '{}'::uuid[]
    ),
    COALESCE(p_subscription->>'attachment_format', 'excel'),
    COALESCE((p_subscription->>'push_to_phone')::boolean, true),
    COALESCE(p_subscription->>'scope', 'shared'),
    COALESCE(p_subscription->>'status', 'active'),
    v_uid,
    COALESCE(p_subscription->>'recipient_mode', 'named_users')
  ) RETURNING id INTO v_sub_id;

  RETURN v_sub_id;
END;
$$;



--
-- Name: credit_ledger_sync_pending_amount(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.credit_ledger_sync_pending_amount() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE retailers
  SET pending_amount = GREATEST(0, COALESCE(pending_amount, 0) + NEW.amount),
      updated_at = now()
  WHERE id = NEW.retailer_id;
  RETURN NEW;
END;
$$;



--
-- Name: deactivate_beat(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.deactivate_beat(p_beat_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_user uuid := auth.uid();
BEGIN
  UPDATE public.beats
     SET is_active = false, deactivated_at = now(), deactivated_by = v_user, updated_at = now(), updated_by = v_user
   WHERE beat_id = p_beat_id;
  INSERT INTO public.beat_audit_log(beat_id, action, metadata, performed_by)
  VALUES (p_beat_id, 'BEAT_DEACTIVATED', '{}'::jsonb, v_user);
  RETURN jsonb_build_object('status','ok');
END $$;



--
-- Name: deactivate_user(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.deactivate_user(p_user_id uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_caller uuid := auth.uid(); v_name text;
BEGIN
  IF v_caller IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.user_has_permission(v_caller, 'admin_user_activate_deactivate', 'can_edit') THEN
    RAISE EXCEPTION 'Your profile does not have permission to deactivate users';
  END IF;
  IF p_user_id = v_caller THEN RAISE EXCEPTION 'You cannot deactivate your own account'; END IF;
  SELECT full_name INTO v_name FROM public.profiles WHERE id = p_user_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'User not found'; END IF;
  UPDATE public.profiles
     SET is_active=false, user_status='inactive',
         deactivated_at=now(), deactivated_by=v_caller, deactivation_reason=p_reason, reactivated_at=NULL
   WHERE id=p_user_id;
  UPDATE auth.users SET banned_until='infinity'::timestamptz WHERE id=p_user_id;
  INSERT INTO public.user_status_log(user_id, action, performed_by, reason)
  VALUES (p_user_id, 'deactivate', v_caller, p_reason);
  RETURN jsonb_build_object('success', true, 'action','deactivate','user_id', p_user_id, 'user_name', v_name);
END $$;



--
-- Name: delete_beat_permanent(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_beat_permanent(p_beat_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_check jsonb;
BEGIN
  v_check := public.can_delete_beat(p_beat_id);
  IF (v_check->>'deletable')::boolean IS NOT TRUE THEN
    RAISE EXCEPTION 'Beat has historical references and cannot be deleted: %', v_check->'reasons';
  END IF;
  DELETE FROM public.beats WHERE beat_id = p_beat_id;
  RETURN jsonb_build_object('status','deleted');
END $$;



--
-- Name: detect_retailer_duplicates(uuid, text, text, numeric, numeric, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.detect_retailer_duplicates(p_retailer_id uuid, p_phone text, p_gst text, p_lat numeric, p_lng numeric, p_name text, p_address text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE risk integer := 0; excl uuid := COALESCE(p_retailer_id, '00000000-0000-0000-0000-000000000000'::uuid); has_match boolean;
BEGIN
  IF p_phone IS NOT NULL AND length(regexp_replace(p_phone,'\D','','g')) >= 10 THEN
    has_match := EXISTS (SELECT 1 FROM public.retailers WHERE id <> excl AND regexp_replace(COALESCE(phone,''),'\D','','g') = regexp_replace(p_phone,'\D','','g'));
    IF has_match THEN risk := risk + 35; END IF;
  END IF;
  IF p_gst IS NOT NULL AND length(trim(p_gst)) >= 10 THEN
    has_match := EXISTS (SELECT 1 FROM public.retailers WHERE id <> excl AND upper(trim(COALESCE(gst_number,''))) = upper(trim(p_gst)));
    IF has_match THEN risk := risk + 30; END IF;
  END IF;
  IF p_lat IS NOT NULL AND p_lng IS NOT NULL THEN
    has_match := EXISTS (SELECT 1 FROM public.retailers WHERE id <> excl AND latitude IS NOT NULL AND longitude IS NOT NULL AND abs(latitude - p_lat) < 0.00045 AND abs(longitude - p_lng) < 0.00045);
    IF has_match THEN risk := risk + 20; END IF;
  END IF;
  IF p_name IS NOT NULL AND length(trim(p_name)) > 3 THEN
    has_match := EXISTS (SELECT 1 FROM public.retailers WHERE id <> excl AND lower(regexp_replace(COALESCE(name,''),'\s+',' ','g')) = lower(regexp_replace(p_name,'\s+',' ','g')));
    IF has_match THEN risk := risk + 10; END IF;
  END IF;
  IF p_address IS NOT NULL AND length(trim(p_address)) > 5 THEN
    has_match := EXISTS (SELECT 1 FROM public.retailers WHERE id <> excl AND lower(regexp_replace(COALESCE(address,''),'\s+',' ','g')) = lower(regexp_replace(p_address,'\s+',' ','g')));
    IF has_match THEN risk := risk + 5; END IF;
  END IF;
  IF risk > 100 THEN risk := 100; END IF;
  RETURN risk;
END; $$;



--
-- Name: dispatch_push_for_notification(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dispatch_push_for_notification() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_url text;
  v_secret text;
  v_actor text;
  v_route text;
  v_push_to_phone text;
BEGIN
  IF NEW.user_id IS NULL
     OR (NEW.target_portal IS NOT NULL AND NEW.target_portal <> 'field_sales_app') THEN
    RETURN NEW;
  END IF;

  v_actor := NEW.metadata->>'actor_id';
  IF v_actor IS NOT NULL AND v_actor = NEW.user_id::text THEN
    RETURN NEW;
  END IF;

  v_push_to_phone := NEW.metadata->>'push_to_phone';
  IF v_push_to_phone IS NOT NULL AND lower(v_push_to_phone) = 'false' THEN
    RETURN NEW;
  END IF;

  SELECT function_url, trigger_secret INTO v_url, v_secret
  FROM public.push_config WHERE id = true LIMIT 1;

  IF v_url IS NULL OR v_secret IS NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.type = 'report_delivery' THEN
    v_route := '/notifications/' || NEW.id::text;
  ELSE
    v_route := COALESCE(NEW.metadata->>'route', '/');
  END IF;

  PERFORM net.http_post(
    url := v_url,
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'x-push-secret', v_secret
    ),
    body := jsonb_build_object(
      'user_id', NEW.user_id,
      'title', COALESCE(NEW.title, 'Notification'),
      'body', COALESCE(NEW.message, ''),
      'data', jsonb_build_object(
        'route', v_route,
        'notification_id', NEW.id,
        'type', NEW.type
      )
    )
  );

  RETURN NEW;
END;
$$;



--
-- Name: emit_notification_event(text, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.emit_notification_event(p_event_code text, p_source_table text, p_record_id text, p_actor_user_id uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_log_id uuid; v_rule RECORD; v_receiver_id uuid; v_title text; v_message text;
  v_actor_name text; v_module_name text; v_record_uuid uuid;
  v_metadata jsonb := COALESCE(p_metadata, '{}'::jsonb);
  v_period_type text; v_top3 jsonb; v_notif_type text; v_is_leaderboard boolean;
BEGIN
  -- ===== outer guard: never propagate to the calling business write =====
  BEGIN
    BEGIN v_record_uuid := p_record_id::uuid; EXCEPTION WHEN others THEN v_record_uuid := NULL; END;
    v_is_leaderboard := p_event_code IN ('WEEKLY_LEADERBOARD','MONTHLY_LEADERBOARD');
    IF v_is_leaderboard THEN
      v_period_type := CASE WHEN p_event_code='WEEKLY_LEADERBOARD' THEN 'weekly' ELSE 'monthly' END;
      SELECT jsonb_agg(jsonb_build_object('rank',s.rank,'user_id',s.user_id,'full_name',s.full_name,'profile_picture_url',s.profile_picture_url,'total_points',s.total_points,'period_label',s.period_label) ORDER BY s.rank)
      INTO v_top3 FROM (SELECT * FROM leaderboard_snapshots WHERE period_type=v_period_type AND captured_at >= now()-interval '10 minutes' ORDER BY captured_at DESC, rank ASC LIMIT 3) s;
      v_metadata := v_metadata || jsonb_build_object('top3', COALESCE(v_top3,'[]'::jsonb));
    END IF;
    INSERT INTO notification_event_log (event_code, source_table, record_id, actor_user_id, metadata)
    VALUES (p_event_code, p_source_table, p_record_id, p_actor_user_id, v_metadata) RETURNING id INTO v_log_id;
    SELECT COALESCE(full_name, username, 'System') INTO v_actor_name FROM profiles WHERE id = p_actor_user_id;
    v_module_name := INITCAP(REPLACE(p_source_table,'_',' '));
    v_notif_type := CASE WHEN v_is_leaderboard THEN 'leaderboard_banner' ELSE p_event_code END;

    IF v_is_leaderboard THEN
      SELECT * INTO v_rule FROM notification_rules WHERE event_code=p_event_code AND source_table=p_source_table AND is_active=true LIMIT 1;
      v_title := COALESCE(v_rule.title_template,'🏆 Top performers');
      v_message := COALESCE(v_rule.message_template,'The leaderboard results are in.');
      v_title := REPLACE(v_title,'{record_name}', COALESCE(v_metadata->>'period_label',''));
      v_message := REPLACE(v_message,'{record_name}', COALESCE(v_metadata->>'period_label',''));
      INSERT INTO notifications (user_id, title, message, type, related_table, related_id, metadata)
      SELECT DISTINCT up.user_id, v_title, v_message, v_notif_type, p_source_table, v_record_uuid, v_metadata
      FROM user_profiles up WHERE up.user_id IS NOT NULL;
      RETURN v_log_id;
    END IF;

    FOR v_rule IN SELECT * FROM notification_rules WHERE event_code=p_event_code AND source_table=p_source_table AND is_active=true LOOP
      v_title := public.notif_fill(v_rule.title_template, v_actor_name, v_module_name, v_metadata);
      v_message := public.notif_fill(v_rule.message_template, v_actor_name, v_module_name, v_metadata);
      CASE v_rule.receiver_type
        WHEN 'employee', 'self' THEN
          INSERT INTO notifications (user_id,title,message,type,related_table,related_id,metadata)
          VALUES (p_actor_user_id, v_title, v_message, v_notif_type, p_source_table, v_record_uuid, v_metadata);
        WHEN 'manager' THEN
          SELECT manager_id INTO v_receiver_id FROM employees WHERE user_id=p_actor_user_id;
          IF v_receiver_id IS NOT NULL THEN
            INSERT INTO notifications (user_id,title,message,type,related_table,related_id,metadata)
            VALUES (v_receiver_id, v_title, v_message, v_notif_type, p_source_table, v_record_uuid, v_metadata);
          END IF;
        WHEN 'hierarchy', 'reporting_chain' THEN
          FOR v_receiver_id IN SELECT public.notif_managers_up_chain(p_actor_user_id) LOOP
            INSERT INTO notifications (user_id,title,message,type,related_table,related_id,metadata)
            VALUES (v_receiver_id, v_title, v_message, v_notif_type, p_source_table, v_record_uuid, v_metadata);
          END LOOP;
        WHEN 'admin' THEN
          FOR v_receiver_id IN SELECT up.user_id FROM user_profiles up JOIN security_profiles sp ON sp.id=up.profile_id WHERE sp.name='System Administrator' LOOP
            INSERT INTO notifications (user_id,title,message,type,related_table,related_id,metadata)
            VALUES (v_receiver_id, v_title, v_message, v_notif_type, p_source_table, v_record_uuid, v_metadata);
          END LOOP;
        WHEN 'specific_user' THEN
          IF v_rule.receiver_user_id IS NOT NULL THEN
            INSERT INTO notifications (user_id,title,message,type,related_table,related_id,metadata)
            VALUES (v_rule.receiver_user_id, v_title, v_message, v_notif_type, p_source_table, v_record_uuid, v_metadata);
          END IF;
        WHEN 'role' THEN
          FOR v_receiver_id IN SELECT user_id FROM user_roles WHERE role::text=v_rule.receiver_role LOOP
            INSERT INTO notifications (user_id,title,message,type,related_table,related_id,metadata)
            VALUES (v_receiver_id, v_title, v_message, v_notif_type, p_source_table, v_record_uuid, v_metadata);
          END LOOP;
        ELSE NULL;
      END CASE;
    END LOOP;
    RETURN v_log_id;

  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'emit_notification_event(%,%) suppressed: % [%] — business write preserved',
      p_event_code, p_source_table, SQLERRM, SQLSTATE;
    RETURN NULL;
  END;
END;
$$;



--
-- Name: FUNCTION emit_notification_event(p_event_code text, p_source_table text, p_record_id text, p_actor_user_id uuid, p_metadata jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.emit_notification_event(p_event_code text, p_source_table text, p_record_id text, p_actor_user_id uuid, p_metadata jsonb) IS 'Emits notifications per notification_rules. Body wrapped in an exception handler so a notification fault can never abort the calling INSERT/UPDATE. Logic unchanged 2026-08-05.';



--
-- Name: enforce_base_factor_one(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_base_factor_one() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN IF NEW.is_base = true AND NEW.conversion_to_base <> 1 THEN RAISE EXCEPTION 'Base unit must have conversion_to_base = 1 (got %)', NEW.conversion_to_base; END IF; RETURN NEW; END; $$;



--
-- Name: enforce_category_match(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_category_match() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE v_base_category text; v_new_category text;
BEGIN
  SELECT m.category INTO v_new_category FROM public.uom_master m WHERE m.id = NEW.uom_id;
  SELECT m.category INTO v_base_category FROM public.product_uom_mapping p JOIN public.uom_master m ON m.id = p.uom_id WHERE p.product_id = NEW.product_id AND p.is_base = true AND p.id <> NEW.id LIMIT 1;
  IF v_base_category IS NOT NULL AND v_new_category <> v_base_category AND v_new_category <> 'Quantity' THEN
    RAISE EXCEPTION 'Unit category % does not match product base category %', v_new_category, v_base_category; END IF;
  RETURN NEW; END; $$;



--
-- Name: enforce_delivery_run_status_transition(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_delivery_run_status_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  allowed_transitions jsonb := '{
    "ready": ["assigned"],
    "assigned": ["out_for_delivery"],
    "out_for_delivery": ["delivered"]
  }'::jsonb;
  allowed jsonb;
BEGIN
  IF OLD.status = NEW.status THEN
    RETURN NEW;
  END IF;

  allowed := allowed_transitions -> OLD.status;
  IF allowed IS NULL OR NOT (allowed ? NEW.status) THEN
    RAISE EXCEPTION 'Invalid delivery run status transition: % -> %', OLD.status, NEW.status;
  END IF;

  RETURN NEW;
END;
$$;



--
-- Name: enforce_single_base_per_product(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_single_base_per_product() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE v_count integer; v_product_id uuid;
BEGIN
  IF TG_OP = 'DELETE' THEN v_product_id := OLD.product_id; ELSE v_product_id := NEW.product_id; END IF;
  SELECT count(*) INTO v_count FROM public.product_uom_mapping WHERE product_id = v_product_id AND is_base = true;
  IF v_count > 1 THEN RAISE EXCEPTION 'Product % cannot have more than one base unit (found %)', v_product_id, v_count; END IF;
  RETURN NULL; END; $$;



--
-- Name: ensure_inventory_batch_quantity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_inventory_batch_quantity() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF (NEW.quantity IS NULL OR NEW.quantity = 0)
     AND (COALESCE(NEW.available_qty, 0) > 0 OR COALESCE(NEW.reserved_qty, 0) > 0) THEN
    NEW.quantity := COALESCE(NEW.available_qty, 0) + COALESCE(NEW.reserved_qty, 0);
  END IF;
  RETURN NEW;
END; $$;



--
-- Name: eod_cancel_pending_visits(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.eod_cancel_pending_visits() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cfg public.operations_config%ROWTYPE;
  v_now timestamp;
  v_today date;
  v_time time;
  v_count integer := 0;
BEGIN
  SELECT * INTO v_cfg FROM public.operations_config WHERE id = 1;
  IF v_cfg.id IS NULL OR COALESCE(v_cfg.auto_cancel_enabled, false) = false THEN
    RETURN 0;
  END IF;

  v_now := (now() AT TIME ZONE v_cfg.eod_timezone);
  v_today := v_now::date;
  v_time := v_now::time;

  UPDATE public.visits
     SET status = 'cancelled',
         cancel_source = 'eod_auto',
         updated_at = now()
   WHERE status = 'planned'
     AND (planned_date < v_today
          OR (planned_date = v_today AND v_time >= v_cfg.eod_cutoff_time));

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;



--
-- Name: event_sync_participants(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.event_sync_participants(p_event_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_ev       record;
  v_rep      uuid;
  v_added    int := 0;
  v_existing int := 0;
  v_moved    int := 0;
begin
  select ae.id, ae.user_id, ae.visit_id, ae.activity_date, ae.sales_reps
    into v_ev
    from public.activity_events ae
   where ae.id = p_event_id;

  if v_ev.id is null then
    raise exception 'Event not found';
  end if;

  if auth.uid() is null or auth.uid() <> v_ev.user_id then
    raise exception 'Only the event owner can change its team';
  end if;

  update public.visits
     set activity_event_id = v_ev.id
   where id = v_ev.visit_id
     and activity_event_id is distinct from v_ev.id;

  foreach v_rep in array coalesce(v_ev.sales_reps, '{}'::uuid[]) loop
    if v_rep = v_ev.user_id then
      continue;
    end if;

    if exists (
      select 1 from public.visits v
       where v.user_id = v_rep and v.activity_event_id = v_ev.id
    ) then
      v_existing := v_existing + 1;
      continue;
    end if;

    insert into public.visits (user_id, planned_date, status, visit_type, activity_event_id)
    values (v_rep, v_ev.activity_date, 'planned', 'activity', v_ev.id);
    v_added := v_added + 1;
  end loop;

  update public.visits
     set planned_date = v_ev.activity_date
   where activity_event_id = v_ev.id
     and check_in_time is null
     and planned_date is distinct from v_ev.activity_date;
  get diagnostics v_moved = row_count;

  return jsonb_build_object('added', v_added, 'existing', v_existing, 'moved', v_moved);
end;
$$;



--
-- Name: expire_user_delegations(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expire_user_delegations() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE public.retailer_shared_access SET is_active = false
   WHERE source = 'delegation' AND is_active = true
     AND effective_to IS NOT NULL AND effective_to < now();
  UPDATE public.user_delegations SET status = 'expired'
   WHERE status = 'active' AND effective_to < now();
END $$;



--
-- Name: finalize_order_edit(uuid, uuid, uuid, text, numeric, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_order_edit(p_original_order_id uuid, p_replacement_order_id uuid, p_edited_by uuid, p_reason text, p_target_paid numeric DEFAULT NULL::numeric, p_new_collection_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_original orders%ROWTYPE;
  v_replacement orders%ROWTYPE;
  v_original_total numeric;
  v_replacement_total numeric;
  v_new_pending numeric;
  v_alloc RECORD;
  v_apply numeric;
  v_left numeric;
  v_transfer numeric := 0;
  v_repl_pending numeric;
  v_cf_collection uuid;
  v_repl_paid numeric;
  v_excess numeric;
  v_delta numeric;
  v_free_left numeric := 0;
  v_alloc2 RECORD;
  v_take numeric;
  v_orig_snapshot jsonb;
  v_repl_snapshot jsonb;
  v_cfg operations_config%ROWTYPE;
  v_price_mismatch int;
BEGIN
  IF NOT public.can_edit_order(p_original_order_id, p_edited_by) THEN
    RAISE EXCEPTION 'Editing not allowed for this order (locked, no permission, or edit limit reached)';
  END IF;

  SELECT * INTO v_cfg FROM operations_config WHERE id = 1;

  IF COALESCE(v_cfg.edit_require_reason, false) AND COALESCE(p_reason, '') = '' THEN
    RAISE EXCEPTION 'A reason is required to edit this order';
  END IF;

  IF COALESCE(v_cfg.edit_lock_price, false) THEN
    SELECT COUNT(*) INTO v_price_mismatch
    FROM order_items oi_o
    JOIN order_items oi_r
      ON oi_r.order_id = p_replacement_order_id
     AND oi_r.product_id IS NOT DISTINCT FROM oi_o.product_id
     AND COALESCE(oi_r.variant_id::text, '') = COALESCE(oi_o.variant_id::text, '')
    WHERE oi_o.order_id = p_original_order_id
      AND COALESCE(oi_r.rate, 0) <> COALESCE(oi_o.rate, 0);

    IF v_price_mismatch > 0 THEN
      RAISE EXCEPTION 'Price edits are locked; only quantity can be changed';
    END IF;
  END IF;

  SELECT * INTO v_original FROM orders WHERE id = p_original_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Original order not found');
  END IF;

  SELECT * INTO v_replacement FROM orders WHERE id = p_replacement_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Replacement order not found');
  END IF;

  IF v_original.replaced_by_order_id = p_replacement_order_id THEN
    v_new_pending := public.recompute_retailer_pending(v_original.retailer_id);
    RETURN jsonb_build_object(
      'success', true, 'already_finalized', true,
      'original_order_id', p_original_order_id,
      'replacement_order_id', p_replacement_order_id,
      'retailer_pending', v_new_pending
    );
  END IF;

  IF v_original.replaced_by_order_id IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Original order is already replaced by another order');
  END IF;
  IF v_original.status = 'cancelled' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Original order is already cancelled');
  END IF;
  IF v_replacement.replaces_order_id IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Replacement order already replaces another order');
  END IF;
  IF v_replacement.status = 'cancelled' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Replacement order is cancelled');
  END IF;

  v_orig_snapshot := jsonb_build_object(
    'order', to_jsonb(v_original),
    'items', COALESCE((SELECT jsonb_agg(to_jsonb(oi.*)) FROM order_items oi
                       WHERE oi.order_id = p_original_order_id), '[]'::jsonb));

  v_original_total := v_original.total_amount;
  v_replacement_total := v_replacement.total_amount;

  UPDATE orders SET replaced_by_order_id = p_replacement_order_id, updated_at = now()
    WHERE id = p_original_order_id;
  UPDATE orders SET replaces_order_id = p_original_order_id, updated_at = now()
    WHERE id = p_replacement_order_id;

  FOR v_alloc IN
    SELECT collection_id, SUM(amount_applied) AS amt
    FROM retailer_payment_allocations
    WHERE order_id = p_original_order_id
    GROUP BY collection_id
  LOOP
    SELECT COALESCE(credit_pending_amount, 0) INTO v_repl_pending
      FROM orders WHERE id = p_replacement_order_id FOR UPDATE;
    v_apply := LEAST(v_alloc.amt, v_repl_pending);

    IF v_apply > 0 THEN
      UPDATE orders
        SET credit_paid_amount    = COALESCE(credit_paid_amount, 0) + v_apply,
            credit_pending_amount = COALESCE(credit_pending_amount, 0) - v_apply,
            payment_status = CASE
              WHEN COALESCE(credit_pending_amount, 0) - v_apply <= 0 THEN 'paid' ELSE 'partial' END
        WHERE id = p_replacement_order_id;

      INSERT INTO retailer_payment_allocations (collection_id, order_id, retailer_id, amount_applied)
        VALUES (v_alloc.collection_id, p_replacement_order_id, v_original.retailer_id, v_apply);
    END IF;

    IF v_alloc.amt - v_apply > 0 THEN
      v_left := public.reflow_allocation_fifo(
                  v_original.retailer_id, v_alloc.collection_id, v_alloc.amt - v_apply, p_original_order_id);
      IF v_left > 0 THEN
        INSERT INTO credit_ledger (retailer_id, amount, type, reference_id, created_by)
        VALUES (v_original.retailer_id, -v_left, 'cancel_carry_forward', p_original_order_id, p_edited_by);
      END IF;
    END IF;

    v_transfer := v_transfer + v_alloc.amt;
  END LOOP;

  IF v_transfer = 0 AND COALESCE(v_original.credit_paid_amount, 0) > 0 THEN
    INSERT INTO retailer_payment_collections
      (retailer_id, amount, payment_method, collected_by_user_id, notes)
    VALUES
      (v_original.retailer_id, v_original.credit_paid_amount, 'carry_forward', p_edited_by,
       'Carry-forward from edited order ' || COALESCE(v_original.invoice_number, p_original_order_id::text))
    RETURNING id INTO v_cf_collection;

    SELECT COALESCE(credit_pending_amount, 0) INTO v_repl_pending
      FROM orders WHERE id = p_replacement_order_id FOR UPDATE;
    v_apply := LEAST(v_original.credit_paid_amount, v_repl_pending);

    IF v_apply > 0 THEN
      UPDATE orders
        SET credit_paid_amount    = COALESCE(credit_paid_amount, 0) + v_apply,
            credit_pending_amount = COALESCE(credit_pending_amount, 0) - v_apply,
            payment_status = CASE
              WHEN COALESCE(credit_pending_amount, 0) - v_apply <= 0 THEN 'paid' ELSE 'partial' END
        WHERE id = p_replacement_order_id;

      INSERT INTO retailer_payment_allocations (collection_id, order_id, retailer_id, amount_applied)
        VALUES (v_cf_collection, p_replacement_order_id, v_original.retailer_id, v_apply);
    END IF;

    IF v_original.credit_paid_amount - v_apply > 0 THEN
      v_left := public.reflow_allocation_fifo(
                  v_original.retailer_id, v_cf_collection, v_original.credit_paid_amount - v_apply, p_original_order_id);
      IF v_left > 0 THEN
        INSERT INTO credit_ledger (retailer_id, amount, type, reference_id, created_by)
        VALUES (v_original.retailer_id, -v_left, 'cancel_carry_forward', p_original_order_id, p_edited_by);
      END IF;
    END IF;
  END IF;

  IF p_target_paid IS NOT NULL THEN
    SELECT COALESCE(credit_paid_amount, 0) INTO v_repl_paid
      FROM orders WHERE id = p_replacement_order_id FOR UPDATE;

    v_delta := p_target_paid - v_repl_paid;

    IF v_delta > 0 THEN
      IF p_new_collection_id IS NOT NULL THEN
        SELECT COALESCE(credit_pending_amount, 0) INTO v_repl_pending
          FROM orders WHERE id = p_replacement_order_id FOR UPDATE;
        v_apply := LEAST(v_delta, v_repl_pending);

        IF v_apply > 0 THEN
          UPDATE orders
            SET credit_paid_amount = COALESCE(credit_paid_amount,0) + v_apply,
                credit_pending_amount = COALESCE(credit_pending_amount,0) - v_apply,
                payment_status = CASE
                  WHEN COALESCE(credit_pending_amount,0) - v_apply <= 0 THEN 'paid' ELSE 'partial' END
            WHERE id = p_replacement_order_id;

          INSERT INTO retailer_payment_allocations (collection_id, order_id, retailer_id, amount_applied)
            VALUES (p_new_collection_id, p_replacement_order_id, v_original.retailer_id, v_apply);
        END IF;
      END IF;
    ELSIF v_delta < 0 THEN
      v_excess := -v_delta;
      UPDATE orders
        SET credit_paid_amount = GREATEST(0, COALESCE(credit_paid_amount,0) - v_excess),
            credit_pending_amount = COALESCE(credit_pending_amount,0) + v_excess,
            payment_status = CASE
              WHEN COALESCE(credit_pending_amount,0) + v_excess <= 0 THEN 'paid' ELSE 'partial' END
        WHERE id = p_replacement_order_id;

      FOR v_alloc2 IN
        SELECT id, amount_applied
        FROM retailer_payment_allocations
        WHERE order_id = p_replacement_order_id
        ORDER BY id DESC
      LOOP
        EXIT WHEN v_excess <= 0;
        v_take := LEAST(v_alloc2.amount_applied, v_excess);
        IF v_take = v_alloc2.amount_applied THEN
          DELETE FROM retailer_payment_allocations WHERE id = v_alloc2.id;
        ELSE
          UPDATE retailer_payment_allocations SET amount_applied = amount_applied - v_take WHERE id = v_alloc2.id;
        END IF;
        v_excess := v_excess - v_take;
      END LOOP;
    END IF;
  END IF;

  v_repl_snapshot := jsonb_build_object(
    'order', to_jsonb((SELECT o FROM orders o WHERE o.id = p_replacement_order_id)),
    'items', COALESCE((SELECT jsonb_agg(to_jsonb(oi.*)) FROM order_items oi
                       WHERE oi.order_id = p_replacement_order_id), '[]'::jsonb));

  UPDATE orders
    SET edit_count = COALESCE(edit_count, 0) + 1,
        is_edited = true,
        edited_at = now(),
        updated_at = now()
    WHERE id = p_original_order_id;

  INSERT INTO public.order_edit_log (order_id, original_order_id, replacement_order_id, edited_by, reason, old_total, new_total, original_snapshot, replacement_snapshot)
  VALUES (p_original_order_id, p_original_order_id, p_replacement_order_id, p_edited_by, p_reason, v_original_total, v_replacement_total, v_orig_snapshot, v_repl_snapshot);

  v_new_pending := public.recompute_retailer_pending(v_original.retailer_id);

  RETURN jsonb_build_object(
    'success', true,
    'original_order_id', p_original_order_id,
    'replacement_order_id', p_replacement_order_id,
    'old_total', v_original_total,
    'new_total', v_replacement_total,
    'retailer_pending', v_new_pending
  );
END;
$$;



--
-- Name: find_duplicate_retailers(text, text, numeric, numeric, uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.find_duplicate_retailers(p_name text, p_phone text DEFAULT NULL::text, p_lat numeric DEFAULT NULL::numeric, p_lng numeric DEFAULT NULL::numeric, p_exclude_id uuid DEFAULT NULL::uuid, p_radius_m numeric DEFAULT 100) RETURNS TABLE(id uuid, name text, phone text, owner_user_id uuid, owner_name text, matched_on text[], distance_m numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT r.id, r.name, r.phone, r.user_id, p.full_name,
    array_remove(ARRAY[
      CASE WHEN p_phone IS NOT NULL AND length(regexp_replace(p_phone,'\D','','g'))>=7 AND regexp_replace(coalesce(r.phone,''),'\D','','g')=regexp_replace(p_phone,'\D','','g') THEN 'phone' END,
      CASE WHEN p_name IS NOT NULL AND similarity(lower(btrim(r.name)),lower(btrim(p_name)))>=0.5 THEN 'name' END,
      CASE WHEN p_lat IS NOT NULL AND p_lng IS NOT NULL AND r.latitude IS NOT NULL AND r.longitude IS NOT NULL AND (6371000*acos(least(1,greatest(-1,cos(radians(p_lat))*cos(radians(r.latitude))*cos(radians(r.longitude)-radians(p_lng))+sin(radians(p_lat))*sin(radians(r.latitude))))))<=p_radius_m THEN 'location' END
    ], NULL) AS matched_on,
    CASE WHEN p_lat IS NOT NULL AND p_lng IS NOT NULL AND r.latitude IS NOT NULL AND r.longitude IS NOT NULL THEN round((6371000*acos(least(1,greatest(-1,cos(radians(p_lat))*cos(radians(r.latitude))*cos(radians(r.longitude)-radians(p_lng))+sin(radians(p_lat))*sin(radians(r.latitude))))))::numeric,0) END AS distance_m
  FROM retailers r LEFT JOIN profiles p ON p.id = r.user_id
  WHERE (p_exclude_id IS NULL OR r.id <> p_exclude_id) AND coalesce(r.status,'active') <> 'inactive'
    AND ((p_phone IS NOT NULL AND length(regexp_replace(p_phone,'\D','','g'))>=7 AND regexp_replace(coalesce(r.phone,''),'\D','','g')=regexp_replace(p_phone,'\D','','g'))
      OR (p_name IS NOT NULL AND similarity(lower(btrim(r.name)),lower(btrim(p_name)))>=0.5)
      OR (p_lat IS NOT NULL AND p_lng IS NOT NULL AND r.latitude IS NOT NULL AND r.longitude IS NOT NULL AND (6371000*acos(least(1,greatest(-1,cos(radians(p_lat))*cos(radians(r.latitude))*cos(radians(r.longitude)-radians(p_lng))+sin(radians(p_lat))*sin(radians(r.latitude))))))<=p_radius_m))
  ORDER BY array_length(array_remove(ARRAY[
      CASE WHEN p_phone IS NOT NULL AND regexp_replace(coalesce(r.phone,''),'\D','','g')=regexp_replace(coalesce(p_phone,''),'\D','','g') AND length(regexp_replace(coalesce(p_phone,''),'\D','','g'))>=7 THEN 'x' END,
      CASE WHEN p_name IS NOT NULL AND similarity(lower(btrim(r.name)),lower(btrim(p_name)))>=0.5 THEN 'x' END
    ], NULL),1) DESC NULLS LAST, distance_m ASC NULLS LAST
  LIMIT 10;
$$;



--
-- Name: gam_award_event(uuid, text, text, uuid, uuid, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gam_award_event(p_user_id uuid, p_trigger_type text, p_reference_type text DEFAULT NULL::text, p_reference_id uuid DEFAULT NULL::uuid, p_retailer_id uuid DEFAULT NULL::uuid, p_context jsonb DEFAULT '{}'::jsonb, p_dry_run boolean DEFAULT NULL::boolean) RETURNS TABLE(action_id uuid, action_name text, points numeric, awarded boolean, reason text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  s public.gamification_settings%ROWTYPE;
  a record;
  v_now timestamptz := now();
  v_dry boolean;
  v_expires timestamptz;
BEGIN
  SELECT * INTO s FROM public.gamification_settings LIMIT 1;
  v_dry := COALESCE(p_dry_run, NOT COALESCE(s.engine_enabled, false));

  IF p_user_id IS NULL OR p_trigger_type IS NULL THEN RETURN; END IF;

  FOR a IN
    SELECT act.* FROM public.gamification_actions act
    JOIN public.gamification_games g ON g.id = act.game_id
    WHERE act.is_enabled = true
      AND g.is_active = true
      AND COALESCE(act.trigger_type, act.action_type) = p_trigger_type
      AND COALESCE(act.is_tiered, false) = false
      AND (act.validity_from IS NULL OR act.validity_from <= v_now::date)
      AND (act.validity_to IS NULL OR act.validity_to >= v_now::date)
      AND (g.start_date IS NULL OR g.start_date <= v_now::date)
      AND (g.end_date IS NULL OR g.end_date >= v_now::date)
  LOOP
    action_id := a.id; action_name := a.action_name; points := a.points; awarded := false; reason := NULL;

    IF NOT public.gam_is_eligible(a.id, p_user_id) THEN
      reason := 'not_eligible'; RETURN NEXT; CONTINUE;
    END IF;

    IF NOT public.gam_conditions_match(a.conditions_json, p_context) THEN
      reason := 'conditions_not_met'; RETURN NEXT; CONTINUE;
    END IF;

    IF p_reference_id IS NOT NULL AND EXISTS (
      SELECT 1 FROM public.gamification_points gp
      WHERE gp.action_id = a.id AND gp.reference_id = p_reference_id AND gp.user_id = p_user_id
    ) THEN
      reason := 'already_awarded'; RETURN NEXT; CONTINUE;
    END IF;

    IF v_dry THEN
      reason := 'dry_run'; RETURN NEXT; CONTINUE;
    END IF;

    IF NOT public.gam_consume_cap(a.id, p_user_id, p_retailer_id, v_now) THEN
      reason := 'cap_reached'; RETURN NEXT; CONTINUE;
    END IF;

    v_expires := public.gam_compute_expiry(a.expiry_type, a.expiry_days, v_now);

    INSERT INTO public.gamification_points
      (user_id, game_id, action_id, points, reference_type, reference_id, earned_at, expires_at, status, period_key, retailer_id, metadata)
    VALUES
      (p_user_id, a.game_id, a.id, a.points, p_reference_type, p_reference_id, v_now, v_expires, 'active',
       to_char(v_now, 'YYYY-MM'), p_retailer_id, jsonb_build_object('trigger', p_trigger_type, 'context', p_context));

    awarded := true; reason := 'awarded';

    IF COALESCE(s.notifications_enabled, true) THEN
      BEGIN
        INSERT INTO public.notifications (user_id, title, message, type)
        VALUES (p_user_id,
                'You earned ' || a.points || ' points',
                a.action_name,
                'gamification');
      EXCEPTION WHEN others THEN NULL;
      END;
    END IF;

    RETURN NEXT;
  END LOOP;
END;
$$;



--
-- Name: gam_compute_expiry(text, integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gam_compute_expiry(p_expiry_type text, p_expiry_days integer, p_ts timestamp with time zone DEFAULT now()) RETURNS timestamp with time zone
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN p_expiry_type = 'never' THEN NULL
    WHEN p_expiry_type = 'days' THEN p_ts + make_interval(days => COALESCE(p_expiry_days, 180))
    ELSE public.gam_fy_end(p_ts)
  END;
$$;



--
-- Name: gam_conditions_match(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gam_conditions_match(p_conditions jsonb, p_context jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  c jsonb;
  fld text; op text; val jsonb; actual jsonb;
  a_num numeric; v_num numeric;
BEGIN
  IF p_conditions IS NULL OR jsonb_typeof(p_conditions) <> 'array' OR jsonb_array_length(p_conditions) = 0 THEN
    RETURN true;
  END IF;

  FOR c IN SELECT * FROM jsonb_array_elements(COALESCE(p_conditions, '[]'::jsonb)) LOOP
    fld := c->>'field';
    op := COALESCE(c->>'operator', '=');
    val := c->'value';
    actual := COALESCE(p_context, '{}'::jsonb)->fld;

    IF actual IS NULL THEN RETURN false; END IF;

    BEGIN
      a_num := (actual #>> '{}')::numeric;
      v_num := (val #>> '{}')::numeric;
    EXCEPTION WHEN others THEN
      a_num := NULL; v_num := NULL;
    END;

    IF op IN ('>', '>=', '<', '<=') THEN
      IF a_num IS NULL OR v_num IS NULL THEN RETURN false; END IF;
      IF op = '>'  AND NOT (a_num >  v_num) THEN RETURN false; END IF;
      IF op = '>=' AND NOT (a_num >= v_num) THEN RETURN false; END IF;
      IF op = '<'  AND NOT (a_num <  v_num) THEN RETURN false; END IF;
      IF op = '<=' AND NOT (a_num <= v_num) THEN RETURN false; END IF;
    ELSIF op = '=' THEN
      IF a_num IS NOT NULL AND v_num IS NOT NULL THEN
        IF a_num <> v_num THEN RETURN false; END IF;
      ELSIF (actual #>> '{}') IS DISTINCT FROM (val #>> '{}') THEN
        RETURN false;
      END IF;
    ELSIF op = '!=' THEN
      IF (actual #>> '{}') IS NOT DISTINCT FROM (val #>> '{}') THEN RETURN false; END IF;
    ELSIF op = 'in' THEN
      IF jsonb_typeof(val) <> 'array' THEN RETURN false; END IF;
      IF NOT EXISTS (SELECT 1 FROM jsonb_array_elements(val) e WHERE (e #>> '{}') = (actual #>> '{}')) THEN
        RETURN false;
      END IF;
    ELSIF op = 'contains' THEN
      IF position(lower(val #>> '{}') in lower(actual #>> '{}')) = 0 THEN RETURN false; END IF;
    ELSIF op = 'is_true' THEN
      IF (actual #>> '{}') NOT IN ('true','t','1') THEN RETURN false; END IF;
    ELSIF op = 'is_false' THEN
      IF (actual #>> '{}') NOT IN ('false','f','0') THEN RETURN false; END IF;
    END IF;
  END LOOP;

  RETURN true;
END;
$$;



--
-- Name: gam_consume_cap(uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gam_consume_cap(p_action_id uuid, p_user_id uuid, p_retailer_id uuid, p_ts timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  a public.gamification_actions%ROWTYPE;
  v_key text;
  v_ret uuid;
  v_count integer;
BEGIN
  SELECT * INTO a FROM public.gamification_actions WHERE id = p_action_id;
  IF NOT FOUND THEN RETURN false; END IF;
  IF a.cap_scope = 'none' OR a.cap_value IS NULL OR a.cap_value <= 0 THEN RETURN true; END IF;

  IF a.cap_scope = 'user_month' THEN
    v_key := public.gam_period_key('user_month', p_ts); v_ret := NULL;
  ELSIF a.cap_scope = 'retailer' THEN
    v_key := 'retailer'; v_ret := p_retailer_id;
    IF v_ret IS NULL THEN RETURN true; END IF;
  ELSE
    v_key := public.gam_period_key('user_day', p_ts); v_ret := NULL;
  END IF;

  INSERT INTO public.gamification_daily_tracking (user_id, action_id, tracking_date, period_key, retailer_id, count)
  VALUES (p_user_id, p_action_id, p_ts::date, v_key, v_ret, 1)
  ON CONFLICT (user_id, action_id, period_key, coalesce(retailer_id, '00000000-0000-0000-0000-000000000000'::uuid))
  DO UPDATE SET count = public.gamification_daily_tracking.count + 1, updated_at = now()
  RETURNING count INTO v_count;

  IF v_count > a.cap_value THEN
    UPDATE public.gamification_daily_tracking
      SET count = a.cap_value, updated_at = now()
    WHERE user_id = p_user_id AND action_id = p_action_id AND period_key = v_key
      AND coalesce(retailer_id, '00000000-0000-0000-0000-000000000000'::uuid) = coalesce(v_ret, '00000000-0000-0000-0000-000000000000'::uuid);
    RETURN false;
  END IF;

  RETURN true;
END;
$$;



--
-- Name: gam_evaluate_target_tiers(text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gam_evaluate_target_tiers(p_period_key text DEFAULT to_char(now(), 'YYYY-MM'::text), p_dry_run boolean DEFAULT NULL::boolean) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  s public.gamification_settings%ROWTYPE;
  v_dry boolean; a record; t record; upt record; v_awards integer := 0;
  v_start date := to_date(p_period_key || '-01', 'YYYY-MM-DD');
BEGIN
  SELECT * INTO s FROM public.gamification_settings LIMIT 1;
  v_dry := COALESCE(p_dry_run, NOT COALESCE(s.engine_enabled, false));

  FOR a IN
    SELECT act.* FROM public.gamification_actions act
    JOIN public.gamification_games g ON g.id = act.game_id
    WHERE act.is_enabled AND g.is_active AND act.is_tiered AND act.kpi_id IS NOT NULL
  LOOP
    FOR upt IN
      SELECT u.user_id, u.achievement_percent
      FROM public.user_period_targets u
      WHERE u.kpi_id = a.kpi_id
        AND u.period_start >= v_start
        AND u.period_start < (v_start + interval '1 month')
    LOOP
      IF NOT public.gam_is_eligible(a.id, upt.user_id) THEN CONTINUE; END IF;

      SELECT * INTO t FROM public.activity_tiers
      WHERE action_id = a.id AND threshold_pct <= COALESCE(upt.achievement_percent, 0)
      ORDER BY threshold_pct DESC LIMIT 1;

      IF NOT FOUND THEN CONTINUE; END IF;

      IF EXISTS (
        SELECT 1 FROM public.gamification_points
        WHERE action_id = a.id AND user_id = upt.user_id AND period_key = p_period_key
      ) THEN CONTINUE; END IF;

      IF v_dry THEN v_awards := v_awards + 1; CONTINUE; END IF;

      INSERT INTO public.gamification_points
        (user_id, game_id, action_id, points, reference_type, earned_at, expires_at, status, period_key, metadata)
      VALUES
        (upt.user_id, a.game_id, a.id, t.points, 'target_tier', now(),
         public.gam_compute_expiry(a.expiry_type, a.expiry_days, now()), 'active', p_period_key,
         jsonb_build_object('tier_threshold', t.threshold_pct, 'achievement_percent', upt.achievement_percent));

      v_awards := v_awards + 1;
    END LOOP;
  END LOOP;

  RETURN v_awards;
END;
$$;



--
-- Name: gam_expire_points(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gam_expire_points() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_count integer;
BEGIN
  UPDATE public.gamification_points
  SET status = 'expired'
  WHERE status = 'active' AND expires_at IS NOT NULL AND expires_at <= now();
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;



--
