--

CREATE FUNCTION public.gam_fy_end(p_ts timestamp with time zone DEFAULT now()) RETURNS timestamp with time zone
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT (date_trunc('year', p_ts + interval '9 months') + interval '3 months' - interval '1 second');
$$;



--
-- Name: gam_is_eligible(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gam_is_eligible(p_action_id uuid, p_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  a public.gamification_actions%ROWTYPE;
BEGIN
  SELECT * INTO a FROM public.gamification_actions WHERE id = p_action_id;
  IF NOT FOUND THEN RETURN false; END IF;

  IF a.eligibility_mode = 'all' THEN
    RETURN true;
  ELSIF a.eligibility_mode = 'users' THEN
    RETURN p_user_id = ANY(a.eligibility_ids);
  ELSIF a.eligibility_mode = 'manager' THEN
    IF p_user_id = ANY(a.eligibility_ids) THEN RETURN true; END IF;
    RETURN EXISTS (
      SELECT 1 FROM unnest(a.eligibility_ids) m(mid),
      LATERAL public.get_all_subordinates(m.mid) s
      WHERE s.subordinate_user_id = p_user_id
    );
  ELSIF a.eligibility_mode = 'territory' THEN
    RETURN EXISTS (
      SELECT 1 FROM public.profiles p
      WHERE p.id = p_user_id
        AND p.territories_covered && (SELECT array_agg(x::text) FROM unnest(a.eligibility_ids) x)
    );
  END IF;
  RETURN false;
END;
$$;



--
-- Name: gam_on_retailer_verified(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gam_on_retailer_verified() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid;
BEGIN
  IF COALESCE(NEW.verified, false) = true AND COALESCE(OLD.verified, false) = false THEN
    v_user := COALESCE(NEW.owner_id, NEW.user_id, NEW.created_by);
    IF v_user IS NOT NULL THEN
      BEGIN
        PERFORM public.gam_award_event(
          v_user,
          'retailer_verified',
          'retailer',
          NEW.id,
          NEW.id,
          jsonb_build_object(
            'verification_score', NEW.verification_score,
            'verification_method', NEW.verification_method
          ),
          NULL
        );
      EXCEPTION WHEN others THEN NULL;
      END;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;



