--
-- Name: get_activity_logging_summary(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_activity_logging_summary(p_days integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  result jsonb;
  cutoff timestamptz;
  has_access boolean := false;
BEGIN
  has_access := is_system_admin(auth.uid());
  
  IF NOT has_access THEN
    SELECT EXISTS (
      SELECT 1 FROM user_profiles up
      JOIN profile_object_permissions pop ON pop.profile_id = up.profile_id
      WHERE up.user_id = auth.uid()
        AND pop.object_name LIKE 'admin_%'
        AND pop.can_read = true
    ) INTO has_access;
  END IF;

  IF NOT has_access THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  cutoff := now() - (p_days || ' days')::interval;

  SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb), '[]'::jsonb)
  INTO result
  FROM (
    SELECT
      p.id::text AS user_id,
      COALESCE(p.full_name, p.username, 'Unknown') AS full_name,
      COALESCE((
        SELECT SUM(EXTRACT(EPOCH FROM (a.check_out_time::timestamp - a.check_in_time::timestamp)))::bigint
        FROM attendance a
        WHERE a.user_id = p.id
          AND a.date >= (cutoff::date)
          AND a.check_in_time IS NOT NULL
          AND a.check_out_time IS NOT NULL
      ), 0) AS total_usage_seconds,
      COALESCE((
        SELECT COALESCE(pv.module_name, pv.page)
        FROM user_page_views pv
        WHERE pv.user_id = p.id AND pv.created_at >= cutoff
        GROUP BY COALESCE(pv.module_name, pv.page)
        ORDER BY COUNT(*) DESC
        LIMIT 1
      ), '-') AS most_used_module,
      COALESCE((
        SELECT COUNT(*)::int
        FROM user_page_views pv
        WHERE pv.user_id = p.id AND pv.created_at >= cutoff
        GROUP BY COALESCE(pv.module_name, pv.page)
        ORDER BY COUNT(*) DESC
        LIMIT 1
      ), 0) AS most_used_count,
      COALESCE((
        SELECT COALESCE(pv.module_name, pv.page)
        FROM user_page_views pv
        WHERE pv.user_id = p.id AND pv.created_at >= cutoff
        GROUP BY COALESCE(pv.module_name, pv.page)
        ORDER BY COUNT(*) ASC
        LIMIT 1
      ), '-') AS least_used_module,
      COALESCE((
        SELECT COUNT(*)::int
        FROM user_page_views pv
        WHERE pv.user_id = p.id AND pv.created_at >= cutoff
        GROUP BY COALESCE(pv.module_name, pv.page)
        ORDER BY COUNT(*) ASC
        LIMIT 1
      ), 0) AS least_used_count,
      COALESCE((
        SELECT SUM(COALESCE(du.bytes_uploaded, 0) + COALESCE(du.bytes_downloaded, 0))::bigint
        FROM user_data_usage du
        WHERE du.user_id = p.id AND du.created_at >= cutoff
      ), 0) AS data_usage_bytes
    FROM profiles p
    WHERE p.user_status = 'active'
      AND EXISTS (
        SELECT 1 FROM attendance a2
        WHERE a2.user_id = p.id AND a2.date >= cutoff::date
      )
    ORDER BY full_name
  ) t;

  RETURN result;
END;
$$;



--
-- Name: get_all_product_units(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_all_product_units() RETURNS TABLE(product_id uuid, mapping_id uuid, uom_id uuid, code text, name text, category text, conversion_to_base numeric, is_base boolean, is_default_sales boolean, is_price_basis boolean, is_default_purchase boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT p.product_id, p.id, m.id, m.code, m.name, m.category, p.conversion_to_base, p.is_base, p.is_default_sales, COALESCE(p.is_price_basis, false), COALESCE(p.is_default_purchase, false)
  FROM product_uom_mapping p JOIN uom_master m ON m.id = p.uom_id JOIN products pr ON pr.id = p.product_id AND COALESCE(pr.is_active, true) = true LEFT JOIN enabled_units eu ON eu.uom_id = m.id
  WHERE COALESCE(p.is_active, true) = true AND COALESCE(eu.enabled, true) = true; $$;



--
-- Name: get_all_subordinates(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_all_subordinates(manager_user_id uuid) RETURNS TABLE(subordinate_user_id uuid, level integer, full_name text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH RECURSIVE subordinate_tree AS (
    -- Base case: the manager themselves (level 0)
    SELECT manager_user_id as user_id, 0 as lvl
    UNION ALL
    -- Recursive case: all employees reporting to current level
    SELECT e.user_id, st.lvl + 1
    FROM employees e
    INNER JOIN subordinate_tree st ON e.manager_id = st.user_id
    WHERE e.user_id != manager_user_id -- Prevent self-reference loops
  )
  SELECT 
    st.user_id as subordinate_user_id,
    st.lvl as level,
    COALESCE(p.full_name, p.username, 'Unknown') as full_name
  FROM subordinate_tree st
  LEFT JOIN profiles p ON p.id = st.user_id
  ORDER BY st.lvl, p.full_name;
END;
$$;



--
-- Name: get_attendance_report(text, text, text, text[], jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_attendance_report(p_layout text, p_rows text, p_columns text, p_values text[], p_filters jsonb) RETURNS SETOF jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_default_from DATE := CASE WHEN p_layout = 'tabular' THEN CURRENT_DATE - 14 ELSE CURRENT_DATE - 30 END;
  v_date_from DATE := COALESCE((p_filters->>'date_from')::DATE, v_default_from);
  v_date_to   DATE := COALESCE((p_filters->>'date_to')::DATE,   CURRENT_DATE);
  v_scope_user UUID := NULLIF(p_filters->>'scope_user_id','')::UUID;
  v_user_ids UUID[];
  v_rec JSONB;
  v_measure TEXT := COALESCE(p_values[1], 'present');
  v_row_key TEXT := COALESCE(NULLIF(p_rows,''), 'team_member');
  v_col_key TEXT := COALESCE(NULLIF(p_columns,''), 'date');
BEGIN
  IF v_scope_user IS NOT NULL THEN
    BEGIN
      SELECT ARRAY(SELECT s.subordinate_user_id FROM public.get_all_subordinates(v_scope_user) s) || v_scope_user
        INTO v_user_ids;
    EXCEPTION WHEN OTHERS THEN
      v_user_ids := ARRAY[v_scope_user];
    END;
  END IF;

  -- Report audience: narrow to the selected users and/or drop inactive ones.
  -- Only ever narrows -- the hierarchy scope above is a hard ceiling, so a
  -- report author cannot widen what a recipient sees. Evaluated on every run,
  -- so someone deactivated since the subscription was created drops out here.
  v_user_ids := public.report_apply_audience(v_user_ids, p_filters);


  IF p_layout = 'tabular' THEN
    FOR v_rec IN
      SELECT to_jsonb(t) FROM (
        SELECT
          a.date,
          COALESCE(p.full_name, p.username, 'Unknown') AS team_member,
          a.status,
          (
            SELECT bp.beat_name FROM public.beat_plans bp
            WHERE bp.user_id = a.user_id AND bp.plan_date = a.date LIMIT 1
          ) AS beat,
          a.check_in_time, a.check_out_time,
          COALESCE(a.total_hours, 0) AS total_hours
        FROM public.attendance a
        LEFT JOIN public.profiles p ON p.id = a.user_id
        WHERE a.date BETWEEN v_date_from AND v_date_to
          AND (v_user_ids IS NULL OR a.user_id = ANY(v_user_ids))
        ORDER BY a.date DESC, team_member ASC
        LIMIT 5000
      ) t
    LOOP RETURN NEXT v_rec; END LOOP;

  ELSIF p_layout = 'grouped' THEN
    FOR v_rec IN
      WITH days AS (SELECT generate_series(v_date_from, v_date_to, '1 day')::date AS d),
      roster AS (
        SELECT id AS user_id, COALESCE(full_name, username, 'Unknown') AS team_member
        FROM public.profiles
        WHERE is_active = true AND (v_user_ids IS NULL OR id = ANY(v_user_ids))
      ),
      base AS (
        SELECT d.d AS date, r.user_id, r.team_member,
               COALESCE(a.status, 'absent') AS status,
               a.total_hours
        FROM days d CROSS JOIN roster r
        LEFT JOIN public.attendance a ON a.user_id=r.user_id AND a.date=d.d
      )
      SELECT to_jsonb(t) FROM (
        SELECT
          CASE v_row_key
            WHEN 'date' THEN date::text
            WHEN 'status' THEN status
            ELSE team_member
          END AS grp,
          COALESCE(SUM(total_hours),0)::numeric(10,2) AS total_hours,
          COUNT(*) FILTER (WHERE status='present') AS present,
          COUNT(*) FILTER (WHERE status='absent')  AS absent,
          COUNT(*) FILTER (WHERE status='half_day_leave') AS half_day,
          COUNT(*) FILTER (WHERE status='leave') AS on_leave
        FROM base
        GROUP BY 1 ORDER BY 1 ASC LIMIT 2000
      ) t
    LOOP RETURN NEXT v_rec; END LOOP;

  ELSIF p_layout = 'matrix' THEN
    FOR v_rec IN
      WITH days AS (SELECT generate_series(v_date_from, v_date_to, '1 day')::date AS d),
      roster AS (
        SELECT id AS user_id, COALESCE(full_name, username, 'Unknown') AS team_member
        FROM public.profiles
        WHERE is_active = true AND (v_user_ids IS NULL OR id = ANY(v_user_ids))
      ),
      base AS (
        SELECT
          d.d AS date,
          r.user_id,
          r.team_member,
          COALESCE(a.status, 'absent') AS status,
          COALESCE(a.total_hours, 0)::numeric AS total_hours,
          (SELECT bp.beat_name FROM public.beat_plans bp
             WHERE bp.user_id = r.user_id AND bp.plan_date = d.d LIMIT 1) AS beat_raw,
          a.check_in_time, a.check_out_time
        FROM days d
        CROSS JOIN roster r
        LEFT JOIN public.attendance a ON a.user_id = r.user_id AND a.date = d.d
      ),
      enriched AS (
        SELECT
          CASE v_row_key
            WHEN 'date' THEN date::text
            WHEN 'status' THEN status
            WHEN 'beat' THEN COALESCE(beat_raw, 'No beat')
            WHEN 'check_in_time' THEN COALESCE(check_in_time::text, '—')
            WHEN 'check_out_time' THEN COALESCE(check_out_time::text, '—')
            ELSE team_member
          END AS row_val,
          CASE v_col_key
            WHEN 'date' THEN date::text
            WHEN 'status' THEN status
            WHEN 'beat' THEN COALESCE(beat_raw, 'No beat')
            WHEN 'check_in_time' THEN COALESCE(check_in_time::text, '—')
            WHEN 'check_out_time' THEN COALESCE(check_out_time::text, '—')
            ELSE team_member
          END AS col_val,
          status, total_hours
        FROM base
      ),
      agg AS (
        SELECT row_val, col_val,
          CASE v_measure
            WHEN 'total_hours' THEN COALESCE(AVG(total_hours), 0)::numeric(10,2)
            WHEN 'absent'      THEN COUNT(*) FILTER (WHERE status='absent')::numeric
            WHEN 'half_day'    THEN COUNT(*) FILTER (WHERE status='half_day_leave')::numeric
            WHEN 'on_leave'    THEN COUNT(*) FILTER (WHERE status='leave')::numeric
            ELSE               COUNT(*) FILTER (WHERE status='present')::numeric
          END AS val
        FROM enriched
        GROUP BY row_val, col_val
      )
      SELECT jsonb_build_object(v_row_key, row_val, v_col_key, col_val, v_measure, val)
      FROM agg
      WHERE val IS NOT NULL
      ORDER BY row_val, col_val
      LIMIT 5000
    LOOP RETURN NEXT v_rec; END LOOP;
  END IF;

  RETURN;
END; $$;



