--
-- Name: get_carry_forward_retailers(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_carry_forward_retailers(p_user uuid, p_date date) RETURNS TABLE(retailer_id uuid, retailer_name text, cancelled_on date)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_user <> auth.uid() AND NOT public.is_subordinate_of(auth.uid(), p_user) THEN RETURN; END IF;
  RETURN QUERY WITH latest AS (SELECT DISTINCT ON (v.retailer_id) v.retailer_id, v.planned_date, v.status, v.cancel_source FROM public.visits v WHERE v.user_id = p_user ORDER BY v.retailer_id, v.planned_date DESC)
  SELECT l.retailer_id, r.name::text, l.planned_date FROM latest l JOIN public.retailers r ON r.id = l.retailer_id
  WHERE l.status = 'cancelled' AND l.cancel_source = 'eod_auto' AND l.planned_date < p_date AND NOT EXISTS (SELECT 1 FROM public.visits v2 WHERE v2.user_id = p_user AND v2.retailer_id = l.retailer_id AND v2.planned_date >= p_date);
END; $$;



--
-- Name: get_database_metrics(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_database_metrics() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  result jsonb;
BEGIN
  IF NOT is_system_admin(auth.uid()) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  SELECT jsonb_build_object(
    'db_size_bytes', pg_database_size(current_database()),
    'uptime_seconds', EXTRACT(EPOCH FROM (now() - pg_postmaster_start_time()))::bigint,
    'postmaster_start_time', pg_postmaster_start_time(),
    'active_connections', (SELECT count(*) FROM pg_stat_activity WHERE state = 'active'),
    'total_connections', (SELECT count(*) FROM pg_stat_activity),
    'cache_hit_ratio', (SELECT ROUND(
      CASE WHEN (blks_hit + blks_read) = 0 THEN 0
      ELSE blks_hit::numeric / (blks_hit + blks_read) * 100 END, 2)
      FROM pg_stat_database WHERE datname = current_database()),
    'xact_commit', (SELECT xact_commit FROM pg_stat_database WHERE datname = current_database()),
    'xact_rollback', (SELECT xact_rollback FROM pg_stat_database WHERE datname = current_database()),
    'table_count', (SELECT count(*) FROM information_schema.tables 
                    WHERE table_schema = 'public' AND table_type = 'BASE TABLE')
  ) INTO result;

  RETURN result;
END;
$$;



--
-- Name: get_db_health_drift(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_db_health_drift(p_days integer DEFAULT 7) RETURNS TABLE(change_type text, object_type text, parent_name text, object_name text, detail_before jsonb, detail_after jsonb)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  WITH cur AS (SELECT id, captured_at FROM db_health_snapshots ORDER BY captured_at DESC LIMIT 1),
       base AS (SELECT id FROM db_health_snapshots
                WHERE captured_at <= (SELECT captured_at FROM cur) - make_interval(days => GREATEST(p_days,0))
                  AND id <> (SELECT id FROM cur)
                ORDER BY captured_at DESC LIMIT 1),
       ok AS (SELECT EXISTS(SELECT 1 FROM base) AS has_base),
       b AS (SELECT o.* FROM db_health_objects o, ok WHERE ok.has_base AND o.snapshot_id=(SELECT id FROM base)),
       c AS (SELECT o.* FROM db_health_objects o, ok WHERE ok.has_base AND o.snapshot_id=(SELECT id FROM cur))
  SELECT 'removed', b.object_type, b.parent_name, b.object_name, b.detail, NULL::jsonb
  FROM b LEFT JOIN c ON c.object_type=b.object_type AND c.object_name=b.object_name
                    AND c.parent_name IS NOT DISTINCT FROM b.parent_name
  WHERE c.id IS NULL
  UNION ALL
  SELECT 'added', c.object_type, c.parent_name, c.object_name, NULL::jsonb, c.detail
  FROM c LEFT JOIN b ON b.object_type=c.object_type AND b.object_name=c.object_name
                    AND b.parent_name IS NOT DISTINCT FROM c.parent_name
  WHERE b.id IS NULL
  UNION ALL
  SELECT 'modified', c.object_type, c.parent_name, c.object_name, b.detail, c.detail
  FROM c JOIN b ON b.object_type=c.object_type AND b.object_name=c.object_name
               AND b.parent_name IS NOT DISTINCT FROM c.parent_name
  WHERE c.object_type IN ('column','policy','trigger','cron_job','function')
    AND b.detail IS DISTINCT FROM c.detail
  ORDER BY 1,2,3,4;
$$;



--
-- Name: get_db_health_object_history(text, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_db_health_object_history(p_object_type text, p_object_name text, p_parent_name text DEFAULT NULL::text, p_days integer DEFAULT 90) RETURNS TABLE(captured_at timestamp with time zone, present boolean, detail jsonb)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT s.captured_at, (o.id IS NOT NULL), o.detail
  FROM db_health_snapshots s
  LEFT JOIN db_health_objects o
    ON o.snapshot_id=s.id AND o.object_type=p_object_type AND o.object_name=p_object_name
   AND (p_parent_name IS NULL OR o.parent_name=p_parent_name)
  WHERE s.captured_at >= now() - make_interval(days => GREATEST(p_days,1))
  ORDER BY s.captured_at;
$$;



--
-- Name: get_db_health_overview(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_db_health_overview() RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  WITH latest AS (SELECT * FROM db_health_snapshots ORDER BY captured_at DESC LIMIT 1),
       prev AS (SELECT * FROM db_health_snapshots
                WHERE captured_at < (SELECT captured_at FROM latest)
                ORDER BY captured_at DESC LIMIT 1)
  SELECT jsonb_build_object(
    'snapshot_id',l.id,'captured_at',l.captured_at,'source',l.source,
    'previous_at',p.captured_at,'db_size_bytes',l.db_size_bytes,
    'total_row_estimate',l.total_row_estimate,
    'metrics', jsonb_build_array(
      jsonb_build_object('key','tables','label','Tables','value',l.table_count,'delta',l.table_count-p.table_count),
      jsonb_build_object('key','columns','label','Columns','value',l.column_count,'delta',l.column_count-p.column_count),
      jsonb_build_object('key','views','label','Views','value',l.view_count,'delta',l.view_count-p.view_count),
      jsonb_build_object('key','policies','label','RLS Policies','value',l.rls_policy_count,'delta',l.rls_policy_count-p.rls_policy_count),
      jsonb_build_object('key','rls_enabled','label','RLS-enabled Tables','value',l.rls_enabled_table_count,'delta',l.rls_enabled_table_count-p.rls_enabled_table_count),
      jsonb_build_object('key','rls_disabled','label','RLS-DISABLED Tables','value',l.rls_disabled_table_count,'delta',l.rls_disabled_table_count-p.rls_disabled_table_count),
      jsonb_build_object('key','functions','label','Functions','value',l.function_count,'delta',l.function_count-p.function_count),
      jsonb_build_object('key','triggers','label','Triggers','value',l.trigger_count,'delta',l.trigger_count-p.trigger_count),
      jsonb_build_object('key','indexes','label','Indexes','value',l.index_count,'delta',l.index_count-p.index_count),
      jsonb_build_object('key','foreign_keys','label','Foreign Keys','value',l.foreign_key_count,'delta',l.foreign_key_count-p.foreign_key_count),
      jsonb_build_object('key','enums','label','Enum Types','value',l.enum_count,'delta',l.enum_count-p.enum_count),
      jsonb_build_object('key','sequences','label','Sequences','value',l.sequence_count,'delta',l.sequence_count-p.sequence_count),
      jsonb_build_object('key','extensions','label','Extensions','value',l.extension_count,'delta',l.extension_count-p.extension_count),
      jsonb_build_object('key','cron_jobs','label','Cron Jobs','value',l.cron_job_count,'delta',l.cron_job_count-p.cron_job_count),
      jsonb_build_object('key','cron_jobs_active','label','Cron Jobs Active','value',l.cron_job_active_count,'delta',l.cron_job_active_count-p.cron_job_active_count)
    ))
  FROM latest l LEFT JOIN prev p ON true;
$$;



--
-- Name: get_db_health_trend(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_db_health_trend(p_days integer DEFAULT 30) RETURNS TABLE(captured_at timestamp with time zone, source text, table_count integer, column_count integer, rls_policy_count integer, rls_disabled_table_count integer, function_count integer, trigger_count integer, index_count integer, cron_job_count integer, db_size_bytes bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT s.captured_at, s.source, s.table_count, s.column_count, s.rls_policy_count,
         s.rls_disabled_table_count, s.function_count, s.trigger_count, s.index_count,
         s.cron_job_count, s.db_size_bytes
  FROM db_health_snapshots s
  WHERE s.captured_at >= now() - make_interval(days => GREATEST(p_days,1))
  ORDER BY s.captured_at;
$$;



