--
-- Name: get_missed_beat_days(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_missed_beat_days(p_user uuid, p_lookback integer DEFAULT 14) RETURNS TABLE(missed_date date, retailer_count integer, on_leave boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT (p_user = auth.uid() OR public.is_subordinate_of(auth.uid(), p_user)) THEN RETURN; END IF;
  RETURN QUERY WITH day_stats AS (SELECT v.planned_date AS d, COUNT(*) FILTER (WHERE v.status IN ('productive','unproductive','in-progress','in_progress')) AS attended_count, COUNT(*) FILTER (WHERE v.status IN ('planned','cancelled')) AS pending_count, COUNT(DISTINCT v.retailer_id) FILTER (WHERE v.status IN ('planned','cancelled')) AS unvisited_retailers FROM visits v WHERE v.user_id = p_user AND v.planned_date BETWEEN (CURRENT_DATE - p_lookback) AND (CURRENT_DATE - 1) GROUP BY v.planned_date)
  SELECT ds.d, ds.unvisited_retailers::integer, EXISTS (SELECT 1 FROM leave_applications la WHERE la.user_id = p_user AND la.status = 'approved' AND ds.d BETWEEN la.start_date AND la.end_date) FROM day_stats ds WHERE ds.attended_count = 0 AND ds.pending_count > 0 ORDER BY ds.d DESC;
END; $$;



--
-- Name: get_my_operations_today(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_operations_today(p_date date DEFAULT CURRENT_DATE) RETURNS TABLE(retailer_id uuid, retailer_name text, beat_id text, access_type text, pending_collection numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH base AS (
    SELECT r.id AS retailer_id, r.name AS retailer_name, r.beat_id, 'owned'::text AS access_type
      FROM public.retailers r WHERE r.user_id = auth.uid()
    UNION
    SELECT r.id, r.name, r.beat_id, 'shared'::text
      FROM public.retailer_shared_access s
      JOIN public.retailers r ON r.id = s.retailer_id
     WHERE s.shared_to_user_id = auth.uid()
       AND s.is_active = true
       AND s.effective_from <= now()
       AND (s.effective_to IS NULL OR s.effective_to >= now())
  ),
  pend AS (
    SELECT retailer_id, SUM(COALESCE(balance_due,0)) AS pending
      FROM public.distributor_secondary_invoices
     WHERE COALESCE(balance_due,0) > 0
     GROUP BY retailer_id
  )
  SELECT b.retailer_id, b.retailer_name, b.beat_id, b.access_type,
         COALESCE(p.pending, 0)
    FROM base b LEFT JOIN pend p ON p.retailer_id = b.retailer_id
   ORDER BY b.retailer_name;
$$;



--
-- Name: get_operations_exceptions(date, date, text[], uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_operations_exceptions(p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_types text[] DEFAULT NULL::text[], p_user uuid DEFAULT NULL::uuid) RETURNS TABLE(order_id uuid, invoice_number text, order_date date, entered_on timestamp with time zone, is_backdated boolean, is_on_behalf boolean, is_out_of_beat boolean, is_edited boolean, retailer_id uuid, retailer_name text, collector_id uuid, placed_by_id uuid, owner_id uuid, collector_name text, placed_by_name text, owner_name text, reason text, oob_location jsonb, total_amount numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.user_has_permission(auth.uid(), 'operations_config', 'can_edit') THEN RETURN; END IF;
  RETURN QUERY
  SELECT o.id, o.invoice_number, o.order_date, o.created_at, COALESCE(o.is_backdated, false), (o.placed_by_user_id IS NOT NULL), COALESCE(o.is_out_of_beat, false), COALESCE(o.is_edited, false),
    o.retailer_id, r.name, o.user_id, o.placed_by_user_id, o.owner_id_snapshot, pc.full_name, pp.full_name, po.full_name, COALESCE(o.backdate_reason, o.out_of_beat_reason), o.oob_location, o.total_amount
  FROM public.orders o LEFT JOIN public.retailers r ON r.id = o.retailer_id LEFT JOIN public.profiles pc ON pc.id = o.user_id LEFT JOIN public.profiles pp ON pp.id = o.placed_by_user_id LEFT JOIN public.profiles po ON po.id = o.owner_id_snapshot
  WHERE COALESCE(o.status, '') <> 'cancelled' AND (COALESCE(o.is_backdated, false) OR o.placed_by_user_id IS NOT NULL OR COALESCE(o.is_out_of_beat, false) OR COALESCE(o.is_edited, false))
    AND (p_from IS NULL OR o.order_date >= p_from) AND (p_to IS NULL OR o.order_date <= p_to) AND (p_user IS NULL OR o.user_id = p_user OR o.placed_by_user_id = p_user)
    AND (p_types IS NULL OR array_length(p_types, 1) IS NULL OR (COALESCE(o.is_backdated, false) AND 'backdated' = ANY(p_types)) OR (o.placed_by_user_id IS NOT NULL AND 'on_behalf' = ANY(p_types)) OR (COALESCE(o.is_out_of_beat, false) AND 'out_of_beat' = ANY(p_types)) OR (COALESCE(o.is_edited, false) AND 'edited' = ANY(p_types)))
  ORDER BY o.created_at DESC;
END; $$;



--
-- Name: get_orders_report(text, text, text, text[], jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_orders_report(p_layout text, p_rows text, p_columns text, p_values text[], p_filters jsonb) RETURNS SETOF jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_date_from DATE := COALESCE((p_filters->>'date_from')::DATE, CURRENT_DATE - 30);
  v_date_to   DATE := COALESCE((p_filters->>'date_to')::DATE,   CURRENT_DATE);
  v_scope_user UUID := NULLIF(p_filters->>'scope_user_id','')::UUID;
  v_user_ids UUID[];
  v_rec JSONB;
BEGIN
  IF v_scope_user IS NOT NULL THEN
    BEGIN
      SELECT ARRAY(SELECT s.subordinate_user_id FROM public.get_all_subordinates(v_scope_user) s) || v_scope_user
        INTO v_user_ids;
    EXCEPTION WHEN OTHERS THEN
      v_user_ids := ARRAY[v_scope_user];
    END;
  END IF;

  -- Report audience: narrow to the selected users and/or drop inactive ones.
  -- Only ever narrows -- the hierarchy scope above is a hard ceiling, so a
  -- report author cannot widen what a recipient sees. Evaluated on every run,
  -- so someone deactivated since the subscription was created drops out here.
  v_user_ids := public.report_apply_audience(v_user_ids, p_filters);


  IF p_layout = 'tabular' THEN
    FOR v_rec IN
      SELECT to_jsonb(t) FROM (
        SELECT
          o.order_date::date AS order_date,
          o.invoice_number AS order_number,
          COALESCE(p.full_name, p.username, 'Unknown') AS team_member,
          o.retailer_name AS retailer,
          b.beat_name AS beat,
          o.status,
          o.payment_status,
          o.delivery_status,
          o.distributor_name AS distributor,
          1 AS order_count,
          COALESCE(o.total_amount, 0) AS total_amount,
          COALESCE(o.subtotal, 0) AS subtotal,
          COALESCE(o.discount_amount, 0) AS discount_amount
        FROM public.orders o
        LEFT JOIN public.profiles p ON p.id = o.user_id
        LEFT JOIN public.beats b ON b.beat_id = o.beat_id
        WHERE o.order_date::date BETWEEN v_date_from AND v_date_to
          AND (v_user_ids IS NULL OR o.user_id = ANY(v_user_ids))
        ORDER BY o.order_date ASC, o.created_at ASC
        LIMIT 5000
      ) t
    LOOP RETURN NEXT v_rec; END LOOP;
  ELSE
    FOR v_rec IN
      SELECT to_jsonb(t) FROM (
        SELECT
          CASE p_rows
            WHEN 'retailer' THEN o.retailer_name
            WHEN 'order_date' THEN o.order_date::date::text
            WHEN 'status' THEN o.status
            WHEN 'payment_status' THEN o.payment_status
            WHEN 'delivery_status' THEN o.delivery_status
            WHEN 'distributor' THEN o.distributor_name
            WHEN 'beat' THEN b.beat_name
            ELSE COALESCE(p.full_name, p.username, 'Unknown')
          END AS grp,
          COUNT(*) AS order_count,
          COALESCE(SUM(o.total_amount),0)::numeric(14,2) AS total_amount,
          COALESCE(SUM(o.subtotal),0)::numeric(14,2) AS subtotal,
          COALESCE(SUM(o.discount_amount),0)::numeric(14,2) AS discount_amount
        FROM public.orders o
        LEFT JOIN public.profiles p ON p.id = o.user_id
        LEFT JOIN public.beats b ON b.beat_id = o.beat_id
        WHERE o.order_date::date BETWEEN v_date_from AND v_date_to
          AND (v_user_ids IS NULL OR o.user_id = ANY(v_user_ids))
        GROUP BY 1
        ORDER BY 1 ASC
        LIMIT 2000
      ) t
    LOOP RETURN NEXT v_rec; END LOOP;
  END IF;
END; $$;



--
-- Name: get_password_reset_stats(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_password_reset_stats() RETURNS TABLE(email text, total_attempts bigint, failed_attempts bigint, is_locked boolean, last_attempt timestamp with time zone)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT 
    pra.email,
    COUNT(*)::BIGINT as total_attempts,
    COUNT(*) FILTER (WHERE was_successful = false)::BIGINT as failed_attempts,
    public.is_account_locked(pra.email) as is_locked,
    MAX(pra.attempted_at) as last_attempt
  FROM public.password_reset_attempts pra
  WHERE pra.attempted_at > NOW() - INTERVAL '24 hours'
    AND public.has_role(auth.uid(), 'admin'::public.app_role)
  GROUP BY pra.email
  ORDER BY last_attempt DESC;
$$;



--
-- Name: get_product_revenue_performance(text, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_product_revenue_performance(user_full_name text, start_date date DEFAULT '2025-12-19'::date, end_date date DEFAULT '2025-12-26'::date) RETURNS TABLE(full_name text, product_name text, unit text, quantity_sold bigint, revenue numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    p.full_name::text,
    oi.product_name::text,
    oi.unit::text,
    SUM(oi.quantity)::bigint AS quantity_sold,
    SUM(oi.total)::numeric   AS revenue
  FROM orders o
  JOIN order_items oi ON oi.order_id = o.id
  JOIN profiles p ON o.user_id = p.id
  WHERE o.created_at::date BETWEEN start_date AND end_date
    AND o.status IN ('confirmed','delivered')       -- was missing: excludes cancelled/replaced/pending/draft
    AND o.cancelled_at IS NULL
    AND trim(p.full_name) ILIKE trim(user_full_name)
  GROUP BY p.full_name, oi.product_name, oi.unit
  ORDER BY revenue DESC;
END;
$$;



