CREATE FUNCTION public.get_product_units(p_product_id uuid) RETURNS TABLE(mapping_id uuid, uom_id uuid, code text, name text, category text, conversion_to_base numeric, is_base boolean, is_default_sales boolean, is_active boolean, is_price_basis boolean, is_default_purchase boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT p.id, m.id, m.code, m.name, m.category, p.conversion_to_base, p.is_base, p.is_default_sales, COALESCE(p.is_active, true), COALESCE(p.is_price_basis, false), COALESCE(p.is_default_purchase, false)
  FROM public.product_uom_mapping p JOIN public.uom_master m ON m.id = p.uom_id LEFT JOIN public.enabled_units eu ON eu.uom_id = m.id
  WHERE p.product_id = p_product_id AND COALESCE(p.is_active, true) = true AND COALESCE(eu.enabled, true) = true ORDER BY p.is_base DESC, p.is_default_sales DESC, m.name; $$;



--
-- Name: get_productivity_summary(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_productivity_summary(user_full_name text) RETURNS TABLE(full_name text, planned_date text, productive_visits bigint, unproductive_visits bigint, total_visits bigint, productivity_percentage numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    p.full_name::TEXT,
    TO_CHAR(v.planned_date, 'FMMonth FMDD, YYYY') AS planned_date,
    COUNT(CASE WHEN v.status = 'productive' THEN 1 END)   AS productive_visits,
    COUNT(CASE WHEN v.status = 'unproductive' THEN 1 END) AS unproductive_visits,
    COUNT(v.id) AS total_visits,
    ROUND(
      COUNT(CASE WHEN v.status = 'productive' THEN 1 END)::NUMERIC /
      NULLIF(COUNT(v.id), 0) * 100, 2
    ) AS productivity_percentage
  FROM visits v
  JOIN profiles p ON v.user_id = p.id
  WHERE v.status IN ('productive', 'unproductive')
    AND v.planned_date BETWEEN date_trunc('month', CURRENT_DATE)::date AND CURRENT_DATE  -- was hardcoded 2025-12-19..26
    AND p.full_name ILIKE user_full_name
  GROUP BY p.full_name, v.planned_date
  ORDER BY v.planned_date DESC, p.full_name;
END;
$$;



--
-- Name: get_productivity_summary(text, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_productivity_summary(user_full_name text, start_date date DEFAULT '2025-12-19'::date, end_date date DEFAULT '2025-12-26'::date) RETURNS TABLE(full_name text, planned_date text, productive_visits bigint, unproductive_visits bigint, total_visits bigint, productivity_percentage numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    p.full_name::TEXT,
    TO_CHAR(v.planned_date, 'FMMonth FMDD, YYYY') AS planned_date,
    COUNT(CASE WHEN v.status = 'productive' THEN 1 END) AS productive_visits,
    COUNT(CASE WHEN v.status = 'unproductive' THEN 1 END) AS unproductive_visits,
    COUNT(v.id) AS total_visits,
    ROUND(
      COUNT(CASE WHEN v.status = 'productive' THEN 1 END)::NUMERIC /
      NULLIF(COUNT(v.id), 0) * 100,
      2
    ) AS productivity_percentage
  FROM visits v
  JOIN profiles p ON v.user_id = p.id
  WHERE v.status IN ('productive', 'unproductive')
    AND v.planned_date BETWEEN start_date AND end_date
    AND p.full_name ILIKE user_full_name
  GROUP BY p.full_name, v.planned_date
  ORDER BY v.planned_date DESC, p.full_name;
END;
$$;



