--
-- Name: get_report_scope_users(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_report_scope_users() RETURNS TABLE(user_id uuid, full_name text, level integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if user_has_permission(auth.uid(), 'analytics_user_filter', 'can_view_all') then
    return query
      select p.id, coalesce(p.full_name, p.username, 'Unknown')::text, 1
        from profiles p
       where coalesce(p.is_active, true)
         and p.id <> auth.uid()
       order by 2;
  else
    return query
      select s.subordinate_user_id, s.full_name, s.level
        from get_all_subordinates(auth.uid()) s
       where s.level > 0
       order by s.level, s.full_name;
  end if;
end;
$$;



--
-- Name: get_reporting_chain(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_reporting_chain(p_user_id uuid) RETURNS TABLE(manager_id uuid, level integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH RECURSIVE chain AS (
    SELECT e.manager_id, 1 AS level
    FROM employees e
    WHERE e.user_id = p_user_id AND e.manager_id IS NOT NULL
    UNION ALL
    SELECT e.manager_id, c.level + 1
    FROM chain c JOIN employees e ON e.user_id = c.manager_id
    WHERE e.manager_id IS NOT NULL AND c.level < 10
  )
  SELECT chain.manager_id, chain.level FROM chain ORDER BY chain.level;
$$;



