--
-- Name: get_visits_report(text, text, text, text[], jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_visits_report(p_layout text, p_rows text, p_columns text, p_values text[], p_filters jsonb) RETURNS SETOF jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_date_from DATE := COALESCE((p_filters->>'date_from')::DATE, CURRENT_DATE - 30);
  v_date_to   DATE := COALESCE((p_filters->>'date_to')::DATE,   CURRENT_DATE);
  v_scope_user UUID := NULLIF(p_filters->>'scope_user_id','')::UUID;
  v_user_ids UUID[];
  v_rec JSONB;
BEGIN
  IF v_scope_user IS NOT NULL THEN
    BEGIN
      SELECT ARRAY(SELECT s.subordinate_user_id FROM public.get_all_subordinates(v_scope_user) s) || v_scope_user
        INTO v_user_ids;
    EXCEPTION WHEN OTHERS THEN
      v_user_ids := ARRAY[v_scope_user];
    END;
  END IF;

  -- Report audience: narrow to the selected users and/or drop inactive ones.
  -- Only ever narrows -- the hierarchy scope above is a hard ceiling, so a
  -- report author cannot widen what a recipient sees. Evaluated on every run,
  -- so someone deactivated since the subscription was created drops out here.
  v_user_ids := public.report_apply_audience(v_user_ids, p_filters);


  IF p_layout = 'tabular' THEN
    FOR v_rec IN
      SELECT to_jsonb(t) FROM (
        SELECT
          v.planned_date AS visit_date,
          COALESCE(p.full_name, p.username, 'Unknown') AS team_member,
          b.beat_name AS beat,
          r.name AS retailer,
          v.status,
          v.check_in_time,
          v.check_out_time,
          1 AS visit_count,
          CASE WHEN v.status = 'productive' OR EXISTS (
            SELECT 1 FROM public.orders o
             WHERE o.visit_id = v.id AND o.status <> 'cancelled'
          ) THEN 1 ELSE 0 END AS productive_visits
        FROM public.visits v
        LEFT JOIN public.profiles p ON p.id = v.user_id
        LEFT JOIN public.retailers r ON r.id = v.retailer_id
        LEFT JOIN public.beats b ON b.beat_id = r.beat_id
        WHERE v.planned_date BETWEEN v_date_from AND v_date_to
          AND (v_user_ids IS NULL OR v.user_id = ANY(v_user_ids))
        ORDER BY v.planned_date ASC, v.check_in_time ASC NULLS LAST
        LIMIT 5000
      ) t
    LOOP RETURN NEXT v_rec; END LOOP;
  ELSE
    FOR v_rec IN
      SELECT to_jsonb(t) FROM (
        SELECT
          CASE p_rows
            WHEN 'beat' THEN b.beat_name
            WHEN 'retailer' THEN r.name
            WHEN 'visit_date' THEN v.planned_date::text
            WHEN 'status' THEN v.status
            ELSE COALESCE(p.full_name, p.username, 'Unknown')
          END AS grp,
          COUNT(*) AS visit_count,
          COUNT(*) FILTER (
            WHERE v.status='productive' OR EXISTS (
              SELECT 1 FROM public.orders o
               WHERE o.visit_id = v.id AND o.status <> 'cancelled'
            )
          ) AS productive_visits
        FROM public.visits v
        LEFT JOIN public.profiles p ON p.id = v.user_id
        LEFT JOIN public.retailers r ON r.id = v.retailer_id
        LEFT JOIN public.beats b ON b.beat_id = r.beat_id
        WHERE v.planned_date BETWEEN v_date_from AND v_date_to
          AND (v_user_ids IS NULL OR v.user_id = ANY(v_user_ids))
        GROUP BY 1
        ORDER BY 1 ASC
        LIMIT 2000
      ) t
    LOOP RETURN NEXT v_rec; END LOOP;
  END IF;
END; $$;



--
-- Name: guard_critical_column_drops(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_critical_column_drops() RETURNS event_trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  obj record;
BEGIN
  FOR obj IN SELECT * FROM pg_event_trigger_dropped_objects() LOOP
    IF obj.object_type = 'table column'
       AND obj.schema_name = 'public'
       AND split_part(obj.object_identity, '.', 2) IN (
         'products', 'product_variants', 'orders', 'order_items', 'retailers'
       )
       AND NOT obj.is_temporary
    THEN
      -- Allow drops that happen as part of dropping the whole table
      IF NOT EXISTS (
        SELECT 1 FROM pg_event_trigger_dropped_objects()
        WHERE object_type = 'table'
          AND object_identity = split_part(obj.object_identity, '.', 1) || '.' || split_part(obj.object_identity, '.', 2)
      ) THEN
        RAISE EXCEPTION
          'Blocked: dropping column "%" is not allowed. Critical sales columns must be changed via a reviewed migration, not the dashboard table editor.',
          obj.object_identity;
      END IF;
    END IF;
  END LOOP;
END;
$$;



--
-- Name: guard_destructive_ddl(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_destructive_ddl() RETURNS event_trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  q text;
BEGIN
  IF coalesce(current_setting('app.allow_destructive', true), '') = 'on' THEN
    RETURN;
  END IF;

  IF tg_tag = 'DROP TABLE' THEN
    RAISE EXCEPTION 'BLOCKED: DROP TABLE is disabled on production.'
      USING ERRCODE = '42501',
            HINT = 'Intentional? Take a backup, then run  SET LOCAL app.allow_destructive = ''on'';  in the same transaction and retry. Never use the Dashboard Table Editor delete button.';
  END IF;

  IF tg_tag = 'ALTER TABLE' THEN
    q := lower(coalesce(current_query(), ''));

    IF q ~ '\mdrop\s+column\M' THEN
      RAISE EXCEPTION 'BLOCKED: ALTER TABLE ... DROP COLUMN is disabled on production.'
        USING ERRCODE = '42501',
              HINT = 'Intentional? Take a backup, then SET LOCAL app.allow_destructive = ''on''; and retry.';
    END IF;

    IF q ~ '\mrename\s+(column|to|constraint)\M' THEN
      RAISE EXCEPTION 'BLOCKED: ALTER TABLE ... RENAME is disabled on production.'
        USING ERRCODE = '42501',
              HINT = 'Renaming a live column silently breaks every query using the old name -- this is exactly what broke the catalogue on 27 Jul (products.rate -> price). Intentional? SET LOCAL app.allow_destructive = ''on''; and retry.';
    END IF;
  END IF;
END;
$$;



--
-- Name: FUNCTION guard_destructive_ddl(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.guard_destructive_ddl() IS 'Blocks DROP TABLE / DROP COLUMN / RENAME unless app.allow_destructive=on. Added 2026-08-05 after the 27-Jul products.rate rename incident.';



--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  INSERT INTO public.profiles (id, username, full_name, phone_number, recovery_email, hint_question, hint_answer)
  VALUES (
    new.id,
    COALESCE(new.raw_user_meta_data->>'username', split_part(new.email, '@', 1)),
    COALESCE(new.raw_user_meta_data->>'full_name', 'User'),
    new.raw_user_meta_data->>'phone_number',
    new.raw_user_meta_data->>'recovery_email',
    COALESCE(new.raw_user_meta_data->>'hint_question', 'What is your favorite color?'),
    COALESCE(new.raw_user_meta_data->>'hint_answer', 'default')
  )
  ON CONFLICT (id) DO NOTHING;
  RETURN new;
END;
$$;



--
-- Name: has_role(uuid, public.app_role); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF _role = 'admin'::app_role THEN
    RETURN EXISTS (
      SELECT 1 FROM public.user_profiles up
      JOIN public.security_profiles sp ON sp.id = up.profile_id
      WHERE up.user_id = _user_id AND sp.is_system = true
    );
  END IF;
  RETURN EXISTS (
    SELECT 1 FROM public.user_roles
    WHERE user_id = _user_id AND role = _role
  );
END;
$$;



--
-- Name: hash_hint_answer(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hash_hint_answer(answer text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Use md5 with a salt for basic security (better than plaintext)
  RETURN 'hash:' || md5('security_salt_2024_' || LOWER(TRIM(answer)) || '_hint_protection');
END;
$$;



--
-- Name: hash_hint_answer_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hash_hint_answer_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Only hash if hint_answer is provided and not already hashed
  IF NEW.hint_answer IS NOT NULL AND NEW.hint_answer NOT LIKE 'hash:%' THEN
    NEW.hint_answer := public.hash_hint_answer(NEW.hint_answer);
  END IF;
  
  RETURN NEW;
END;
$$;



--
-- Name: initialize_leave_policy_balances(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.initialize_leave_policy_balances(p_policy_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_policy RECORD;
  v_user RECORD;
  v_credit NUMERIC;
  v_current_year INTEGER;
  v_current_month INTEGER;
  v_month INTEGER;
  v_already_credited BOOLEAN;
BEGIN
  v_current_year := EXTRACT(YEAR FROM CURRENT_DATE)::INTEGER;
  v_current_month := EXTRACT(MONTH FROM CURRENT_DATE)::INTEGER;

  SELECT lp.leave_type_id, lp.yearly_entitlement, lp.accrual_type, lt.name as leave_name
  INTO v_policy
  FROM leave_policy lp
  JOIN leave_types lt ON lt.id = lp.leave_type_id
  WHERE lp.id = p_policy_id AND lp.accrual_type = 'monthly';

  IF NOT FOUND THEN
    RETURN;
  END IF;

  v_credit := ROUND(v_policy.yearly_entitlement / 12.0, 2);

  FOR v_user IN SELECT id FROM profiles WHERE user_status = 'active'
  LOOP
    INSERT INTO leave_balance (user_id, leave_type_id, year, opening_balance, used_balance)
    VALUES (v_user.id, v_policy.leave_type_id, v_current_year, 0, 0)
    ON CONFLICT (user_id, leave_type_id, year) DO NOTHING;

    FOR v_month IN 1..v_current_month
    LOOP
      SELECT EXISTS (
        SELECT 1 FROM leave_accrual_log
        WHERE user_id = v_user.id
          AND leave_type_id = v_policy.leave_type_id
          AND year = v_current_year
          AND month = v_month
          AND accrual_type = 'monthly'
      ) INTO v_already_credited;

      IF NOT v_already_credited THEN
        UPDATE leave_balance
        SET opening_balance = opening_balance + v_credit, updated_at = now()
        WHERE user_id = v_user.id
          AND leave_type_id = v_policy.leave_type_id
          AND year = v_current_year;

        INSERT INTO leave_accrual_log (user_id, leave_type_id, year, month, accrual_type, days_credited, balance_after, notes)
        VALUES (
          v_user.id, v_policy.leave_type_id, v_current_year, v_month, 'monthly', v_credit,
          (SELECT remaining_balance FROM leave_balance
           WHERE user_id = v_user.id AND leave_type_id = v_policy.leave_type_id AND year = v_current_year),
          'Backfill month ' || v_month || ' for ' || v_policy.leave_name
        );
      END IF;
    END LOOP;
  END LOOP;
END;
$$;



