--
-- Name: is_account_locked(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_account_locked(user_email text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  failed_attempts INTEGER;
BEGIN
  -- Count failed attempts in the last hour
  SELECT COUNT(*) INTO failed_attempts
  FROM public.password_reset_attempts
  WHERE email = user_email
    AND attempted_at > NOW() - INTERVAL '1 hour'
    AND was_successful = false;
  
  -- Account is locked if 5 or more failed attempts in last hour
  RETURN failed_attempts >= 5;
END;
$$;



