-- Name: log_deleted_record(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_deleted_record() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_user_id uuid; v_user_name text; v_record_id text;
BEGIN
  v_user_id := auth.uid();
  SELECT COALESCE(full_name, username, email, v_user_id::text) INTO v_user_name FROM public.profiles WHERE id = v_user_id;
  v_record_id := COALESCE((OLD::jsonb->>'id'), (OLD::jsonb->>'beat_id'), (OLD::jsonb->>'order_id'), 'unknown');
  INSERT INTO public.deleted_records_audit (table_name, record_id, record_data, deleted_by, deleted_by_name, deleted_at)
  VALUES (TG_TABLE_NAME, v_record_id, row_to_json(OLD)::jsonb, v_user_id, v_user_name, now());
  RETURN OLD;
END; $$;



--
-- Name: log_destructive_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_destructive_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pk text;
  v_app_user uuid;
BEGIN
  BEGIN
    v_app_user := auth.uid();
  EXCEPTION WHEN OTHERS THEN
    v_app_user := NULL;
  END;

  IF TG_TABLE_NAME = 'beats' THEN
    v_pk := COALESCE(OLD.beat_id, OLD.id::text);
  ELSE
    v_pk := OLD.id::text;
  END IF;

  INSERT INTO public.destructive_audit_log
    (table_name, row_pk, row_data, app_user, application_name)
  VALUES
    (TG_TABLE_NAME, v_pk, to_jsonb(OLD), v_app_user,
     current_setting('application_name', true));

  RETURN OLD;
END;
$$;



