--
-- Name: mark_attendance_on_leave_approval(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_attendance_on_leave_approval() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  leave_date DATE;
  v_leave_type_name TEXT;
BEGIN
  IF NEW.status = 'approved' AND OLD.status != 'approved' THEN
    -- Get leave type name
    SELECT name INTO v_leave_type_name FROM leave_types WHERE id = NEW.leave_type_id;
    
    -- Mark attendance for each day of leave
    FOR leave_date IN SELECT generate_series(NEW.start_date, NEW.end_date, '1 day')::DATE
    LOOP
      INSERT INTO attendance (user_id, date, status, notes)
      VALUES (NEW.user_id, leave_date, 
              CASE WHEN NEW.is_half_day THEN 'half_day_leave' ELSE 'leave' END,
              'Auto-marked: ' || COALESCE(v_leave_type_name, 'Leave'))
      ON CONFLICT (user_id, date) 
      DO UPDATE SET 
        status = EXCLUDED.status, 
        notes = EXCLUDED.notes,
        updated_at = now();
    END LOOP;
    
    -- Update final approved by
    NEW.final_approved_by := auth.uid();
    NEW.attendance_marked := true;
    
    -- Log the deduction
    INSERT INTO leave_accrual_log (user_id, leave_type_id, year, accrual_type, days_credited, days_debited, balance_after, notes)
    VALUES (
      NEW.user_id, 
      NEW.leave_type_id, 
      EXTRACT(YEAR FROM NEW.start_date)::INTEGER, 
      'deduction', 
      0, 
      NEW.days_requested,
      COALESCE((SELECT remaining_balance FROM leave_balance 
                WHERE user_id = NEW.user_id AND leave_type_id = NEW.leave_type_id 
                AND year = EXTRACT(YEAR FROM NEW.start_date)), 0) - NEW.days_requested,
      'Leave approved: ' || NEW.start_date || ' to ' || NEW.end_date
    );
    
    -- Check if LOP applies (balance goes negative)
    IF (SELECT remaining_balance - NEW.days_requested FROM leave_balance 
        WHERE user_id = NEW.user_id AND leave_type_id = NEW.leave_type_id 
        AND year = EXTRACT(YEAR FROM NEW.start_date)) < 0 THEN
      NEW.is_lop := true;
      NEW.lop_days := ABS(
        (SELECT remaining_balance - NEW.days_requested FROM leave_balance 
         WHERE user_id = NEW.user_id AND leave_type_id = NEW.leave_type_id 
         AND year = EXTRACT(YEAR FROM NEW.start_date))
      );
    END IF;
  END IF;
  
  RETURN NEW;
END;
$$;



--
-- Name: merge_retailers(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.merge_retailers(p_source uuid, p_target uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE v_uid uuid := auth.uid(); v_is_admin boolean := false; v_tbl text; v_moved int; v_total int := 0; v_repointed jsonb := '[]'::jsonb; v_dropped jsonb := '[]'::jsonb; v_pending_after numeric; v_src_name text; v_tgt_name text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  SELECT EXISTS(SELECT 1 FROM user_roles WHERE user_id=v_uid AND role='admin') INTO v_is_admin;
  IF NOT v_is_admin THEN SELECT COALESCE(sp.is_system,false) INTO v_is_admin FROM profiles p JOIN security_profiles sp ON sp.id=p.role_id WHERE p.id=v_uid; END IF;
  IF NOT COALESCE(v_is_admin,false) THEN RAISE EXCEPTION 'Permission denied: admin only'; END IF;
  IF p_source IS NULL OR p_target IS NULL OR p_source=p_target THEN RAISE EXCEPTION 'source and target must be provided and different'; END IF;
  SELECT name INTO v_src_name FROM retailers WHERE id=p_source;
  SELECT name INTO v_tgt_name FROM retailers WHERE id=p_target;
  IF v_src_name IS NULL THEN RAISE EXCEPTION 'source retailer not found'; END IF;
  IF v_tgt_name IS NULL THEN RAISE EXCEPTION 'target retailer not found'; END IF;
  FOR v_tbl IN SELECT c.table_name FROM information_schema.columns c JOIN information_schema.tables t ON t.table_schema=c.table_schema AND t.table_name=c.table_name AND t.table_type='BASE TABLE' WHERE c.table_schema='public' AND c.column_name='retailer_id' AND c.table_name NOT LIKE 'qa_%' AND c.table_name <> 'retailers' LOOP
    BEGIN
      EXECUTE format('UPDATE public.%I SET retailer_id=$1 WHERE retailer_id=$2', v_tbl) USING p_target, p_source;
      GET DIAGNOSTICS v_moved = ROW_COUNT; v_total := v_total + v_moved;
      IF v_moved > 0 THEN v_repointed := v_repointed || jsonb_build_object('table',v_tbl,'moved',v_moved); END IF;
    EXCEPTION WHEN unique_violation THEN
      EXECUTE format('DELETE FROM public.%I WHERE retailer_id=$1', v_tbl) USING p_source;
      GET DIAGNOSTICS v_moved = ROW_COUNT; v_dropped := v_dropped || jsonb_build_object('table',v_tbl,'dropped',v_moved);
    END;
  END LOOP;
  BEGIN v_pending_after := public.recompute_retailer_pending(p_target); EXCEPTION WHEN OTHERS THEN v_pending_after := NULL; END;
  UPDATE retailers SET status='inactive', duplicate_of=p_target, updated_at=now() WHERE id=p_source;
  RETURN jsonb_build_object('status','ok','source',p_source,'target',p_target,'reason',p_reason,'total_rows_moved',v_total,'repointed',v_repointed,'dropped_on_collision',v_dropped,'pending_after',v_pending_after);
END; $_$;



--
-- Name: next_free_day(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.next_free_day(p_user uuid, p_from date) RETURNS date
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_start date := greatest(p_from, current_date) + 1; v_end date := (date_trunc('month', v_start) + interval '1 month - 1 day')::date; d date := v_start;
BEGIN
  WHILE d <= v_end LOOP
    IF NOT EXISTS (SELECT 1 FROM leave_applications WHERE user_id = p_user AND status = 'approved' AND d BETWEEN start_date AND end_date) AND NOT EXISTS (SELECT 1 FROM visits WHERE user_id = p_user AND planned_date = d) THEN RETURN d; END IF;
    d := d + 1;
  END LOOP;
  RETURN NULL;
END; $$;



