CREATE FUNCTION public.notif_fill(p_tmpl text, p_actor_name text, p_module text, p_meta jsonb) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(
    COALESCE(p_tmpl,''),
    '{user_name}', COALESCE(p_actor_name,'Unknown')),
    '{module_name}', COALESCE(p_module,'')),
    '{record_name}', COALESCE(p_meta->>'record_name','')),
    '{date}', COALESCE(p_meta->>'date', to_char(now(),'YYYY-MM-DD'))),
    '{time}', COALESCE(p_meta->>'time','')),
    '{points}', COALESCE(p_meta->>'points','0')),
