$$;



--
-- Name: notif_managers_up_chain(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notif_managers_up_chain(p_user_id uuid) RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH RECURSIVE chain AS (
    SELECT e.manager_id AS mgr FROM public.employees e WHERE e.user_id = p_user_id AND e.manager_id IS NOT NULL
    UNION
    SELECT e.manager_id FROM public.employees e JOIN chain c ON e.user_id = c.mgr WHERE e.manager_id IS NOT NULL
  )
  SELECT DISTINCT mgr FROM chain WHERE mgr IS NOT NULL;
$$;



--
-- Name: notif_pick_users(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notif_pick_users() RETURNS TABLE(id uuid, name text, role text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT p.id,
         COALESCE(p.full_name, p.username, 'Unknown') AS name,
         (SELECT sp.name
            FROM public.user_profiles up
            JOIN public.security_profiles sp ON sp.id = up.profile_id
           WHERE up.user_id = p.id
           ORDER BY up.assigned_at DESC NULLS LAST
           LIMIT 1) AS role
  FROM public.profiles p
  WHERE COALESCE(p.is_active, true) = true
  ORDER BY COALESCE(p.full_name, p.username);
$$;



--
-- Name: notif_preview_recipients(text, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notif_preview_recipients(p_receiver_type text, p_receiver_role text DEFAULT NULL::text, p_receiver_user_id uuid DEFAULT NULL::uuid, p_sample_actor uuid DEFAULT NULL::uuid) RETURNS TABLE(id uuid, name text, role text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_actor uuid := COALESCE(p_sample_actor, auth.uid());
BEGIN
  RETURN QUERY
  SELECT pr.id,
         COALESCE(pr.full_name, pr.username, 'Unknown'),
         (SELECT sp.name FROM public.user_profiles up
            JOIN public.security_profiles sp ON sp.id = up.profile_id
           WHERE up.user_id = pr.id
           ORDER BY up.assigned_at DESC NULLS LAST LIMIT 1)
  FROM public.profiles pr
  WHERE COALESCE(pr.is_active, true)
    AND pr.id IN (
      SELECT CASE
        WHEN p_receiver_type='employee'      THEN v_actor
        WHEN p_receiver_type='manager'       THEN (SELECT e.manager_id FROM public.employees e WHERE e.user_id=v_actor)
        WHEN p_receiver_type='specific_user' THEN p_receiver_user_id
      END
      UNION
      SELECT public.notif_managers_up_chain(v_actor) WHERE p_receiver_type='hierarchy'
      UNION
      SELECT up.user_id
        FROM public.user_profiles up
        JOIN public.security_profiles sp ON sp.id = up.profile_id
       WHERE p_receiver_type='role' AND sp.name = p_receiver_role
      UNION
      SELECT up.user_id FROM public.user_profiles up
        JOIN public.security_profiles sp ON sp.id = up.profile_id
       WHERE p_receiver_type='admin' AND sp.name='System Administrator'
    )
  ORDER BY 2;
END $$;



--
-- Name: notify_admins(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_admins(p_type text, p_title text, p_message text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_secret text;
BEGIN
  BEGIN
    SELECT trigger_secret INTO v_secret FROM public.push_config WHERE id = true LIMIT 1;
    IF v_secret IS NOT NULL THEN
      PERFORM net.http_post(
        url := 'https://fuicsoheofipzbmomdtv.supabase.co/functions/v1/send-admin-email-alert',
        headers := jsonb_build_object('Content-Type','application/json','x-alert-secret', v_secret),
        body := jsonb_build_object('type', p_type, 'title', p_title, 'message', p_message)
      );
    END IF;
  EXCEPTION WHEN OTHERS THEN NULL;  -- never block the caller (cron/trigger)
  END;
  RETURN;
END
$$;



--
-- Name: notify_send_test(text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_send_test(p_event_code text, p_source_table text, p_actor uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_batch uuid := gen_random_uuid(); v_actor uuid := COALESCE(p_actor, auth.uid()); v_recips jsonb;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'No actor for test'; END IF;
  PERFORM public.emit_notification_event(
    p_event_code, p_source_table, 'test-'||v_batch::text, v_actor,
    jsonb_build_object('is_test', true, 'test_batch_id', v_batch::text,
      'record_name','Test record', 'date', to_char(now(),'YYYY-MM-DD'), 'time', to_char(now(),'HH12:MI am')));
  SELECT jsonb_agg(x ORDER BY x) INTO v_recips FROM (
    SELECT DISTINCT COALESCE(p.full_name, p.username, n.user_id::text) AS x
    FROM public.notifications n LEFT JOIN public.profiles p ON p.id=n.user_id
    WHERE n.metadata->>'test_batch_id' = v_batch::text) s;
  RETURN jsonb_build_object('success', true,
    'recipient_count', COALESCE(jsonb_array_length(v_recips),0),
    'recipients', COALESCE(v_recips,'[]'::jsonb), 'test_batch_id', v_batch::text);
END $$;



--
-- Name: notify_send_test_push(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_send_test_push(p_user_id uuid, p_title text DEFAULT 'Test push'::text, p_body text DEFAULT 'If you see this, push works'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_url text; v_secret text; v_req bigint; v_tokens int;
BEGIN
  SELECT function_url, trigger_secret INTO v_url, v_secret FROM public.push_config WHERE id = true LIMIT 1;
  IF v_url IS NULL OR v_secret IS NULL THEN RAISE EXCEPTION 'push_config not configured'; END IF;
  SELECT count(*) INTO v_tokens FROM public.push_device_tokens WHERE user_id = p_user_id;
  SELECT net.http_post(url := v_url,
    headers := jsonb_build_object('Content-Type','application/json','x-push-secret', v_secret),
    body := jsonb_build_object('user_id', p_user_id, 'title', p_title, 'body', p_body)) INTO v_req;
  RETURN jsonb_build_object('request_id', v_req, 'tokens_for_user', v_tokens);
END $$;



