--
-- Name: partial_ownership_transfer(uuid, uuid, jsonb, boolean, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.partial_ownership_transfer(p_from uuid, p_to uuid, p_payload jsonb, p_dry_run boolean DEFAULT false, p_caller uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller uuid := COALESCE(p_caller, auth.uid());
  v_counts jsonb := '{}'::jsonb;
  v_warnings jsonb := '[]'::jsonb;
  v_retailer_ids uuid[];
  v_beat_ids text[];
  v_territory_ids uuid[];
  v_distributor_ids uuid[];
  v_van_ids uuid[];
  v_direct_report_ids uuid[];
  v_confirm_dr boolean := COALESCE((p_payload->>'confirmTransferDirectReports')::boolean, false);
  v_include_payments boolean := COALESCE((p_payload->>'include_pending_payments')::boolean, false);
  v_transfer_ownership boolean := COALESCE((p_payload->>'transfer_ownership')::boolean, false);
  v_count int;
  v_total_records int := 0;
  v_max_records int := 500;
  v_reason text := COALESCE(p_payload->>'transfer_reason', '');
  v_affected_retailers uuid[];
  v_outstanding_count int := 0;
  v_outstanding_amount numeric := 0;
  v_cl_count int := 0; v_cl_amt numeric := 0;
  v_dp_count int := 0; v_dp_amt numeric := 0;
  v_ic_count int := 0; v_ic_amt numeric := 0;
  v_to_name text;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'permission denied: caller unknown';
  END IF;
  IF NOT public.is_system_admin(v_caller) THEN
    RAISE EXCEPTION 'permission denied: requires system admin';
  END IF;
  IF p_from = p_to THEN
    RAISE EXCEPTION 'self-transfer not allowed';
  END IF;
  IF p_from IS NULL OR p_to IS NULL THEN
    RAISE EXCEPTION 'p_from and p_to are required';
  END IF;
  IF NOT p_dry_run AND (v_reason IS NULL OR length(trim(v_reason)) < 3) THEN
    RAISE EXCEPTION 'transfer_reason is required (min 3 chars)';
  END IF;

  SELECT COALESCE(NULLIF(trim(full_name), ''), username) INTO v_to_name
    FROM public.profiles WHERE id = p_to;

  IF p_payload ? 'retailers' THEN
    SELECT array_agg((value)::uuid) INTO v_retailer_ids FROM jsonb_array_elements_text(p_payload->'retailers');
  END IF;
  IF p_payload ? 'beats' THEN
    SELECT array_agg(value) INTO v_beat_ids FROM jsonb_array_elements_text(p_payload->'beats');
  END IF;
  IF p_payload ? 'territories' THEN
    SELECT array_agg((value)::uuid) INTO v_territory_ids FROM jsonb_array_elements_text(p_payload->'territories');
  END IF;
  IF p_payload ? 'distributors' THEN
    SELECT array_agg((value)::uuid) INTO v_distributor_ids FROM jsonb_array_elements_text(p_payload->'distributors');
  END IF;
  IF p_payload ? 'vans' THEN
    SELECT array_agg((value)::uuid) INTO v_van_ids FROM jsonb_array_elements_text(p_payload->'vans');
  END IF;
  IF p_payload ? 'direct_reports' THEN
    SELECT array_agg((value)::uuid) INTO v_direct_report_ids FROM jsonb_array_elements_text(p_payload->'direct_reports');
  END IF;

  v_total_records :=
    COALESCE(array_length(v_retailer_ids,1),0) +
    COALESCE(array_length(v_beat_ids,1),0) +
    COALESCE(array_length(v_territory_ids,1),0) +
    COALESCE(array_length(v_distributor_ids,1),0) +
    COALESCE(array_length(v_van_ids,1),0) +
    COALESCE(array_length(v_direct_report_ids,1),0);

  IF v_total_records = 0 THEN
    RAISE EXCEPTION 'no records selected for transfer';
  END IF;
  IF v_total_records > v_max_records THEN
    RAISE EXCEPTION 'transfer exceeds max % records per request (got %)', v_max_records, v_total_records;
  END IF;
  IF v_direct_report_ids IS NOT NULL AND array_length(v_direct_report_ids,1) > 0 AND NOT v_confirm_dr THEN
    RAISE EXCEPTION 'direct_reports transfer requires confirmTransferDirectReports=true';
  END IF;

  IF v_retailer_ids IS NOT NULL THEN
    PERFORM 1 FROM public.retailers WHERE id = ANY(v_retailer_ids) FOR UPDATE;

    IF NOT p_dry_run THEN
      IF v_transfer_ownership THEN
        UPDATE public.retailers
          SET owner_id = p_to, user_id = p_to
          WHERE id = ANY(v_retailer_ids) AND (owner_id = p_from OR user_id = p_from);
      ELSE
        UPDATE public.retailers
          SET user_id = p_to
          WHERE id = ANY(v_retailer_ids) AND (owner_id = p_from OR user_id = p_from);
      END IF;
      GET DIAGNOSTICS v_count = ROW_COUNT;

      WITH affected_beats AS (
        SELECT DISTINCT beat_id
        FROM public.retailers
        WHERE id = ANY(v_retailer_ids)
          AND beat_id IS NOT NULL
          AND beat_id <> ''
          AND beat_id <> 'unassigned'
      ), beat_consensus AS (
        SELECT
          r.beat_id,
          count(DISTINCT r.user_id) FILTER (WHERE r.user_id IS NOT NULL) AS assignee_count,
          max((r.user_id)::text) FILTER (WHERE r.user_id IS NOT NULL)::uuid AS resolved_user_id,
          count(DISTINCT r.owner_id) FILTER (WHERE r.owner_id IS NOT NULL) AS owner_count,
          max((r.owner_id)::text) FILTER (WHERE r.owner_id IS NOT NULL)::uuid AS resolved_owner_id
        FROM public.retailers r
        JOIN affected_beats ab ON ab.beat_id = r.beat_id
        GROUP BY r.beat_id
      )
      UPDATE public.beats b
      SET user_id = bc.resolved_user_id,
          owner_id = CASE
            WHEN v_transfer_ownership AND bc.owner_count = 1 AND bc.resolved_owner_id IS NOT NULL THEN bc.resolved_owner_id
            ELSE b.owner_id
          END,
          owner_name = CASE
            WHEN v_transfer_ownership AND bc.owner_count = 1 AND bc.resolved_owner_id = p_to THEN v_to_name
            ELSE b.owner_name
          END
      FROM beat_consensus bc
      WHERE b.beat_id = bc.beat_id
        AND bc.assignee_count = 1
        AND bc.resolved_user_id IS NOT NULL
        AND (
          b.user_id IS DISTINCT FROM bc.resolved_user_id
          OR (
            v_transfer_ownership
            AND bc.owner_count = 1
            AND bc.resolved_owner_id IS NOT NULL
            AND b.owner_id IS DISTINCT FROM bc.resolved_owner_id
          )
        );
    ELSE
      SELECT count(*) INTO v_count FROM public.retailers
        WHERE id = ANY(v_retailer_ids) AND (owner_id = p_from OR user_id = p_from);
    END IF;
    v_counts := v_counts || jsonb_build_object('retailers', v_count);
  END IF;

  IF v_beat_ids IS NOT NULL THEN
    PERFORM 1 FROM public.beats WHERE beat_id = ANY(v_beat_ids) FOR UPDATE;

    IF NOT p_dry_run THEN
      IF v_transfer_ownership THEN
        UPDATE public.beats
          SET owner_id = p_to, owner_name = v_to_name, user_id = p_to
          WHERE beat_id = ANY(v_beat_ids) AND (owner_id = p_from OR user_id = p_from OR created_by = p_from);
        GET DIAGNOSTICS v_count = ROW_COUNT;
        UPDATE public.retailers
          SET owner_id = p_to, user_id = p_to
          WHERE beat_id = ANY(v_beat_ids) AND (owner_id = p_from OR user_id = p_from);
      ELSE
        UPDATE public.beats
          SET user_id = p_to
          WHERE beat_id = ANY(v_beat_ids) AND (owner_id = p_from OR user_id = p_from OR created_by = p_from);
        GET DIAGNOSTICS v_count = ROW_COUNT;
        UPDATE public.retailers
          SET user_id = p_to
          WHERE beat_id = ANY(v_beat_ids) AND (owner_id = p_from OR user_id = p_from);
      END IF;
    ELSE
      SELECT count(*) INTO v_count FROM public.beats
        WHERE beat_id = ANY(v_beat_ids) AND (owner_id = p_from OR user_id = p_from OR created_by = p_from);
    END IF;
    v_counts := v_counts || jsonb_build_object('beats', v_count);
  END IF;

  IF v_territory_ids IS NOT NULL THEN
    PERFORM 1 FROM public.territories WHERE id = ANY(v_territory_ids) FOR UPDATE;
    IF NOT p_dry_run THEN
      UPDATE public.territories SET assigned_user_id = p_to
        WHERE id = ANY(v_territory_ids) AND assigned_user_id = p_from;
      GET DIAGNOSTICS v_count = ROW_COUNT;
    ELSE
      SELECT count(*) INTO v_count FROM public.territories
        WHERE id = ANY(v_territory_ids) AND assigned_user_id = p_from;
    END IF;
    v_counts := v_counts || jsonb_build_object('territories', v_count);
  END IF;

  IF v_distributor_ids IS NOT NULL THEN
    PERFORM 1 FROM public.distributors WHERE id = ANY(v_distributor_ids) FOR UPDATE;
    IF NOT p_dry_run THEN
      UPDATE public.distributors SET owner_id = p_to
        WHERE id = ANY(v_distributor_ids) AND owner_id = p_from;
      GET DIAGNOSTICS v_count = ROW_COUNT;
    ELSE
      SELECT count(*) INTO v_count FROM public.distributors
        WHERE id = ANY(v_distributor_ids) AND owner_id = p_from;
    END IF;
    v_counts := v_counts || jsonb_build_object('distributors', v_count);
  END IF;

  IF v_van_ids IS NOT NULL THEN
    PERFORM 1 FROM public.vans WHERE id = ANY(v_van_ids) FOR UPDATE;
    IF NOT p_dry_run THEN
      UPDATE public.vans SET assigned_user_id = p_to
        WHERE id = ANY(v_van_ids) AND assigned_user_id = p_from;
      GET DIAGNOSTICS v_count = ROW_COUNT;
    ELSE
      SELECT count(*) INTO v_count FROM public.vans
        WHERE id = ANY(v_van_ids) AND assigned_user_id = p_from;
    END IF;
    v_counts := v_counts || jsonb_build_object('vans', v_count);
  END IF;

  IF v_direct_report_ids IS NOT NULL THEN
    PERFORM 1 FROM public.employees WHERE user_id = ANY(v_direct_report_ids) FOR UPDATE;
    IF NOT p_dry_run THEN
      UPDATE public.employees SET manager_id = p_to
        WHERE user_id = ANY(v_direct_report_ids) AND manager_id = p_from;
      GET DIAGNOSTICS v_count = ROW_COUNT;
    ELSE
      SELECT count(*) INTO v_count FROM public.employees
        WHERE user_id = ANY(v_direct_report_ids) AND manager_id = p_from;
    END IF;
    v_counts := v_counts || jsonb_build_object('direct_reports', v_count);
  END IF;

  SELECT array_agg(DISTINCT rid) INTO v_affected_retailers FROM (
    SELECT unnest(COALESCE(v_retailer_ids, ARRAY[]::uuid[])) AS rid
    UNION
    SELECT id AS rid FROM public.retailers
      WHERE v_beat_ids IS NOT NULL
        AND beat_id = ANY(v_beat_ids)
  ) s WHERE rid IS NOT NULL;

  IF v_affected_retailers IS NOT NULL AND array_length(v_affected_retailers,1) > 0 THEN
    SELECT count(*), COALESCE(sum(amount),0) INTO v_cl_count, v_cl_amt
      FROM public.credit_ledger WHERE retailer_id = ANY(v_affected_retailers);
    SELECT count(*), COALESCE(sum(amount),0) INTO v_dp_count, v_dp_amt
      FROM public.distributor_payments
      WHERE retailer_id = ANY(v_affected_retailers)
        AND COALESCE(status,'') IN ('pending','open','unpaid','partial');
    SELECT count(*), COALESCE(sum(amount),0) INTO v_ic_count, v_ic_amt
      FROM public.inst_collections
      WHERE COALESCE(status,'') IN ('pending','open','unpaid','partial');
    v_outstanding_count := v_cl_count + v_dp_count + v_ic_count;
    v_outstanding_amount := v_cl_amt + v_dp_amt + v_ic_amt;
  END IF;

  IF v_include_payments THEN
    v_warnings := v_warnings || jsonb_build_object(
      'bucket','pending_payments',
      'message','Pending-payment visibility is preview-only. Historical financial rows are not reassigned; visibility follows the transferred retailer assignment.'
    );
  END IF;

  RETURN jsonb_build_object(
    'dry_run', p_dry_run,
    'counts', v_counts,
    'warnings', v_warnings,
    'total_records', v_total_records,
    'include_pending_payments', v_include_payments,
    'transfer_ownership', v_transfer_ownership,
    'outstanding_preview', jsonb_build_object(
      'affected_retailers', COALESCE(array_length(v_affected_retailers,1), 0),
      'open_records', v_outstanding_count,
      'total_amount', v_outstanding_amount,
      'breakdown', jsonb_build_object(
        'credit_ledger', jsonb_build_object('count', v_cl_count, 'amount', v_cl_amt),
        'distributor_payments', jsonb_build_object('count', v_dp_count, 'amount', v_dp_amt),
        'inst_collections', jsonb_build_object('count', v_ic_count, 'amount', v_ic_amt)
      )
    )
  );
END;
$$;



--
-- Name: pm_is_project_member(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pm_is_project_member(project_uuid uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM pm_project_members WHERE project_id = project_uuid AND user_id = auth.uid()
  ) OR EXISTS (
    SELECT 1 FROM pm_projects WHERE id = project_uuid AND created_by = auth.uid()
  ) OR public.is_system_admin(auth.uid());
$$;



--
-- Name: prevent_admin_sensitive_access(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_admin_sensitive_access() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- If user is admin and trying to access someone else's profile
  IF public.has_role(auth.uid(), 'admin'::public.app_role) AND auth.uid() != NEW.id THEN
    -- Prevent updates to sensitive fields
    IF OLD.hint_question IS DISTINCT FROM NEW.hint_question 
       OR OLD.hint_answer IS DISTINCT FROM NEW.hint_answer 
       OR OLD.recovery_email IS DISTINCT FROM NEW.recovery_email 
       OR OLD.phone_number IS DISTINCT FROM NEW.phone_number THEN
      RAISE EXCEPTION 'Admins cannot access or modify sensitive profile data';
    END IF;
  END IF;
  
  RETURN NEW;
END;
$$;



--
-- Name: prevent_negative_batch_stock(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_negative_batch_stock() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.available_qty < 0 THEN RAISE EXCEPTION 'available_qty cannot be negative for batch %', NEW.batch_no; END IF;
  IF NEW.reserved_qty < 0 THEN RAISE EXCEPTION 'reserved_qty cannot be negative for batch %', NEW.batch_no; END IF;
  RETURN NEW;
END; $$;



--
-- Name: prevent_system_profile_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_system_profile_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.is_system = true THEN
    RAISE EXCEPTION 'Cannot delete system security profile "%" (id=%). System profiles are protected.', OLD.name, OLD.id;
  END IF;
  RETURN OLD;
END;
$$;



--
-- Name: process_approval_step(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_approval_step(p_approval_request_id uuid, p_approver_id uuid, p_action text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_request RECORD;
  v_step RECORD;
BEGIN
  SELECT * INTO v_request FROM approval_requests WHERE id = p_approval_request_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'message', 'Request not found');
  END IF;

  IF v_request.status != 'pending' THEN
    RETURN jsonb_build_object('success', false, 'message', 'Request already processed');
  END IF;

  -- Find ANY pending step for this approver (parallel: no level check)
  SELECT * INTO v_step FROM approval_steps 
  WHERE approval_request_id = p_approval_request_id
    AND approver_id = p_approver_id
    AND status = 'pending'
  ORDER BY level ASC
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'message', 'No pending step found for this approver');
  END IF;

  -- Update the acting step
  UPDATE approval_steps SET
    status = p_action,
    action_taken_at = now(),
    rejection_reason = p_reason
  WHERE id = v_step.id;

  -- Skip all other pending steps
  UPDATE approval_steps SET
    status = 'skipped',
    action_taken_at = now()
  WHERE approval_request_id = p_approval_request_id
    AND id != v_step.id
    AND status = 'pending';

  -- Log action
  INSERT INTO approval_audit_log (approval_request_id, entity_type, entity_id, action, performed_by, level, metadata)
  VALUES (p_approval_request_id, v_request.entity_type, v_request.entity_id, p_action, p_approver_id, 
          v_step.level, jsonb_build_object('reason', p_reason));

  IF p_action = 'rejected' THEN
    UPDATE approval_requests SET status = 'rejected', updated_at = now() WHERE id = p_approval_request_id;
    RETURN jsonb_build_object('success', true, 'message', 'Request rejected', 'is_final', true, 'action', 'rejected');
  END IF;

  -- Approved: always final in parallel mode
  UPDATE approval_requests SET
    status = 'approved',
    final_approved_by = p_approver_id,
    updated_at = now()
  WHERE id = p_approval_request_id;

  RETURN jsonb_build_object('success', true, 'message', 'Request approved', 'is_final', true, 'action', 'approved');
END;
$$;



--
-- Name: process_monthly_leave_accrual(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_monthly_leave_accrual() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_policy RECORD;
  v_user RECORD;
  v_credit NUMERIC;
  v_current_year INTEGER;
  v_current_month INTEGER;
  v_already_done BOOLEAN;
BEGIN
  v_current_year := EXTRACT(YEAR FROM CURRENT_DATE)::INTEGER;
  v_current_month := EXTRACT(MONTH FROM CURRENT_DATE)::INTEGER;
  
  FOR v_policy IN 
    SELECT lp.*, lt.name as leave_name FROM leave_policy lp
    JOIN leave_types lt ON lt.id = lp.leave_type_id
    WHERE lp.is_active = true AND lp.accrual_type = 'monthly'
  LOOP
    v_credit := ROUND(v_policy.yearly_entitlement / 12.0, 2);
    
    FOR v_user IN 
      SELECT id FROM profiles WHERE user_status = 'active'
    LOOP
      -- Check if already accrued this month
      SELECT EXISTS(
        SELECT 1 FROM leave_accrual_log
        WHERE user_id = v_user.id
          AND leave_type_id = v_policy.leave_type_id
          AND year = v_current_year
          AND month = v_current_month
      ) INTO v_already_done;
      
      IF v_already_done THEN
        CONTINUE;
      END IF;

      -- Ensure balance record exists
      INSERT INTO leave_balance (user_id, leave_type_id, year, opening_balance, used_balance)
      VALUES (v_user.id, v_policy.leave_type_id, v_current_year, 0, 0)
      ON CONFLICT (user_id, leave_type_id, year) DO NOTHING;
      
      -- Credit opening_balance (remaining_balance is auto-computed as opening_balance - used_balance)
      UPDATE leave_balance
      SET opening_balance = opening_balance + v_credit,
          updated_at = now()
      WHERE user_id = v_user.id 
        AND leave_type_id = v_policy.leave_type_id
        AND year = v_current_year;
      
      -- Log the accrual
      INSERT INTO leave_accrual_log (user_id, leave_type_id, year, month, accrual_type, days_credited, balance_after, notes)
      VALUES (
        v_user.id, 
        v_policy.leave_type_id, 
        v_current_year, 
        v_current_month, 
        'monthly', 
        v_credit,
        (SELECT opening_balance - used_balance FROM leave_balance 
         WHERE user_id = v_user.id AND leave_type_id = v_policy.leave_type_id AND year = v_current_year),
        'Monthly accrual for ' || v_policy.leave_name
      );
    END LOOP;
  END LOOP;
END;
$$;



--
-- Name: process_notification_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_notification_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_rule RECORD;
  v_title TEXT;
  v_message TEXT;
  v_receiver_ids UUID[];
  v_receiver_id UUID;
  v_metadata JSONB;
  v_related_id UUID;
BEGIN
  v_metadata := COALESCE(NEW.metadata, '{}'::jsonb);

  FOR v_rule IN
    SELECT * FROM notification_rules
    WHERE is_active = true
      AND event_code = NEW.event_code
      AND source_table = NEW.source_table
  LOOP
    v_title := v_rule.title_template;
    v_message := v_rule.message_template;

    v_title := replace(v_title, '{user_name}', COALESCE(v_metadata->>'user_name', 'Someone'));
    v_title := replace(v_title, '{record_name}', COALESCE(v_metadata->>'record_name', ''));
    v_title := replace(v_title, '{date}', COALESCE(v_metadata->>'date', ''));
    v_title := replace(v_title, '{auto_close_time}', COALESCE(v_metadata->>'auto_close_time', ''));
    v_title := replace(v_title, '{last_activity}', COALESCE(v_metadata->>'last_activity', ''));

    v_message := replace(v_message, '{user_name}', COALESCE(v_metadata->>'user_name', 'Someone'));
    v_message := replace(v_message, '{record_name}', COALESCE(v_metadata->>'record_name', ''));
    v_message := replace(v_message, '{leave_type}', COALESCE(v_metadata->>'leave_type', 'Leave'));
    v_message := replace(v_message, '{from_date}', COALESCE(v_metadata->>'from_date', ''));
    v_message := replace(v_message, '{to_date}', COALESCE(v_metadata->>'to_date', ''));
    v_message := replace(v_message, '{total_days}', COALESCE(v_metadata->>'total_days', ''));
    v_message := replace(v_message, '{date}', COALESCE(v_metadata->>'date', ''));
    v_message := replace(v_message, '{auto_close_time}', COALESCE(v_metadata->>'auto_close_time', ''));
    v_message := replace(v_message, '{minutes_remaining}', COALESCE(v_metadata->>'minutes_remaining', ''));
    v_message := replace(v_message, '{last_activity}', COALESCE(v_metadata->>'last_activity', ''));

    v_receiver_ids := ARRAY[]::UUID[];

    -- FIXED: 'employee' now correctly sends to the actor, not the manager
    IF v_rule.receiver_type = 'self' OR v_rule.receiver_type = 'employee' THEN
      v_receiver_ids := ARRAY[NEW.actor_user_id];

    ELSIF v_rule.receiver_type = 'manager' THEN
      SELECT ARRAY(
        SELECT manager_id FROM get_reporting_chain(NEW.actor_user_id) WHERE level = 1
      ) INTO v_receiver_ids;

    ELSIF v_rule.receiver_type = 'reporting_chain' THEN
      SELECT ARRAY(
        SELECT manager_id FROM get_reporting_chain(NEW.actor_user_id)
      ) INTO v_receiver_ids;

    ELSIF v_rule.receiver_type = 'specific_user' AND v_rule.receiver_user_id IS NOT NULL THEN
      v_receiver_ids := ARRAY[v_rule.receiver_user_id];

    ELSIF v_rule.receiver_type = 'admin' THEN
      SELECT ARRAY(
        SELECT up.user_id FROM user_profiles up
        JOIN security_profiles sp ON sp.id = up.profile_id
        WHERE sp.name = 'System Administrator'
      ) INTO v_receiver_ids;
    END IF;

    v_related_id := NULL;
    IF NEW.record_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' THEN
      v_related_id := NEW.record_id::UUID;
    END IF;

    -- FIXED: allow self-notifications for 'self' and 'employee' receiver types
    FOREACH v_receiver_id IN ARRAY v_receiver_ids
    LOOP
      IF v_receiver_id IS NOT NULL AND (
        v_rule.receiver_type IN ('self', 'employee') OR v_receiver_id != NEW.actor_user_id
      ) THEN
        INSERT INTO notifications (user_id, title, message, type, related_table, related_id)
        VALUES (v_receiver_id, v_title, v_message, 'info', NEW.source_table, v_related_id);
      END IF;
    END LOOP;
  END LOOP;

  UPDATE notification_event_log SET processed = true WHERE id = NEW.id;

  RETURN NEW;
END;
$_$;



--
-- Name: process_year_end_carry_forward(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_year_end_carry_forward() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_policy RECORD;
  v_balance RECORD;
  v_carry NUMERIC;
  v_new_year INTEGER;
BEGIN
  v_new_year := EXTRACT(YEAR FROM CURRENT_DATE)::INTEGER;
  
  FOR v_policy IN 
    SELECT lp.*, lt.name as leave_name FROM leave_policy lp
    JOIN leave_types lt ON lt.id = lp.leave_type_id
    WHERE lp.is_active = true
  LOOP
    FOR v_balance IN 
      SELECT * FROM leave_balance 
      WHERE leave_type_id = v_policy.leave_type_id 
        AND year = v_new_year - 1
        AND remaining_balance > 0
    LOOP
      IF v_policy.carry_forward_allowed THEN
        v_carry := LEAST(v_balance.remaining_balance, COALESCE(v_policy.max_carry_forward, v_balance.remaining_balance));
      ELSE
        v_carry := 0;
      END IF;
      
      -- Create or update new year balance with carry forward
      INSERT INTO leave_balance (user_id, leave_type_id, year, opening_balance, used_balance, remaining_balance)
      VALUES (v_balance.user_id, v_policy.leave_type_id, v_new_year, 
              v_policy.yearly_entitlement + v_carry, 0, v_policy.yearly_entitlement + v_carry)
      ON CONFLICT (user_id, leave_type_id, year) 
      DO UPDATE SET 
        opening_balance = leave_balance.opening_balance + v_carry,
        remaining_balance = leave_balance.remaining_balance + v_carry,
        updated_at = now();
      
      -- Log carry forward
      IF v_carry > 0 THEN
        INSERT INTO leave_accrual_log (user_id, leave_type_id, year, accrual_type, days_credited, balance_after, notes)
        VALUES (
          v_balance.user_id, 
          v_policy.leave_type_id, 
          v_new_year, 
          'carry_forward', 
          v_carry,
          (SELECT remaining_balance FROM leave_balance 
           WHERE user_id = v_balance.user_id AND leave_type_id = v_policy.leave_type_id AND year = v_new_year),
          'Carried forward from ' || (v_new_year - 1) || ': ' || v_policy.leave_name
        );
      END IF;
    END LOOP;
  END LOOP;
END;
$$;



--
-- Name: prune_db_health_snapshots(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prune_db_health_snapshots(p_keep_days integer DEFAULT 120) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_deleted integer;
BEGIN
  WITH gone AS (
    DELETE FROM db_health_snapshots
    WHERE captured_at < now() - make_interval(days => GREATEST(p_keep_days,7))
    RETURNING 1)
  SELECT count(*) INTO v_deleted FROM gone;
  RETURN v_deleted;
END $$;



--
-- Name: prune_report_delivery_claims(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prune_report_delivery_claims(p_keep_days integer DEFAULT 90) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_n integer;
BEGIN
  DELETE FROM public.report_delivery_claims
  WHERE claimed_at < now() - make_interval(days => GREATEST(p_keep_days, 1));
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END;
$$;



--
-- Name: quarantine_orphan_orders(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.quarantine_orphan_orders(p_grace_minutes integer DEFAULT 10) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_ids uuid[]; r record;
BEGIN
  SELECT array_agg(o.id) INTO v_ids FROM public.orders o WHERE o.status <> 'cancelled' AND o.created_at < now() - make_interval(mins => p_grace_minutes) AND NOT EXISTS (SELECT 1 FROM public.order_items oi WHERE oi.order_id = o.id);
  IF v_ids IS NULL THEN RETURN 0; END IF;
  UPDATE public.orders SET status='cancelled', cancellation_reason = COALESCE(cancellation_reason,'auto-quarantine: order has no line items'), cancelled_at = COALESCE(cancelled_at, now()) WHERE id = ANY(v_ids);
  INSERT INTO public.sync_audit_log(order_id, idempotency_key, user_id, device_id, payload, status, error) SELECT o.id, o.idempotency_key, o.user_id, NULL, jsonb_build_object('auto_quarantine',true), 'validation_error', 'auto-quarantine: 0 line items' FROM public.orders o WHERE o.id = ANY(v_ids);
  FOR r IN SELECT DISTINCT retailer_id FROM public.orders WHERE id = ANY(v_ids) AND retailer_id IS NOT NULL LOOP PERFORM public.recompute_retailer_pending(r.retailer_id); END LOOP;
  RETURN array_length(v_ids,1);
END $$;



--
-- Name: reactivate_beat(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reactivate_beat(p_beat_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_user uuid := auth.uid();
BEGIN
  UPDATE public.beats SET is_active = true, reactivated_at = now(), reactivated_by = v_user, deactivated_at = NULL, deactivated_by = NULL, updated_at = now(), updated_by = v_user WHERE beat_id = p_beat_id;
  INSERT INTO public.beat_audit_log(beat_id, action, metadata, performed_by) VALUES (p_beat_id, 'BEAT_REACTIVATED', '{}'::jsonb, v_user);
  RETURN jsonb_build_object('status','ok');
END $$;



--
-- Name: reactivate_user(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reactivate_user(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_caller uuid := auth.uid(); v_name text;
BEGIN
  IF v_caller IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.user_has_permission(v_caller, 'admin_user_activate_deactivate', 'can_edit') THEN
    RAISE EXCEPTION 'Your profile does not have permission to reactivate users';
  END IF;
  SELECT full_name INTO v_name FROM public.profiles WHERE id = p_user_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'User not found'; END IF;
  UPDATE public.profiles
     SET is_active=true, user_status='active', reactivated_at=now(), deactivation_reason=NULL
   WHERE id=p_user_id;
  UPDATE auth.users SET banned_until=NULL WHERE id=p_user_id;
  INSERT INTO public.user_status_log(user_id, action, performed_by, reason)
  VALUES (p_user_id, 'reactivate', v_caller, NULL);
  RETURN jsonb_build_object('success', true, 'action','reactivate','user_id', p_user_id, 'user_name', v_name);
END $$;



--
-- Name: recompute_invoice_and_payment_totals(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recompute_invoice_and_payment_totals() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_invoice_id uuid; v_payment_id uuid; v_inv_total numeric(14,2); v_inv_paid numeric(14,2); v_pay_total numeric(14,2); v_pay_alloc numeric(14,2);
BEGIN
  v_invoice_id := COALESCE(NEW.invoice_id, OLD.invoice_id); v_payment_id := COALESCE(NEW.payment_id, OLD.payment_id);
  SELECT total_amount INTO v_inv_total FROM public.distributor_secondary_invoices WHERE id = v_invoice_id;
  SELECT COALESCE(SUM(allocated_amount),0) INTO v_inv_paid FROM public.payment_allocations WHERE invoice_id = v_invoice_id;
  UPDATE public.distributor_secondary_invoices SET amount_paid = v_inv_paid, balance_due = GREATEST(COALESCE(v_inv_total,0) - v_inv_paid, 0),
    payment_status = CASE WHEN v_inv_paid <= 0 THEN 'unpaid' WHEN v_inv_paid >= COALESCE(v_inv_total,0) THEN 'paid' ELSE 'partial' END, updated_at = now() WHERE id = v_invoice_id;
  SELECT amount INTO v_pay_total FROM public.distributor_payments WHERE id = v_payment_id;
  SELECT COALESCE(SUM(allocated_amount),0) INTO v_pay_alloc FROM public.payment_allocations WHERE payment_id = v_payment_id;
  UPDATE public.distributor_payments SET unallocated_amount = GREATEST(COALESCE(v_pay_total,0) - v_pay_alloc, 0), updated_at = now() WHERE id = v_payment_id;
  RETURN NULL;
END $$;



--
-- Name: recompute_retailer_pending(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recompute_retailer_pending(p_retailer_id uuid) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_new_pending numeric := 0;
BEGIN
  IF p_retailer_id IS NULL THEN RETURN 0; END IF;
  SELECT COALESCE(SUM(GREATEST(COALESCE(credit_pending_amount, 0), 0)), 0) INTO v_new_pending FROM public.orders WHERE retailer_id = p_retailer_id AND COALESCE(status, '') <> 'cancelled' AND is_credit_order = true;
  UPDATE public.retailers SET pending_amount = v_new_pending, updated_at = now() WHERE id = p_retailer_id;
  RETURN v_new_pending;
END; $$;



--
-- Name: reflow_allocation_fifo(uuid, uuid, numeric, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reflow_allocation_fifo(p_retailer_id uuid, p_collection_id uuid, p_amount numeric, p_exclude_order_id uuid) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_remaining numeric := COALESCE(p_amount, 0); v_apply numeric; v_order RECORD;
BEGIN
  IF v_remaining <= 0 THEN RETURN 0; END IF;
  FOR v_order IN SELECT id, COALESCE(credit_pending_amount, 0) AS pending FROM public.orders WHERE retailer_id = p_retailer_id AND is_credit_order = true AND COALESCE(status, '') <> 'cancelled' AND COALESCE(credit_pending_amount, 0) > 0 AND id <> p_exclude_order_id ORDER BY order_date ASC NULLS LAST, created_at ASC FOR UPDATE SKIP LOCKED LOOP
    EXIT WHEN v_remaining <= 0;
    v_apply := LEAST(v_remaining, v_order.pending);
    UPDATE public.orders SET credit_paid_amount = COALESCE(credit_paid_amount, 0) + v_apply, credit_pending_amount = COALESCE(credit_pending_amount, 0) - v_apply, payment_status = CASE WHEN COALESCE(credit_pending_amount, 0) - v_apply <= 0 THEN 'paid' ELSE 'partial' END WHERE id = v_order.id;
    INSERT INTO public.retailer_payment_allocations (collection_id, order_id, retailer_id, amount_applied) VALUES (p_collection_id, v_order.id, p_retailer_id, v_apply);
    v_remaining := v_remaining - v_apply;
  END LOOP;
  RETURN v_remaining;
END; $$;



--
-- Name: report_all_managers(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_all_managers() RETURNS TABLE(user_id uuid, full_name text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT DISTINCT e.manager_id AS user_id,
         COALESCE(p.full_name, p.username, '')::text AS full_name
  FROM public.employees e
  JOIN public.employees me ON me.user_id = e.manager_id
  JOIN public.profiles p ON p.id = e.manager_id
  WHERE e.manager_id IS NOT NULL
    AND p.is_active = true
    AND (e.date_of_exit IS NULL OR e.date_of_exit > now())
    AND (me.date_of_exit IS NULL OR me.date_of_exit > now());
$$;



--
-- Name: report_apply_audience(uuid[], jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_apply_audience(p_scoped_user_ids uuid[], p_filters jsonb) RETURNS uuid[]
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_audience   uuid[];
  v_result     uuid[] := p_scoped_user_ids;
  v_restricted boolean := p_scoped_user_ids IS NOT NULL;
  v_exclude    boolean := COALESCE((p_filters->>'exclude_inactive')::boolean, false);
BEGIN
  BEGIN
    IF jsonb_typeof(p_filters->'audience_user_ids') = 'array'
       AND jsonb_array_length(p_filters->'audience_user_ids') > 0 THEN
      SELECT array_agg(x::uuid) INTO v_audience
      FROM jsonb_array_elements_text(p_filters->'audience_user_ids') x
      WHERE x <> '';
    END IF;
  EXCEPTION WHEN OTHERS THEN
    -- A malformed list must not silently widen the report.
    RAISE WARNING 'report_apply_audience: bad audience_user_ids (%), ignoring', SQLERRM;
    v_audience := NULL;
  END;

  IF v_audience IS NOT NULL AND array_length(v_audience, 1) > 0 THEN
    IF v_result IS NULL THEN
      v_result := v_audience;                        -- org-wide: selection defines it
    ELSE
      SELECT COALESCE(array_agg(u), ARRAY[]::uuid[]) -- never NULL once restricted
      INTO v_result
      FROM unnest(v_result) u
      WHERE u = ANY(v_audience);
    END IF;
    v_restricted := true;
  END IF;

  -- Evaluated here, at generation time, against CURRENT profile status: someone
  -- selected months ago and since deactivated drops out on the next run without
  -- anyone editing the subscription.
  IF v_exclude THEN
    IF NOT v_restricted THEN
      SELECT COALESCE(array_agg(p.id), ARRAY[]::uuid[]) INTO v_result
      FROM public.profiles p
      WHERE COALESCE(p.is_active, true) = true;
    ELSE
      SELECT COALESCE(array_agg(u), ARRAY[]::uuid[]) INTO v_result
      FROM unnest(COALESCE(v_result, ARRAY[]::uuid[])) u
      WHERE EXISTS (SELECT 1 FROM public.profiles p
                    WHERE p.id = u AND COALESCE(p.is_active, true) = true);
    END IF;
    v_restricted := true;
  END IF;

  IF v_restricted AND v_result IS NULL THEN
    v_result := ARRAY[]::uuid[];
  END IF;

  RETURN v_result;
END;
$$;



--
-- Name: FUNCTION report_apply_audience(p_scoped_user_ids uuid[], p_filters jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.report_apply_audience(p_scoped_user_ids uuid[], p_filters jsonb) IS 'Narrows a report''s user scope by config.filters.audience_user_ids and exclude_inactive. Only ever narrows: the hierarchy scope passed in is a hard ceiling, so a report author cannot widen a recipient''s view.';



--
-- Name: report_can_view_user(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_can_view_user(_viewer uuid, _target uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT _viewer = _target OR public.is_subordinate_of(_viewer, _target);
$$;



--
-- Name: report_claim_delivery(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_claim_delivery(p_subscription_id uuid, p_recipient_user_id uuid, p_period text, p_trigger_type text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_claimed boolean;
BEGIN
  IF p_trigger_type IS DISTINCT FROM 'scheduled' THEN
    RETURN true;
  END IF;

  INSERT INTO public.report_delivery_claims
    (subscription_id, recipient_user_id, period, trigger_type)
  VALUES
    (p_subscription_id, p_recipient_user_id, p_period, 'scheduled')
  ON CONFLICT DO NOTHING;

  GET DIAGNOSTICS v_claimed = ROW_COUNT;
  RETURN v_claimed;
END;
$$;



--
-- Name: FUNCTION report_claim_delivery(p_subscription_id uuid, p_recipient_user_id uuid, p_period text, p_trigger_type text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.report_claim_delivery(p_subscription_id uuid, p_recipient_user_id uuid, p_period text, p_trigger_type text) IS 'Atomically claims one scheduled delivery for a subscription/recipient/period. Returns true to exactly one caller; concurrent duplicates get false and must not deliver. Manual runs always return true.';



--
-- Name: report_system_admins(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_system_admins(p_user_ids uuid[]) RETURNS TABLE(user_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT u
  FROM unnest(COALESCE(p_user_ids, ARRAY[]::uuid[])) AS u
  WHERE public.is_system_admin(u);
$$;



--
-- Name: request_backdate(date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_backdate(p_date date, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid uuid := auth.uid(); v_enabled boolean; v_req_id uuid; v_approval_id uuid;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  SELECT backdate_enabled INTO v_enabled FROM public.operations_config WHERE id = 1;
  IF NOT COALESCE(v_enabled, false) THEN RAISE EXCEPTION 'Backdated orders are disabled'; END IF;
  IF NOT public.user_has_permission(v_uid,'order_backdate','can_create') THEN RAISE EXCEPTION 'You do not have permission to request a backdated order'; END IF;
  INSERT INTO public.order_backdate_requests (user_id, order_date, reason) VALUES (v_uid, p_date, p_reason) RETURNING id INTO v_req_id;
  v_approval_id := public.create_approval_request('order_backdate', v_req_id, v_uid);
  IF v_approval_id IS NULL THEN RAISE EXCEPTION 'No approver could be resolved for this backdate request'; END IF;
  UPDATE public.order_backdate_requests SET approval_request_id = v_approval_id WHERE id = v_req_id;
  RETURN v_req_id;
END; $$;



--
-- Name: request_order_edit(uuid, uuid, uuid, text, numeric, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_order_edit(p_original_order_id uuid, p_replacement_order_id uuid, p_edited_by uuid, p_reason text, p_target_paid numeric DEFAULT NULL::numeric, p_new_collection_id uuid DEFAULT NULL::uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_cfg operations_config%ROWTYPE; v_old_total numeric; v_new_total numeric; v_req_id uuid; v_approval_id uuid;
BEGIN
  IF NOT public.can_edit_order(p_original_order_id, p_edited_by) THEN RAISE EXCEPTION 'Editing not allowed for this order (locked, no permission, or edit limit reached)'; END IF;
  SELECT * INTO v_cfg FROM operations_config WHERE id = 1;
  IF COALESCE(v_cfg.edit_require_reason, false) AND COALESCE(p_reason, '') = '' THEN RAISE EXCEPTION 'A reason is required to edit this order'; END IF;
  SELECT total_amount INTO v_old_total FROM orders WHERE id = p_original_order_id;
  SELECT total_amount INTO v_new_total FROM orders WHERE id = p_replacement_order_id;
  IF COALESCE(v_cfg.edit_require_approval, false) AND abs(COALESCE(v_new_total, 0) - COALESCE(v_old_total, 0)) > COALESCE(v_cfg.edit_approval_threshold, 0) THEN
    INSERT INTO public.order_edit_requests (original_order_id, replacement_order_id, edited_by, reason, target_paid, new_collection_id, old_total, new_total, status) VALUES (p_original_order_id, p_replacement_order_id, p_edited_by, p_reason, p_target_paid, p_new_collection_id, v_old_total, v_new_total, 'pending') RETURNING id INTO v_req_id;
    v_approval_id := public.create_approval_request('order_edit', v_req_id, p_edited_by);
    IF v_approval_id IS NULL THEN RAISE EXCEPTION 'No approver could be resolved for this order edit request'; END IF;
    UPDATE public.order_edit_requests SET approval_request_id = v_approval_id WHERE id = v_req_id;
    RETURN 'pending';
  ELSE
    PERFORM public.finalize_order_edit(p_original_order_id, p_replacement_order_id, p_edited_by, p_reason, p_target_paid, p_new_collection_id);
    RETURN 'applied';
  END IF;
END; $$;



--
-- Name: reschedule_missed_day(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reschedule_missed_day(p_user uuid, p_from_date date, p_to_date date DEFAULT NULL::date) RETURNS TABLE(moved integer, to_date date)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_to date; v_count integer;
BEGIN
  IF NOT (p_user = auth.uid() OR public.is_subordinate_of(auth.uid(), p_user)) THEN RETURN; END IF;
  v_to := COALESCE(p_to_date, public.next_free_day(p_user, p_from_date));
  IF v_to IS NULL THEN RAISE EXCEPTION 'No free day available this month'; END IF;
  WITH updated AS (UPDATE visits v SET planned_date = v_to, status = 'planned', cancel_source = NULL, is_rescheduled = true, rescheduled_from_date = p_from_date, updated_at = now() WHERE v.user_id = p_user AND v.planned_date = p_from_date AND v.status IN ('planned','cancelled') AND NOT EXISTS (SELECT 1 FROM visits v2 WHERE v2.user_id = p_user AND v2.retailer_id = v.retailer_id AND v2.planned_date = v_to AND v2.status = 'planned') RETURNING 1)
  SELECT COUNT(*)::integer INTO v_count FROM updated;
  moved := v_count; to_date := v_to; RETURN NEXT;
END; $$;



--
-- Name: resolve_effective_leave_policy(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_effective_leave_policy(p_leave_type_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_global RECORD;
  v_override RECORD;
  v_result jsonb;
BEGIN
  SELECT * INTO v_global FROM global_leave_policy LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'No global leave policy configured');
  END IF;

  SELECT * INTO v_override FROM leave_type_policy_override
  WHERE leave_type_id = p_leave_type_id AND override_enabled = true;

  v_result := jsonb_build_object(
    'is_enabled', v_global.is_enabled,
    'allow_half_day', v_global.enable_half_day,
    'enable_sandwich_rule', v_global.enable_sandwich_rule,
    'allow_backdated_leave', v_global.allow_backdated_leave,
    'max_backdate_days', v_global.max_backdate_days,
    'min_notice_period_days', v_global.min_notice_period_days,
    'max_continuous_leave_days', v_global.max_continuous_leave_days,
    'allow_negative_balance', COALESCE(v_override.allow_negative_balance, v_global.allow_negative_balance),
    'max_negative_limit', COALESCE(v_override.max_negative_limit, v_global.max_negative_limit),
    'enable_carry_forward', COALESCE(v_override.enable_carry_forward, v_global.enable_carry_forward),
    'max_carry_forward_limit', COALESCE(v_override.max_carry_forward_limit, v_global.max_carry_forward_limit)
  );

  RETURN v_result;
END;
$$;



--
-- Name: resolve_quantity_to_base(numeric, text, uuid, numeric, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_quantity_to_base(p_quantity numeric, p_unit_text text, p_uom_id uuid DEFAULT NULL::uuid, p_conversion_snap numeric DEFAULT NULL::numeric, p_product_id uuid DEFAULT NULL::uuid) RETURNS numeric
    LANGUAGE sql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT p_quantity * COALESCE(p_conversion_snap, (SELECT pum.conversion_to_base FROM product_uom_mapping pum WHERE pum.product_id = p_product_id AND pum.uom_id = p_uom_id AND COALESCE(pum.is_active, true) LIMIT 1),
    CASE LOWER(TRIM(COALESCE(p_unit_text, ''))) WHEN 'gram' THEN 1 WHEN 'grams' THEN 1 WHEN 'g' THEN 1 WHEN 'kg' THEN 1000 WHEN 'kilogram' THEN 1000 WHEN 'kilograms' THEN 1000 WHEN 'ml' THEN 1 WHEN 'millilitre' THEN 1 WHEN 'millilitres' THEN 1 WHEN 'milliliter' THEN 1 WHEN 'milliliters' THEN 1 WHEN 'litre' THEN 1000 WHEN 'litres' THEN 1000 WHEN 'liter' THEN 1000 WHEN 'liters' THEN 1000 WHEN 'l' THEN 1000 ELSE 1 END); $$;



--
-- Name: retailer_has_history(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.retailer_has_history(p_retailer_id uuid) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (SELECT 1 FROM orders WHERE retailer_id = p_retailer_id) OR EXISTS (SELECT 1 FROM visits WHERE retailer_id = p_retailer_id) OR EXISTS (SELECT 1 FROM credit_ledger WHERE retailer_id = p_retailer_id) OR EXISTS (SELECT 1 FROM credit_notes WHERE retailer_id = p_retailer_id) OR EXISTS (SELECT 1 FROM retailer_payment_collections WHERE retailer_id = p_retailer_id);
$$;



--
-- Name: retailer_in_user_oob_scope(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.retailer_in_user_oob_scope(p_retailer_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_cfg RECORD; v_r RECORD; v_uid uuid := auth.uid(); v_assigned boolean := false; v_terr_ok boolean := false;
BEGIN
  IF v_uid IS NULL OR p_retailer_id IS NULL THEN RETURN false; END IF;
  SELECT oob_enabled, oob_visibility INTO v_cfg FROM public.operations_config WHERE id = 1;
  IF NOT FOUND OR NOT COALESCE(v_cfg.oob_enabled, false) THEN RETURN false; END IF;
  IF NOT public.user_has_permission(v_uid, 'order_out_of_beat', 'can_create') THEN RETURN false; END IF;
  SELECT id, user_id, beat_id, territory_id INTO v_r FROM public.retailers WHERE id = p_retailer_id;
  IF NOT FOUND THEN RETURN false; END IF;
  IF v_cfg.oob_visibility = 'beat' THEN RETURN false; END IF;
  IF v_cfg.oob_visibility IN ('assigned','territory','all') THEN
    v_assigned := (v_r.user_id = v_uid) OR public.user_has_beat_access(v_uid, v_r.beat_id) OR EXISTS (SELECT 1 FROM public.retailer_shared_access rsa WHERE rsa.retailer_id = p_retailer_id AND rsa.shared_to_user_id = v_uid AND rsa.is_active = true AND COALESCE(rsa.can_take_orders, false) = true);
    IF v_assigned THEN RETURN true; END IF;
  END IF;
  IF v_cfg.oob_visibility IN ('territory','all') AND v_r.territory_id IS NOT NULL THEN
    v_terr_ok := EXISTS (SELECT 1 FROM public.beats b WHERE b.territory_id = v_r.territory_id AND (b.user_id = v_uid OR public.user_has_beat_access(v_uid, b.beat_id)));
    IF v_terr_ok THEN RETURN true; END IF;
  END IF;
  IF v_cfg.oob_visibility = 'all' THEN IF public.user_has_permission(v_uid, 'order_out_of_beat', 'can_view_all') THEN RETURN true; END IF; END IF;
  RETURN false;
END; $$;



--
-- Name: retailers_autofill_owner(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.retailers_autofill_owner() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_name text;
BEGIN
  IF NEW.owner_id IS NULL AND NEW.user_id IS NOT NULL THEN
    NEW.owner_id := NEW.user_id;
  END IF;
  IF COALESCE(NEW.owner_name,'') = '' AND NEW.owner_id IS NOT NULL THEN
    SELECT full_name INTO v_name FROM public.profiles WHERE id = NEW.owner_id;
    NEW.owner_name := v_name;
  END IF;
  IF NEW.created_by IS NULL AND NEW.user_id IS NOT NULL THEN
    NEW.created_by := NEW.user_id;
  END IF;
  RETURN NEW;
END; $$;



--
-- Name: run_data_health_checks(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.run_data_health_checks() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_count integer; v_total integer := 0;
BEGIN
  SELECT COUNT(*) INTO v_count FROM public.orders o WHERE o.created_at < now() - interval '15 minutes' AND o.status IN ('confirmed','pending','draft') AND NOT EXISTS (SELECT 1 FROM public.order_items oi WHERE oi.order_id = o.id);
  INSERT INTO public.data_health_log(check_name, anomaly_count, details) VALUES ('orders_without_items', v_count, jsonb_build_object('threshold_minutes', 15)); v_total := v_total + v_count;
  SELECT COUNT(*) INTO v_count FROM public.visits v WHERE v.retailer_id IS NULL;
  INSERT INTO public.data_health_log(check_name, anomaly_count, details) VALUES ('visits_without_retailer', v_count, NULL); v_total := v_total + v_count;
  SELECT COUNT(*) INTO v_count FROM public.order_items oi WHERE oi.variant_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.product_variants pv WHERE pv.id = oi.variant_id);
  INSERT INTO public.data_health_log(check_name, anomaly_count, details) VALUES ('order_items_orphan_variant', v_count, NULL); v_total := v_total + v_count;
  SELECT COUNT(*) INTO v_count FROM public.order_items oi WHERE oi.product_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.products p WHERE p.id = oi.product_id);
  INSERT INTO public.data_health_log(check_name, anomaly_count, details) VALUES ('order_items_orphan_product', v_count, NULL); v_total := v_total + v_count;
  SELECT COUNT(*) INTO v_count FROM public.retailers r WHERE r.beat_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.beats b WHERE b.beat_id = r.beat_id);
  INSERT INTO public.data_health_log(check_name, anomaly_count, details) VALUES ('retailers_orphan_beat', v_count, NULL); v_total := v_total + v_count;
  IF v_total > 0 THEN PERFORM public.notify_admins('data_health_alert', 'Data integrity anomalies found', v_total||' data-integrity anomalies detected in the daily health check. Open Sync Health to review.'); END IF;
  RETURN v_total;
END $$;



--
-- Name: securityaudit_notify(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.securityaudit_notify() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.event_type IN ('DROP POLICY','DROP TABLE','RLS_DRIFT_REENABLED','RLS_POLICY_MISSING') THEN
    PERFORM public.notify_admins(
      'security_alert',
      'Security change: '||NEW.event_type,
      COALESCE(NEW.event_type,'')||' on '||COALESCE(NEW.table_name,'?')||COALESCE(' ('||NEW.policy_name||')','')||' by '||COALESCE(NEW.session_user_name,'?')
    );
  END IF;
  RETURN NEW;
END
$$;



--
-- Name: send_notification(uuid, text, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.send_notification(user_id_param uuid, title_param text, message_param text, type_param text DEFAULT 'info'::text, related_table_param text DEFAULT NULL::text, related_id_param uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    notification_id UUID;
BEGIN
    INSERT INTO public.notifications (user_id, title, message, type, related_table, related_id)
    VALUES (user_id_param, title_param, message_param, type_param, related_table_param, related_id_param)
    RETURNING id INTO notification_id;
    
    RETURN notification_id;
END;
$$;



