    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.is_read IS TRUE AND (OLD.is_read IS DISTINCT FROM TRUE) AND NEW.read_at IS NULL THEN
    NEW.read_at := now();
  END IF;
  RETURN NEW;
END;
$$;



