--
-- Name: to_base_qty(uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.to_base_qty(p_product_id uuid, p_qty numeric, p_uom_code text) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_factor numeric;
BEGIN
  IF p_uom_code IS NULL OR p_qty IS NULL THEN RETURN p_qty; END IF;
  SELECT pum.conversion_to_base INTO v_factor FROM public.product_uom_mapping pum JOIN public.uom_master um ON um.id = pum.uom_id WHERE pum.product_id = p_product_id AND upper(um.code) = upper(p_uom_code) AND COALESCE(pum.is_active, true) = true LIMIT 1;
  IF v_factor IS NULL OR v_factor <= 0 THEN RETURN p_qty; END IF;
  RETURN p_qty * v_factor; END; $$;



