--
-- Name: track_territory_assignment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.track_territory_assignment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Close previous assignment when user changes
  IF TG_OP = 'UPDATE' AND OLD.assigned_user_id IS DISTINCT FROM NEW.assigned_user_id THEN
    -- Close old assignment
    IF OLD.assigned_user_id IS NOT NULL THEN
      UPDATE territory_assignment_history
      SET assigned_to = now()
      WHERE territory_id = OLD.id 
        AND assigned_user_id = OLD.assigned_user_id 
        AND assigned_to IS NULL;
    END IF;
    
    -- Create new assignment
    IF NEW.assigned_user_id IS NOT NULL THEN
      INSERT INTO territory_assignment_history (territory_id, assigned_user_id, assigned_from)
      VALUES (NEW.id, NEW.assigned_user_id, now());
    END IF;
  END IF;
  
  -- Create initial assignment on insert
  IF TG_OP = 'INSERT' AND NEW.assigned_user_id IS NOT NULL THEN
    INSERT INTO territory_assignment_history (territory_id, assigned_user_id, assigned_from)
    VALUES (NEW.id, NEW.assigned_user_id, now());
  END IF;
  
  RETURN NEW;
END;
$$;



--
-- Name: transfer_beat_complete(text, uuid, uuid, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transfer_beat_complete(p_beat_id text, p_new_owner_id uuid, p_transferred_by uuid, p_reason text DEFAULT ''::text, p_effective_date date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_beat beats%ROWTYPE; v_old_owner_id UUID; v_old_owner_name TEXT; v_new_owner_name TEXT; v_retailer_count INT;
BEGIN
  IF NOT user_has_permission(p_transferred_by, 'action_beat_transfer', 'can_create') THEN RAISE EXCEPTION 'Permission denied: action_beat_transfer required'; END IF;
  SELECT * INTO v_beat FROM beats WHERE beat_id = p_beat_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Beat not found: %', p_beat_id; END IF;
  v_old_owner_id := COALESCE(v_beat.owner_id, v_beat.user_id);
  SELECT COALESCE(full_name, username) INTO v_old_owner_name FROM profiles WHERE id = v_old_owner_id;
  SELECT COALESCE(full_name, username) INTO v_new_owner_name FROM profiles WHERE id = p_new_owner_id;
  UPDATE beats SET user_id = p_new_owner_id, owner_id = p_new_owner_id, owner_name = v_new_owner_name, transferred_at = now(), transferred_by = p_transferred_by, updated_by = p_transferred_by, updated_at = now() WHERE beat_id = p_beat_id;
  UPDATE retailers SET user_id = p_new_owner_id, owner_id = p_new_owner_id, owner_name = v_new_owner_name, updated_at = now() WHERE beat_id = p_beat_id;
  GET DIAGNOSTICS v_retailer_count = ROW_COUNT;
  INSERT INTO beat_ownership_history(beat_id, beat_name, old_owner_id, old_owner_name, new_owner_id, new_owner_name, transferred_by, transferred_at, reason, effective_date) VALUES (p_beat_id, v_beat.beat_name, v_old_owner_id, v_old_owner_name, p_new_owner_id, v_new_owner_name, p_transferred_by, now(), p_reason, p_effective_date);
  INSERT INTO retailer_owner_history(retailer_id, retailer_name, old_user_id, old_user_name, new_user_id, new_user_name, changed_by, reason, beat_id) SELECT id, name, v_old_owner_id, v_old_owner_name, p_new_owner_id, v_new_owner_name, p_transferred_by, p_reason, p_beat_id FROM retailers WHERE beat_id = p_beat_id;
  UPDATE beat_user_access SET is_active = false WHERE beat_id = p_beat_id AND user_id = v_old_owner_id;
  RETURN jsonb_build_object('success', true, 'beat_name', v_beat.beat_name, 'old_owner', v_old_owner_name, 'new_owner', v_new_owner_name, 'retailers_transferred', v_retailer_count);
END; $$;



--
-- Name: transfer_retailer_beat(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transfer_retailer_beat(p_retailer_id uuid, p_new_beat_id text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_user uuid := auth.uid(); v_current record; v_beat record; v_retailer record;
BEGIN
  SELECT * INTO v_retailer FROM public.retailers WHERE id = p_retailer_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Retailer not found'; END IF;
  SELECT * INTO v_beat FROM public.beats WHERE beat_id = p_new_beat_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Target beat not found'; END IF;
  IF v_beat.is_active IS DISTINCT FROM true THEN RAISE EXCEPTION 'Cannot assign retailer to inactive beat'; END IF;
  SELECT * INTO v_current FROM public.retailer_beat_assignments WHERE retailer_id = p_retailer_id AND is_current LIMIT 1;
  IF FOUND AND v_current.beat_id = p_new_beat_id THEN RETURN jsonb_build_object('status','noop','assignment_id', v_current.id); END IF;
  IF FOUND THEN UPDATE public.retailer_beat_assignments SET assigned_to = now(), is_current = false, removed_by = v_user, transfer_reason = COALESCE(transfer_reason, p_reason), updated_at = now() WHERE id = v_current.id; END IF;
  INSERT INTO public.retailer_beat_assignments(retailer_id, beat_id, beat_name, assigned_from, is_current, assigned_by, transfer_reason, user_id) VALUES (p_retailer_id, p_new_beat_id, v_beat.beat_name, now(), true, v_user, p_reason, v_retailer.user_id);
  UPDATE public.retailers SET beat_id = p_new_beat_id, beat_name = v_beat.beat_name, updated_at = now() WHERE id = p_retailer_id;
  INSERT INTO public.beat_audit_log(beat_id, action, metadata, performed_by) VALUES (p_new_beat_id, CASE WHEN v_current.beat_id IS NULL THEN 'RETAILER_ASSIGNED_TO_BEAT' ELSE 'RETAILER_TRANSFERRED' END, jsonb_build_object('retailer_id', p_retailer_id, 'from_beat_id', v_current.beat_id, 'to_beat_id', p_new_beat_id, 'reason', p_reason), v_user);
  RETURN jsonb_build_object('status','ok','from_beat_id', v_current.beat_id, 'to_beat_id', p_new_beat_id);
END $$;



--
-- Name: transfer_user_data_partial(uuid, uuid, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transfer_user_data_partial(p_from uuid, p_to uuid, p_payload jsonb, p_dry_run boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_retailer_ids uuid[] := NULL;
  v_beat_ids uuid[] := NULL;
  v_territory_ids uuid[] := NULL;
  v_distributor_ids uuid[] := NULL;
  v_van_ids uuid[] := NULL;
  v_direct_report_ids uuid[] := NULL;
  v_confirm_dr boolean := COALESCE((p_payload->>'confirmTransferDirectReports')::boolean, false);
  v_reason text := COALESCE(p_payload->>'transferReason','');
  v_count int := 0;
  v_total_records int := 0;
  v_counts jsonb := '{}'::jsonb;
  v_warnings jsonb := '[]'::jsonb;
  v_include_payments boolean := COALESCE((p_payload->>'include_pending_payments')::boolean, false);
  v_transfer_ownership boolean := COALESCE((p_payload->>'transfer_ownership')::boolean, false);
  v_affected_retailers uuid[];
  v_outstanding_count int := 0;
  v_outstanding_amount numeric := 0;
  v_cl_count int := 0;
  v_cl_amt numeric := 0;
  v_dp_count int := 0;
  v_dp_amt numeric := 0;
  v_ic_count int := 0;
  v_ic_amt numeric := 0;
BEGIN
  IF p_from IS NULL OR p_to IS NULL OR p_from = p_to THEN
    RAISE EXCEPTION 'Invalid from/to users';
  END IF;

  v_retailer_ids := CASE WHEN p_payload ? 'retailers' THEN ARRAY(SELECT (jsonb_array_elements_text(p_payload->'retailers'))::uuid) END;
  v_beat_ids := CASE WHEN p_payload ? 'beats' THEN ARRAY(SELECT (jsonb_array_elements_text(p_payload->'beats'))::uuid) END;
  v_territory_ids := CASE WHEN p_payload ? 'territories' THEN ARRAY(SELECT (jsonb_array_elements_text(p_payload->'territories'))::uuid) END;
  v_distributor_ids := CASE WHEN p_payload ? 'distributors' THEN ARRAY(SELECT (jsonb_array_elements_text(p_payload->'distributors'))::uuid) END;
  v_van_ids := CASE WHEN p_payload ? 'vans' THEN ARRAY(SELECT (jsonb_array_elements_text(p_payload->'vans'))::uuid) END;
  v_direct_report_ids := CASE WHEN p_payload ? 'direct_reports' THEN ARRAY(SELECT (jsonb_array_elements_text(p_payload->'direct_reports'))::uuid) END;

  -- Retailers
  IF v_retailer_ids IS NOT NULL THEN
    PERFORM 1 FROM public.retailers WHERE id = ANY(v_retailer_ids) FOR UPDATE;
    IF NOT p_dry_run THEN
      UPDATE public.retailers SET user_id = p_to
        WHERE id = ANY(v_retailer_ids) AND user_id = p_from;
      IF v_transfer_ownership THEN
        UPDATE public.retailers SET owner_id = p_to
          WHERE id = ANY(v_retailer_ids) AND owner_id = p_from;
      END IF;
      GET DIAGNOSTICS v_count = ROW_COUNT;
    ELSE
      SELECT count(*) INTO v_count FROM public.retailers
        WHERE id = ANY(v_retailer_ids) AND user_id = p_from;
    END IF;
    v_counts := v_counts || jsonb_build_object('retailers', v_count);
    v_total_records := v_total_records + v_count;
  END IF;

  -- Beats
  IF v_beat_ids IS NOT NULL THEN
    IF NOT p_dry_run THEN
      UPDATE public.beats SET user_id = p_to::text
        WHERE beat_id = ANY(v_beat_ids) AND user_id = p_from::text;
      GET DIAGNOSTICS v_count = ROW_COUNT;
      -- Move retailer assignment under those beats
      UPDATE public.retailers SET user_id = p_to
        WHERE beat_id::uuid = ANY(v_beat_ids) AND user_id = p_from;
      IF v_transfer_ownership THEN
        UPDATE public.retailers SET owner_id = p_to
          WHERE beat_id::uuid = ANY(v_beat_ids) AND owner_id = p_from;
      END IF;
    ELSE
      SELECT count(*) INTO v_count FROM public.beats
        WHERE beat_id = ANY(v_beat_ids) AND user_id = p_from::text;
    END IF;
    v_counts := v_counts || jsonb_build_object('beats', v_count);
    v_total_records := v_total_records + v_count;
  END IF;

  -- Territories
  IF v_territory_ids IS NOT NULL THEN
    IF NOT p_dry_run THEN
      UPDATE public.territories SET user_id = p_to
        WHERE id = ANY(v_territory_ids) AND user_id = p_from;
      GET DIAGNOSTICS v_count = ROW_COUNT;
    ELSE
      SELECT count(*) INTO v_count FROM public.territories
        WHERE id = ANY(v_territory_ids) AND user_id = p_from;
    END IF;
    v_counts := v_counts || jsonb_build_object('territories', v_count);
    v_total_records := v_total_records + v_count;
  END IF;

  -- Distributors
  IF v_distributor_ids IS NOT NULL THEN
    IF NOT p_dry_run THEN
      UPDATE public.distributors SET user_id = p_to
        WHERE id = ANY(v_distributor_ids) AND user_id = p_from;
      GET DIAGNOSTICS v_count = ROW_COUNT;
    ELSE
      SELECT count(*) INTO v_count FROM public.distributors
        WHERE id = ANY(v_distributor_ids) AND user_id = p_from;
    END IF;
    v_counts := v_counts || jsonb_build_object('distributors', v_count);
    v_total_records := v_total_records + v_count;
  END IF;

  -- Vans
  IF v_van_ids IS NOT NULL THEN
    IF NOT p_dry_run THEN
      UPDATE public.vans SET assigned_user_id = p_to
        WHERE id = ANY(v_van_ids) AND assigned_user_id = p_from;
      GET DIAGNOSTICS v_count = ROW_COUNT;
    ELSE
      SELECT count(*) INTO v_count FROM public.vans
        WHERE id = ANY(v_van_ids) AND assigned_user_id = p_from;
    END IF;
    v_counts := v_counts || jsonb_build_object('vans', v_count);
  END IF;

  -- Direct reports
  IF v_direct_report_ids IS NOT NULL THEN
    IF NOT p_dry_run THEN
      UPDATE public.employees SET manager_id = p_to
        WHERE user_id = ANY(v_direct_report_ids) AND manager_id = p_from;
      GET DIAGNOSTICS v_count = ROW_COUNT;
    ELSE
      SELECT count(*) INTO v_count FROM public.employees
        WHERE user_id = ANY(v_direct_report_ids) AND manager_id = p_from;
    END IF;
    v_counts := v_counts || jsonb_build_object('direct_reports', v_count);
  END IF;

  -- Affected retailers for outstanding preview
  SELECT array_agg(DISTINCT rid) INTO v_affected_retailers FROM (
    SELECT unnest(COALESCE(v_retailer_ids, ARRAY[]::uuid[])) AS rid
    UNION
    SELECT id AS rid FROM public.retailers
      WHERE v_beat_ids IS NOT NULL
        AND beat_id::uuid = ANY(v_beat_ids)
  ) s WHERE rid IS NOT NULL;

  IF v_affected_retailers IS NOT NULL AND array_length(v_affected_retailers,1) > 0 THEN
    SELECT count(*), COALESCE(sum(amount),0) INTO v_cl_count, v_cl_amt
      FROM public.credit_ledger WHERE retailer_id = ANY(v_affected_retailers);
    SELECT count(*), COALESCE(sum(amount),0) INTO v_dp_count, v_dp_amt
      FROM public.distributor_payments
      WHERE retailer_id = ANY(v_affected_retailers)
        AND COALESCE(status,'') IN ('pending','open','unpaid','partial');
    SELECT count(*), COALESCE(sum(amount),0) INTO v_ic_count, v_ic_amt
      FROM public.inst_collections
      WHERE COALESCE(status,'') IN ('pending','open','unpaid','partial');
    v_outstanding_count := v_cl_count + v_dp_count + v_ic_count;
    v_outstanding_amount := v_cl_amt + v_dp_amt + v_ic_amt;
  END IF;

  IF v_outstanding_count > 0 THEN
    v_warnings := v_warnings || jsonb_build_object(
      'bucket','pending_payments',
      'message', 'Pending payments will be visible to the new user (via transferred retailer ownership) so they can collect them. Revenue from those collections is credited to the original user — historical revenue is preserved. New orders placed by the new user after this transfer will be credited to the new user automatically.'
    );
  END IF;

  RETURN jsonb_build_object(
    'dry_run', p_dry_run,
    'from', p_from,
    'to', p_to,
    'counts', v_counts,
    'warnings', v_warnings,
    'total_records', v_total_records,
    'reason', v_reason,
    'transfer_ownership', v_transfer_ownership,
    'include_pending_payments', v_include_payments,
    'outstanding_preview', jsonb_build_object(
      'affected_retailers', COALESCE(array_length(v_affected_retailers,1),0),
      'open_records', v_outstanding_count,
      'total_amount', v_outstanding_amount,
      'breakdown', jsonb_build_object(
        'credit_ledger', jsonb_build_object('count', v_cl_count, 'amount', v_cl_amt),
        'distributor_payments', jsonb_build_object('count', v_dp_count, 'amount', v_dp_amt),
        'inst_collections', jsonb_build_object('count', v_ic_count, 'amount', v_ic_amt)
      )
    )
  );
END;
$$;



--
-- Name: trg_apply_event_stock_after_order_items(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_apply_event_stock_after_order_items() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order RECORD;
  v_event_id uuid;
  v_day_id uuid;
  v_row RECORD;
  v_pid uuid;
  v_price numeric;
  v_qty numeric;
  v_conv_order numeric;
  v_conv_stock numeric;
BEGIN
  IF EXISTS (SELECT 1 FROM public.event_stock_audit WHERE order_item_id = NEW.id) THEN
    RETURN NEW;
  END IF;

  SELECT id, visit_id, order_date, status, user_id
    INTO v_order
  FROM public.orders WHERE id = NEW.order_id;
  IF v_order.visit_id IS NULL OR v_order.status = 'cancelled' THEN RETURN NEW; END IF;
  IF NEW.product_id IS NULL OR NEW.quantity IS NULL OR NEW.quantity <= 0 THEN RETURN NEW; END IF;
  BEGIN
    v_pid := NEW.product_id::uuid;
  EXCEPTION WHEN OTHERS THEN
    RETURN NEW;
  END;

  SELECT id INTO v_event_id FROM public.activity_events WHERE visit_id = v_order.visit_id LIMIT 1;
  IF v_event_id IS NULL THEN RETURN NEW; END IF;

  SELECT id INTO v_day_id
  FROM public.event_stock_days
  WHERE event_id = v_event_id AND date = v_order.order_date
  LIMIT 1;
  IF v_day_id IS NULL THEN
    SELECT id INTO v_day_id
    FROM public.event_stock_days
    WHERE event_id = v_event_id
    ORDER BY day_number ASC
    LIMIT 1;
  END IF;
  IF v_day_id IS NULL THEN RETURN NEW; END IF;

  SELECT id, sold_qty, unit INTO v_row
  FROM public.event_stock_items
  WHERE event_stock_day_id = v_day_id AND product_id = v_pid
  FOR UPDATE;

  IF NOT FOUND THEN
    v_price := COALESCE(NEW.rate, (SELECT rate FROM public.products WHERE id = v_pid), 0);
    INSERT INTO public.event_stock_items(event_stock_day_id, product_id, unit, stock_taken, sold_qty, price)
    VALUES (v_day_id, v_pid, NULLIF(NEW.unit, ''), 0, 0, v_price)
    RETURNING id, sold_qty, unit INTO v_row;
  END IF;

  v_qty := NEW.quantity;
  IF v_row.unit IS NOT NULL AND NULLIF(NEW.unit, '') IS NOT NULL
     AND lower(NEW.unit) <> lower(v_row.unit) THEN
    SELECT m.conversion_to_base INTO v_conv_order
    FROM public.product_uom_mapping m
    WHERE m.product_id = v_pid AND m.uom_id = NEW.uom_id AND m.is_active IS NOT FALSE
    LIMIT 1;
    IF v_conv_order IS NULL THEN
      SELECT m.conversion_to_base INTO v_conv_order
      FROM public.product_uom_mapping m
      JOIN public.uom_master u ON u.id = m.uom_id
      WHERE m.product_id = v_pid AND lower(u.code) = lower(NEW.unit) AND m.is_active IS NOT FALSE
      LIMIT 1;
    END IF;
    SELECT m.conversion_to_base INTO v_conv_stock
    FROM public.product_uom_mapping m
    JOIN public.uom_master u ON u.id = m.uom_id
    WHERE m.product_id = v_pid AND lower(u.code) = lower(v_row.unit) AND m.is_active IS NOT FALSE
    LIMIT 1;
    IF v_conv_order IS NOT NULL AND v_conv_stock IS NOT NULL AND v_conv_stock > 0 THEN
      v_qty := round((NEW.quantity * v_conv_order / v_conv_stock)::numeric, 3);
    END IF;
  END IF;

  UPDATE public.event_stock_items
     SET sold_qty = v_row.sold_qty + v_qty,
         updated_at = now()
   WHERE id = v_row.id;

  INSERT INTO public.event_stock_audit(
    event_stock_item_id, event_id, event_stock_day_id, product_id,
    order_id, order_item_id, visit_id, user_id,
    delta_qty, prev_sold_qty, new_sold_qty, source
  ) VALUES (
    v_row.id, v_event_id, v_day_id, v_pid,
    v_order.id, NEW.id, v_order.visit_id, v_order.user_id,
    v_qty, v_row.sold_qty, v_row.sold_qty + v_qty, 'order_submit'
  );

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'event-stock trigger failed for order_item %: %', NEW.id, SQLERRM;
  RETURN NEW;
END;
$$;



--
-- Name: trg_emit_leave_notification(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_emit_leave_notification() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_name TEXT;
  v_leave_type TEXT;
BEGIN
  IF TG_OP = 'INSERT' AND NEW.status = 'pending' THEN
    SELECT full_name INTO v_user_name FROM profiles WHERE id = NEW.user_id;
    SELECT name INTO v_leave_type FROM leave_types WHERE id = NEW.leave_type_id;

    PERFORM emit_notification_event(
      'RECORD_CREATED',
      'leave_applications',
      NEW.id::TEXT,
      NEW.user_id,
      jsonb_build_object(
        'user_name', COALESCE(v_user_name, 'Unknown'),
        'leave_type', COALESCE(v_leave_type, 'Leave'),
        'from_date', NEW.start_date,
        'to_date', NEW.end_date,
        'total_days', NEW.days_requested,
        'record_name', 'Leave Application'
      )
    );
  END IF;
  RETURN NEW;
END;
$$;



--
-- Name: trg_retailer_audit_log(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_retailer_audit_log() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE uid uuid := auth.uid(); uname text;
BEGIN
  SELECT COALESCE(full_name, username) INTO uname FROM public.profiles WHERE id = uid;
  IF NEW.name IS DISTINCT FROM OLD.name THEN INSERT INTO public.retailer_audit_log(retailer_id, field_name, old_value, new_value, changed_by, changed_by_name) VALUES (NEW.id, 'name', OLD.name, NEW.name, uid, uname); END IF;
  IF NEW.phone IS DISTINCT FROM OLD.phone THEN INSERT INTO public.retailer_audit_log(retailer_id, field_name, old_value, new_value, changed_by, changed_by_name) VALUES (NEW.id, 'phone', OLD.phone, NEW.phone, uid, uname); END IF;
  IF NEW.address IS DISTINCT FROM OLD.address THEN INSERT INTO public.retailer_audit_log(retailer_id, field_name, old_value, new_value, changed_by, changed_by_name) VALUES (NEW.id, 'address', OLD.address, NEW.address, uid, uname); END IF;
  IF NEW.owner_name IS DISTINCT FROM OLD.owner_name THEN INSERT INTO public.retailer_audit_log(retailer_id, field_name, old_value, new_value, changed_by, changed_by_name) VALUES (NEW.id, 'owner_name', OLD.owner_name, NEW.owner_name, uid, uname); END IF;
  IF NEW.gst_number IS DISTINCT FROM OLD.gst_number THEN INSERT INTO public.retailer_audit_log(retailer_id, field_name, old_value, new_value, changed_by, changed_by_name) VALUES (NEW.id, 'gst_number', OLD.gst_number, NEW.gst_number, uid, uname); END IF;
  IF NEW.verified IS DISTINCT FROM OLD.verified THEN INSERT INTO public.retailer_audit_log(retailer_id, field_name, old_value, new_value, changed_by, changed_by_name) VALUES (NEW.id, 'verified', OLD.verified::text, NEW.verified::text, uid, uname); END IF;
  IF NEW.status IS DISTINCT FROM OLD.status THEN INSERT INTO public.retailer_audit_log(retailer_id, field_name, old_value, new_value, changed_by, changed_by_name) VALUES (NEW.id, 'status', OLD.status, NEW.status, uid, uname); END IF;
  RETURN NEW;
END; $$;



--
-- Name: trg_retailer_duplicate_check(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_retailer_duplicate_check() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN NEW.duplicate_risk_score := public.detect_retailer_duplicates(NEW.id, NEW.phone, NEW.gst_number, NEW.latitude, NEW.longitude, NEW.name, NEW.address); RETURN NEW; END; $$;



--
-- Name: trg_retailer_score_recalc(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_retailer_score_recalc() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' OR (NEW.name IS DISTINCT FROM OLD.name) OR (NEW.phone IS DISTINCT FROM OLD.phone) OR (NEW.address IS DISTINCT FROM OLD.address) OR (NEW.category IS DISTINCT FROM OLD.category) OR (NEW.gst_number IS DISTINCT FROM OLD.gst_number) OR (NEW.latitude IS DISTINCT FROM OLD.latitude) OR (NEW.longitude IS DISTINCT FROM OLD.longitude) OR (NEW.photo_url IS DISTINCT FROM OLD.photo_url) OR (NEW.shop_front_visible IS DISTINCT FROM OLD.shop_front_visible) OR (NEW.owner_name IS DISTINCT FROM OLD.owner_name) OR (NEW.alternate_phone IS DISTINCT FROM OLD.alternate_phone) OR (NEW.distributor_id IS DISTINCT FROM OLD.distributor_id) OR (NEW.beat_id IS DISTINCT FROM OLD.beat_id) OR (NEW.retail_type IS DISTINCT FROM OLD.retail_type) OR (NEW.whatsapp_verified IS DISTINCT FROM OLD.whatsapp_verified) OR (NEW.retailer_confirmed IS DISTINCT FROM OLD.retailer_confirmed) OR (NEW.verified IS DISTINCT FROM OLD.verified) OR (NEW.verification_address IS DISTINCT FROM OLD.verification_address) OR (NEW.first_visit_completed IS DISTINCT FROM OLD.first_visit_completed) OR (NEW.first_order_placed IS DISTINCT FROM OLD.first_order_placed) THEN
    PERFORM public.calculate_retailer_quality_score(NEW.id);
  END IF;
  RETURN NEW;
END; $$;



--
-- Name: trigger_create_expense_approval_request(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trigger_create_expense_approval_request() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_workflow_id uuid;
  v_workflow RECORD;
  v_step RECORD;
  v_request_id uuid;
  v_approver_id uuid;
  v_chain RECORD;
  v_levels integer := 0;
  v_category_id uuid;
BEGIN
  -- Only fire on new submissions (status = 'submitted')
  IF NEW.status != 'submitted' THEN
    RETURN NEW;
  END IF;
  
  -- For updates, only fire if status changed to submitted
  IF TG_OP = 'UPDATE' AND OLD.status = 'submitted' THEN
    RETURN NEW;
  END IF;

  -- Step 1: Try to match an expense_approval_rule
  v_workflow_id := NULL;

  -- Try amount-based rules first
  SELECT r.workflow_id INTO v_workflow_id
  FROM expense_approval_rules r
  WHERE r.is_active = true
    AND r.condition_type = 'amount_range'
    AND (r.condition_value->>'min')::numeric <= NEW.amount
    AND (r.condition_value->>'max')::numeric >= NEW.amount
  ORDER BY r.priority ASC
  LIMIT 1;

  -- Try category-based rules if no amount match
  IF v_workflow_id IS NULL THEN
    -- Look up category id from name
    SELECT ec.id INTO v_category_id
    FROM expense_categories ec
    WHERE ec.name = NEW.category AND ec.is_active = true
    LIMIT 1;

    IF v_category_id IS NOT NULL THEN
      SELECT r.workflow_id INTO v_workflow_id
      FROM expense_approval_rules r
      WHERE r.is_active = true
        AND r.condition_type = 'category'
        AND (r.condition_value->>'category_id')::uuid = v_category_id
      ORDER BY r.priority ASC
      LIMIT 1;
    END IF;
  END IF;

  -- Try 'always' rules as final fallback
  IF v_workflow_id IS NULL THEN
    SELECT r.workflow_id INTO v_workflow_id
    FROM expense_approval_rules r
    WHERE r.is_active = true
      AND r.condition_type = 'always'
    ORDER BY r.priority ASC
    LIMIT 1;
  END IF;

  -- Fallback: use default workflow
  IF v_workflow_id IS NULL THEN
    SELECT id INTO v_workflow_id
    FROM approval_workflows
    WHERE entity_type = 'expense' AND is_default = true AND is_active = true
    LIMIT 1;
  END IF;

  -- Ultimate fallback: use old approval_config behavior
  IF v_workflow_id IS NULL THEN
    DECLARE
      v_approval_mode text;
    BEGIN
      SELECT approval_mode INTO v_approval_mode
      FROM approval_config
      WHERE entity_type = 'expense';

      IF v_approval_mode = 'auto' THEN
        NEW.status := 'manager_approved';
        NEW.approved_at := now();
        RETURN NEW;
      END IF;

      PERFORM create_approval_request('expense', NEW.id, NEW.user_id);
      RETURN NEW;
    END;
  END IF;

  -- Load workflow
  SELECT * INTO v_workflow FROM approval_workflows WHERE id = v_workflow_id;

  -- If no steps exist, auto-approve
  IF NOT EXISTS (SELECT 1 FROM workflow_steps WHERE workflow_id = v_workflow_id) THEN
    NEW.status := 'manager_approved';
    NEW.approved_at := now();
    RETURN NEW;
  END IF;

  -- Create approval_request
  INSERT INTO approval_requests (entity_type, entity_id, requester_id, current_level, total_levels, status)
  SELECT 'expense', NEW.id, NEW.user_id, 1, COUNT(*), 'pending'
  FROM workflow_steps WHERE workflow_id = v_workflow_id
  RETURNING id INTO v_request_id;

  -- Create approval_steps from workflow_steps
  FOR v_step IN
    SELECT * FROM workflow_steps
    WHERE workflow_id = v_workflow_id
    ORDER BY step_number ASC
  LOOP
    v_approver_id := NULL;

    IF v_step.approver_type = 'specific_user' AND v_step.specific_user_id IS NOT NULL THEN
      v_approver_id := v_step.specific_user_id;
    ELSIF v_step.approver_type = 'manager' OR v_step.approver_type = 'hierarchy_level' THEN
      -- Get manager at the right level from reporting chain
      SELECT manager_id INTO v_approver_id
      FROM get_reporting_chain(NEW.user_id)
      WHERE level = COALESCE(v_step.hierarchy_level, v_step.step_number)
      LIMIT 1;
    END IF;

    -- Skip step if no approver found
    IF v_approver_id IS NOT NULL THEN
      INSERT INTO approval_steps (approval_request_id, level, approver_id, status)
      VALUES (v_request_id, v_step.step_number, v_approver_id, 'pending');
    END IF;
  END LOOP;

  -- Log submission
  INSERT INTO approval_audit_log (approval_request_id, entity_type, entity_id, action, performed_by, level, metadata)
  VALUES (v_request_id, 'expense', NEW.id, 'submitted', NEW.user_id, 0,
          jsonb_build_object('workflow_id', v_workflow_id, 'workflow_name', v_workflow.workflow_name));

  RETURN NEW;
END;
$$;



