--
-- Name: trigger_notification_attendance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trigger_notification_attendance() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tz text;
  v_ts timestamptz;
BEGIN
  BEGIN
    v_ts := COALESCE(NEW.check_in_time, now());
    -- Use the timezone SELECTED on the active attendance rule (fallback Asia/Kolkata),
    -- so {time}/{date} render in that zone instead of the DB's UTC.
    SELECT COALESCE(NULLIF(timezone,''),'Asia/Kolkata') INTO v_tz
    FROM public.notification_rules
    WHERE source_table='attendance' AND event_code='RECORD_CREATED' AND is_active
    ORDER BY updated_at DESC NULLS LAST
    LIMIT 1;
    v_tz := COALESCE(v_tz, 'Asia/Kolkata');

    PERFORM public.emit_notification_event(
      'RECORD_CREATED','attendance', NEW.id::text, NEW.user_id,
      jsonb_build_object(
        'date',       to_char(v_ts AT TIME ZONE v_tz, 'YYYY-MM-DD'),
        'time',       to_char(v_ts AT TIME ZONE v_tz, 'HH12:MI am'),
        'time_24',    to_char(v_ts AT TIME ZONE v_tz, 'HH24:MI'),
        'timezone',   v_tz,
        'record_name','attendance'));
  EXCEPTION WHEN others THEN NULL;
  END;
  RETURN NEW;
END $$;



--
-- Name: trigger_notification_attendance_checkout(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trigger_notification_attendance_checkout() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_tz text; v_ts timestamptz;
BEGIN
  BEGIN
    IF NEW.check_out_time IS NOT NULL THEN
      v_ts := NEW.check_out_time;
      SELECT COALESCE(NULLIF(timezone,''),'Asia/Kolkata') INTO v_tz
      FROM public.notification_rules
      WHERE source_table='attendance' AND event_code='RECORD_UPDATED' AND is_active
      ORDER BY updated_at DESC NULLS LAST LIMIT 1;
      v_tz := COALESCE(v_tz,'Asia/Kolkata');
      PERFORM public.emit_notification_event('RECORD_UPDATED','attendance', NEW.id::text, NEW.user_id,
        jsonb_build_object(
          'date',       to_char(v_ts AT TIME ZONE v_tz, 'YYYY-MM-DD'),
          'time',       to_char(v_ts AT TIME ZONE v_tz, 'HH12:MI am'),
          'time_24',    to_char(v_ts AT TIME ZONE v_tz, 'HH24:MI'),
          'timezone',   v_tz,
          'record_name','attendance'));
    END IF;
  EXCEPTION WHEN OTHERS THEN NULL;
  END;
  RETURN NEW;
END; $$;



