--
-- Name: update_child_territories_count(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_child_territories_count() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Update parent's child count when a territory is added/updated with a parent
  IF NEW.parent_id IS NOT NULL THEN
    UPDATE territories
    SET child_territories_count = (
      SELECT COUNT(*) 
      FROM territories 
      WHERE parent_id = NEW.parent_id
    )
    WHERE id = NEW.parent_id;
  END IF;
  
  -- Update old parent's count if parent changed
  IF TG_OP = 'UPDATE' AND OLD.parent_id IS DISTINCT FROM NEW.parent_id AND OLD.parent_id IS NOT NULL THEN
    UPDATE territories
    SET child_territories_count = (
      SELECT COUNT(*) 
      FROM territories 
      WHERE parent_id = OLD.parent_id
    )
    WHERE id = OLD.parent_id;
  END IF;
  
  RETURN NEW;
END;
$$;



