-- Name: update_child_territories_count_on_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_child_territories_count_on_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF OLD.parent_id IS NOT NULL THEN
    UPDATE territories
    SET child_territories_count = (
      SELECT COUNT(*) 
      FROM territories 
      WHERE parent_id = OLD.parent_id
    )
    WHERE id = OLD.parent_id;
  END IF;
  
  RETURN OLD;
END;
$$;



