--
-- Name: update_leave_balance_on_approval(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_leave_balance_on_approval() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    leave_days INTEGER;
BEGIN
    -- Only update balance when status changes to approved
    IF NEW.status = 'approved' AND OLD.status != 'approved' THEN
        -- Calculate number of leave days
        leave_days := NEW.end_date - NEW.start_date + 1;
        
        -- Update or insert leave balance
        INSERT INTO public.leave_balance (user_id, leave_type_id, used_balance)
        VALUES (NEW.user_id, NEW.leave_type_id, leave_days)
        ON CONFLICT (user_id, leave_type_id, year)
        DO UPDATE SET 
            used_balance = public.leave_balance.used_balance + leave_days,
            updated_at = now();
    END IF;
    
    RETURN NEW;
END;
$$;



--
-- Name: update_leave_balance_on_status_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_leave_balance_on_status_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  leave_days NUMERIC;
BEGIN
  leave_days := COALESCE(NEW.days_requested, NEW.end_date - NEW.start_date + 1);

  -- NEW application (INSERT): deduct immediately
  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.leave_balance (user_id, leave_type_id, year, opening_balance, used_balance)
    VALUES (NEW.user_id, NEW.leave_type_id, EXTRACT(YEAR FROM NEW.start_date)::INTEGER, 0, leave_days)
    ON CONFLICT (user_id, leave_type_id, year)
    DO UPDATE SET
      used_balance = leave_balance.used_balance + leave_days,
      updated_at = now();
    RETURN NEW;
  END IF;

  -- UPDATE: if status changed to rejected/cancelled, restore balance
  IF TG_OP = 'UPDATE' THEN
    IF NEW.status IN ('rejected', 'cancelled') AND OLD.status NOT IN ('rejected', 'cancelled') THEN
      UPDATE public.leave_balance
      SET used_balance = GREATEST(0, used_balance - leave_days), updated_at = now()
      WHERE user_id = NEW.user_id
        AND leave_type_id = NEW.leave_type_id
        AND year = EXTRACT(YEAR FROM NEW.start_date)::INTEGER;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;



--
-- Name: update_leave_balance_on_submit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_leave_balance_on_submit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_days NUMERIC;
  v_year INTEGER;
BEGIN
  v_year := EXTRACT(YEAR FROM COALESCE(NEW.start_date, OLD.start_date));

  IF TG_OP = 'INSERT' AND NEW.status IN ('pending', 'approved') THEN
    v_days := COALESCE(NEW.days_requested, NEW.end_date - NEW.start_date + 1);
    IF COALESCE(NEW.is_half_day, false) THEN v_days := 0.5; END IF;

    -- Ensure balance row exists
    INSERT INTO leave_balance (user_id, leave_type_id, year, opening_balance, used_balance)
    VALUES (NEW.user_id, NEW.leave_type_id, v_year, 0, 0)
    ON CONFLICT (user_id, leave_type_id, year) DO NOTHING;

    UPDATE leave_balance
    SET used_balance = used_balance + v_days, updated_at = now()
    WHERE user_id = NEW.user_id AND leave_type_id = NEW.leave_type_id AND year = v_year;

  ELSIF TG_OP = 'UPDATE' AND OLD.status IN ('pending', 'approved') AND NEW.status IN ('rejected', 'cancelled') THEN
    v_days := COALESCE(OLD.days_requested, OLD.end_date - OLD.start_date + 1);
    IF COALESCE(OLD.is_half_day, false) THEN v_days := 0.5; END IF;

    UPDATE leave_balance
    SET used_balance = GREATEST(0, used_balance - v_days), updated_at = now()
    WHERE user_id = OLD.user_id AND leave_type_id = OLD.leave_type_id AND year = v_year;
  END IF;

  RETURN NEW;
END;
$$;



