--
-- Name: update_picking_atomic(uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_picking_atomic(p_batch_row_id uuid, p_picked_qty numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_pli_id UUID; v_total_picked NUMERIC; v_total_allocated NUMERIC; v_short_qty NUMERIC;
BEGIN
  UPDATE packing_list_item_batches SET picked_qty = p_picked_qty WHERE id = p_batch_row_id RETURNING packing_list_item_id INTO v_pli_id;
  IF v_pli_id IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'Batch row not found'); END IF;
  SELECT COALESCE(SUM(picked_qty), 0), COALESCE(SUM(allocated_qty), 0) INTO v_total_picked, v_total_allocated FROM packing_list_item_batches WHERE packing_list_item_id = v_pli_id;
  v_short_qty := GREATEST(0, v_total_allocated - v_total_picked);
  UPDATE packing_list_items SET picked_qty = v_total_picked, short_qty = v_short_qty WHERE id = v_pli_id;
  RETURN jsonb_build_object('success', true, 'total_picked', v_total_picked, 'short_qty', v_short_qty);
END; $$;



