--
-- Name: user_has_action_permission(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.user_has_action_permission(_user_id uuid, _action text, _perm text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE result boolean;
BEGIN
  IF _perm NOT IN ('can_read','can_create','can_edit','can_delete','can_view_all','can_modify_all') THEN RAISE EXCEPTION 'Invalid permission column: %', _perm; END IF;
  EXECUTE format($f$ SELECT EXISTS (SELECT 1 FROM public.user_profiles up JOIN public.profile_object_permissions pop ON pop.profile_id = up.profile_id WHERE up.user_id = $1 AND pop.object_name = $2 AND pop.%I = true) $f$, _perm) INTO result USING _user_id, _action;
  RETURN COALESCE(result, false);
END; $_$;



--
-- Name: user_has_beat_access(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.user_has_beat_access(_user_id uuid, _beat_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (SELECT 1 FROM beats WHERE beat_id = _beat_id AND user_id = _user_id UNION ALL SELECT 1 FROM beat_user_access WHERE beat_id = _beat_id AND user_id = _user_id AND is_active = true AND (effective_to IS NULL OR effective_to > now()) UNION ALL SELECT 1 FROM beat_coverage_assignments WHERE beat_id = _beat_id AND coverage_user_id = _user_id AND is_active = true AND start_date <= CURRENT_DATE AND end_date >= CURRENT_DATE);
$$;



--
-- Name: user_has_operational_access(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.user_has_operational_access(_user uuid, _retailer uuid, _perm text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    public.user_owns_retailer(_user, _retailer)
    OR EXISTS (
      SELECT 1 FROM public.retailer_shared_access s
       WHERE s.retailer_id = _retailer
         AND s.shared_to_user_id = _user
         AND s.is_active = true
         AND s.effective_from <= now()
         AND (s.effective_to IS NULL OR s.effective_to >= now())
         AND CASE _perm
               WHEN 'view'     THEN s.can_view
               WHEN 'order'    THEN s.can_take_orders
               WHEN 'collect'  THEN s.can_collect_payment
               WHEN 'feedback' THEN s.can_update_feedback
               ELSE false END
    );
$$;



--
-- Name: user_has_permission(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.user_has_permission(_user_id uuid, _object text, _perm text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  result boolean := false;
BEGIN
  IF _perm NOT IN ('can_read','can_create','can_edit','can_delete','can_view_all','can_modify_all') THEN
    RAISE EXCEPTION 'Invalid permission: %', _perm;
  END IF;

  EXECUTE format(
    'SELECT COALESCE(%I, false) FROM user_object_permissions
     WHERE user_id = $1 AND object_name = $2 LIMIT 1', _perm)
  INTO result USING _user_id, _object;
  IF result THEN RETURN true; END IF;

  EXECUTE format(
    'SELECT EXISTS (
       SELECT 1 FROM coverage_permission_assignments cpa
       JOIN permission_set_group_permissions psgp ON psgp.group_id = cpa.permission_set_id
       WHERE cpa.user_id = $1
         AND psgp.object_name = $2
         AND psgp.%I = true
         AND cpa.is_active = true
         AND cpa.start_date <= CURRENT_DATE
         AND cpa.end_date >= CURRENT_DATE
     )', _perm)
  INTO result USING _user_id, _object;
  IF result THEN RETURN true; END IF;

  EXECUTE format(
    'SELECT EXISTS (
       SELECT 1 FROM permission_set_group_users psgu
       JOIN permission_set_group_permissions psgp ON psgp.group_id = psgu.group_id
       WHERE psgu.user_id = $1
         AND psgp.object_name = $2
         AND psgp.%I = true
     )', _perm)
  INTO result USING _user_id, _object;
  IF result THEN RETURN true; END IF;

  EXECUTE format(
    'SELECT EXISTS (
       SELECT 1 FROM user_profiles up
       JOIN profile_object_permissions pop ON pop.profile_id = up.profile_id
       WHERE up.user_id = $1
         AND pop.object_name = $2
         AND pop.%I = true
     )', _perm)
  INTO result USING _user_id, _object;
  RETURN COALESCE(result, false);
END;
$_$;



