--
-- Name: validate_activity_event_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_activity_event_status() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.status NOT IN ('upcoming', 'active', 'closed') THEN
    RAISE EXCEPTION
      'Invalid activity_events.status: %. Allowed: upcoming, active, closed',
      NEW.status;
  END IF;
  RETURN NEW;
END;
$$;



--
-- Name: validate_batch_packed_qty(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_batch_packed_qty() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.packed_qty IS NULL THEN
    NEW.packed_qty := 0;
  END IF;
  IF NEW.packed_qty < 0 THEN
    RAISE EXCEPTION 'packed_qty cannot be negative';
  END IF;
  IF NEW.packed_qty > COALESCE(NEW.picked_qty, 0) THEN
    RAISE EXCEPTION 'packed_qty (%) cannot exceed picked_qty (%)', NEW.packed_qty, NEW.picked_qty;
  END IF;
  RETURN NEW;
END;
$$;



--
-- Name: validate_distributor_payment_modes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_distributor_payment_modes() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.allowed_payment_modes IS NULL OR array_length(NEW.allowed_payment_modes, 1) IS NULL THEN
    RAISE EXCEPTION 'At least one allowed payment mode is required';
  END IF;
  IF NEW.default_payment_mode IS NOT NULL AND NOT (NEW.default_payment_mode = ANY(NEW.allowed_payment_modes)) THEN
    RAISE EXCEPTION 'default_payment_mode must be one of allowed_payment_modes';
  END IF;
  IF NEW.allowed_payment_terms IS NULL OR array_length(NEW.allowed_payment_terms, 1) IS NULL THEN
    RAISE EXCEPTION 'At least one allowed payment term is required';
  END IF;
  IF NEW.default_payment_term IS NOT NULL AND NOT (NEW.default_payment_term = ANY(NEW.allowed_payment_terms)) THEN
    RAISE EXCEPTION 'default_payment_term must be one of allowed_payment_terms';
  END IF;
  RETURN NEW;
END;
$$;



--
-- Name: validate_invitation_token(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_invitation_token(_token text) RETURNS TABLE(id uuid, email text, full_name text, phone_number text, manager_id uuid, expires_at timestamp with time zone)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT 
    ui.id,
    ui.email,
    ui.full_name,
    ui.phone_number,
    ui.manager_id,
    ui.expires_at
  FROM public.user_invitations ui
  WHERE ui.invitation_token = _token
    AND ui.status = 'pending'
    AND ui.expires_at > now()
  LIMIT 1;
$$;



--
-- Name: validate_leave_application(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_leave_application() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_balance NUMERIC;
  v_policy jsonb;
  v_overlapping INTEGER;
  v_days NUMERIC;
  v_allow_neg BOOLEAN;
  v_max_neg INT;
  v_max_backdate INT;
  v_allow_backdate BOOLEAN;
  v_min_notice INT;
  v_max_per_month NUMERIC;
  v_days_in_month NUMERIC;
BEGIN
  -- Resolve effective policy from global + override
  v_policy := resolve_effective_leave_policy(NEW.leave_type_id);
  
  IF v_policy ? 'error' THEN
    RAISE EXCEPTION 'Leave policy not configured: %', v_policy->>'error';
  END IF;

  -- Check overlapping leaves (exclude current row on UPDATE)
  SELECT COUNT(*) INTO v_overlapping FROM leave_applications
  WHERE user_id = NEW.user_id
    AND id != COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000'::uuid)
    AND status NOT IN ('rejected', 'cancelled')
    AND (NEW.start_date, NEW.end_date) OVERLAPS (start_date, end_date);
  
  IF v_overlapping > 0 THEN
    RAISE EXCEPTION 'Overlapping leave request exists for these dates';
  END IF;
  
  -- Check backdated limit using global policy
  v_allow_backdate := COALESCE((v_policy->>'allow_backdated_leave')::boolean, false);
  v_max_backdate := COALESCE((v_policy->>'max_backdate_days')::int, 0);
  
  IF NEW.start_date < CURRENT_DATE THEN
    IF NOT v_allow_backdate THEN
      RAISE EXCEPTION 'Backdated leave is not allowed by policy';
    END IF;
    IF NEW.start_date < CURRENT_DATE - v_max_backdate THEN
      RAISE EXCEPTION 'Backdated leave request exceeds allowed limit of % days', v_max_backdate;
    END IF;
  END IF;
  
  -- Check advance notice using global policy
  v_min_notice := COALESCE((v_policy->>'min_notice_period_days')::int, 0);
  IF v_min_notice > 0 AND NEW.start_date > CURRENT_DATE THEN
    IF NEW.start_date < CURRENT_DATE + v_min_notice THEN
      RAISE EXCEPTION 'Leave request requires % days advance notice', v_min_notice;
    END IF;
  END IF;
  
  -- Calculate days
  v_days := (NEW.end_date - NEW.start_date + 1);
  IF COALESCE(NEW.is_half_day, false) THEN
    v_days := 0.5;
  END IF;
  NEW.days_requested := v_days;
  
  -- Check max continuous days
  IF (v_policy->>'max_continuous_leave_days') IS NOT NULL AND v_days > (v_policy->>'max_continuous_leave_days')::int THEN
    RAISE EXCEPTION 'Cannot take more than % continuous leave days', (v_policy->>'max_continuous_leave_days')::int;
  END IF;

  -- Check max leaves per month (from leave_policy if exists)
  SELECT max_leaves_per_month INTO v_max_per_month FROM leave_policy
  WHERE leave_type_id = NEW.leave_type_id AND is_active = true;
  
  IF v_max_per_month IS NOT NULL THEN
    SELECT COALESCE(SUM(days_requested), 0) INTO v_days_in_month
    FROM leave_applications
    WHERE user_id = NEW.user_id
      AND leave_type_id = NEW.leave_type_id
      AND status NOT IN ('rejected', 'cancelled')
      AND EXTRACT(MONTH FROM start_date) = EXTRACT(MONTH FROM NEW.start_date)
      AND EXTRACT(YEAR FROM start_date) = EXTRACT(YEAR FROM NEW.start_date)
      AND id != COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000'::uuid);
    
    IF (v_days_in_month + v_days) > v_max_per_month THEN
      RAISE EXCEPTION 'Exceeds maximum % leaves allowed per month', v_max_per_month;
    END IF;
  END IF;
  
  -- Check balance
  SELECT remaining_balance INTO v_balance FROM leave_balance
  WHERE user_id = NEW.user_id 
    AND leave_type_id = NEW.leave_type_id 
    AND year = EXTRACT(YEAR FROM NEW.start_date);
  
  v_allow_neg := COALESCE((v_policy->>'allow_negative_balance')::boolean, false);
  v_max_neg := COALESCE((v_policy->>'max_negative_limit')::int, 0);
  
  IF COALESCE(v_balance, 0) < v_days AND NOT v_allow_neg THEN
    RAISE EXCEPTION 'Insufficient leave balance. Available: %, Requested: %', COALESCE(v_balance, 0), v_days;
  END IF;
  
  IF v_allow_neg AND (COALESCE(v_balance, 0) - v_days) < -v_max_neg THEN
    RAISE EXCEPTION 'Exceeds maximum negative balance limit of % days', v_max_neg;
  END IF;
  
  RETURN NEW;
END;
$$;



--
-- Name: validate_leave_request(uuid, uuid, date, date, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_leave_request(p_user_id uuid, p_leave_type_id uuid, p_start_date date, p_end_date date, p_is_half_day boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_policy jsonb;
  v_days numeric;
  v_balance numeric;
  v_max_neg int;
  v_allow_neg boolean;
  v_overlapping int;
  v_sandwich int := 0;
BEGIN
  v_policy := resolve_effective_leave_policy(p_leave_type_id);
  
  IF v_policy ? 'error' THEN
    RETURN jsonb_build_object('is_valid', false, 'error_code', 'NO_POLICY', 'error_message', v_policy->>'error');
  END IF;

  -- Check enabled
  IF NOT (v_policy->>'is_enabled')::boolean THEN
    RETURN jsonb_build_object('is_valid', false, 'error_code', 'DISABLED', 'error_message', 'Leave applications are disabled');
  END IF;

  -- Check dates
  IF p_end_date < p_start_date THEN
    RETURN jsonb_build_object('is_valid', false, 'error_code', 'INVALID_DATES', 'error_message', 'End date cannot be before start date');
  END IF;

  -- Calculate days
  v_days := (p_end_date - p_start_date + 1);
  IF p_is_half_day THEN v_days := 0.5; END IF;

  -- Check backdate
  IF p_start_date < CURRENT_DATE THEN
    IF NOT (v_policy->>'allow_backdated_leave')::boolean THEN
      RETURN jsonb_build_object('is_valid', false, 'error_code', 'NO_BACKDATE', 'error_message', 'Backdated leave is not allowed');
    END IF;
    IF p_start_date < CURRENT_DATE - COALESCE((v_policy->>'max_backdate_days')::int, 0) THEN
      RETURN jsonb_build_object('is_valid', false, 'error_code', 'BACKDATE_EXCEEDED',
        'error_message', 'Backdated leave cannot exceed ' || (v_policy->>'max_backdate_days') || ' days');
    END IF;
  END IF;

  -- Check notice period for future dates
  IF p_start_date > CURRENT_DATE AND COALESCE((v_policy->>'min_notice_period_days')::int, 0) > 0 THEN
    IF p_start_date < CURRENT_DATE + (v_policy->>'min_notice_period_days')::int THEN
      RETURN jsonb_build_object('is_valid', false, 'error_code', 'NOTICE_PERIOD',
        'error_message', 'Leave requires ' || (v_policy->>'min_notice_period_days') || ' days advance notice');
    END IF;
  END IF;

  -- Check max continuous days
  IF (v_policy->>'max_continuous_leave_days') IS NOT NULL AND v_days > (v_policy->>'max_continuous_leave_days')::int THEN
    RETURN jsonb_build_object('is_valid', false, 'error_code', 'MAX_CONTINUOUS',
      'error_message', 'Cannot take more than ' || (v_policy->>'max_continuous_leave_days') || ' continuous days');
  END IF;

  -- Check overlap
  SELECT COUNT(*) INTO v_overlapping FROM leave_applications
  WHERE user_id = p_user_id
    AND status NOT IN ('rejected', 'cancelled')
    AND (p_start_date, p_end_date) OVERLAPS (start_date, end_date);
  IF v_overlapping > 0 THEN
    RETURN jsonb_build_object('is_valid', false, 'error_code', 'OVERLAP', 'error_message', 'Overlapping leave request exists');
  END IF;

  -- Check balance
  SELECT COALESCE(remaining_balance, 0) INTO v_balance FROM leave_balance
  WHERE user_id = p_user_id AND leave_type_id = p_leave_type_id
    AND year = EXTRACT(YEAR FROM p_start_date)::int;

  v_allow_neg := COALESCE((v_policy->>'allow_negative_balance')::boolean, false);
  v_max_neg := COALESCE((v_policy->>'max_negative_limit')::int, 0);

  IF COALESCE(v_balance, 0) < v_days THEN
    IF NOT v_allow_neg THEN
      RETURN jsonb_build_object('is_valid', false, 'error_code', 'INSUFFICIENT_BALANCE',
        'error_message', 'Insufficient leave balance. Available: ' || COALESCE(v_balance, 0) || ', Requested: ' || v_days,
        'current_balance', COALESCE(v_balance, 0), 'days_requested', v_days);
    END IF;
    IF ABS(COALESCE(v_balance, 0) - v_days) > v_max_neg THEN
      RETURN jsonb_build_object('is_valid', false, 'error_code', 'NEGATIVE_LIMIT',
        'error_message', 'Exceeds maximum negative balance limit of ' || v_max_neg || ' days',
        'current_balance', COALESCE(v_balance, 0), 'days_requested', v_days);
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'is_valid', true,
    'days_requested', v_days,
    'current_balance', COALESCE(v_balance, 0),
    'balance_after', COALESCE(v_balance, 0) - v_days,
    'sandwich_days', v_sandwich
  );
END;
$$;



--
-- Name: validate_packing_list_order_type(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_packing_list_order_type() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_type_code text;
  v_supports_primary boolean;
BEGIN
  IF NEW.order_type = 'secondary' THEN
    RETURN NEW;
  END IF;

  IF NEW.distributor_id IS NULL THEN
    RAISE EXCEPTION 'distributor_id is required for primary packing lists';
  END IF;

  SELECT dt.code INTO v_type_code
  FROM distributors d
  JOIN distributor_types dt ON dt.id = d.type_id
  WHERE d.id = NEW.distributor_id;

  IF v_type_code IS NULL THEN
    RAISE EXCEPTION 'Distributor not found or has no assigned type (distributor_id: %)', NEW.distributor_id;
  END IF;

  SELECT get_type_supports_primary(v_type_code) INTO v_supports_primary;

  IF NOT COALESCE(v_supports_primary, false) THEN
    RAISE EXCEPTION 'Distributor type "%" does not support primary packing', v_type_code;
  END IF;

  RETURN NEW;
END;
$$;



--
-- Name: validate_primary_order_status_transition(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_primary_order_status_transition() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  valid_transitions jsonb := '{
    "draft": ["pending", "cancelled"],
    "pending": ["submitted", "cancelled"],
    "submitted": ["confirmed", "allocated", "cancelled", "rejected"],
    "confirmed": ["processing", "allocated", "cancelled"],
    "processing": ["allocated", "cancelled"],
    "allocated": ["packed", "dispatched", "shipped", "cancelled"],
    "packed": ["dispatched", "shipped", "cancelled"],
    "shipped": ["partially_delivered", "delivered"],
    "dispatched": ["partially_delivered", "delivered", "completed"],
    "partially_delivered": ["delivered", "completed"],
    "delivered": ["completed"]
  }'::jsonb;
BEGIN
  IF (SELECT public.is_system_admin(auth.uid())) THEN RETURN NEW; END IF;
  IF OLD.status = NEW.status THEN RETURN NEW; END IF;
  IF NOT (valid_transitions ? OLD.status) THEN RETURN NEW; END IF;
  IF NOT (valid_transitions->OLD.status @> to_jsonb(NEW.status)) THEN
    RAISE EXCEPTION 'Invalid status transition: % to %', OLD.status, NEW.status;
  END IF;
  RETURN NEW;
END;
$$;



--
-- Name: validate_product_uom_mapping_state(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_product_uom_mapping_state() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_product_id uuid; v_base_count integer; v_sales_count integer; v_price_count integer; v_bad_factor integer;
BEGIN
  v_product_id := COALESCE(NEW.product_id, OLD.product_id);
  SELECT COUNT(*) FILTER (WHERE is_base), COUNT(*) FILTER (WHERE is_default_sales), COUNT(*) FILTER (WHERE is_price_basis), COUNT(*) FILTER (WHERE conversion_to_base <= 0)
    INTO v_base_count, v_sales_count, v_price_count, v_bad_factor
    FROM public.product_uom_mapping WHERE product_id = v_product_id AND COALESCE(is_active, true) = true;
  IF v_bad_factor > 0 THEN RAISE EXCEPTION 'All unit conversion factors must be positive'; END IF;
  IF v_base_count > 1 THEN RAISE EXCEPTION 'Only one base unit is allowed per product'; END IF;
  IF v_sales_count > 1 THEN RAISE EXCEPTION 'Only one default sales unit is allowed per product'; END IF;
  IF v_price_count > 1 THEN RAISE EXCEPTION 'Only one price-basis unit is allowed per product'; END IF;
  RETURN NULL; END; $$;



--
-- Name: verify_hint_answer(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_hint_answer(user_email text, submitted_answer text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  stored_answer text;
BEGIN
  SELECT p.hint_answer INTO stored_answer
  FROM public.profiles p
  JOIN auth.users u ON p.id = u.id
  WHERE u.email = user_email;
  
  RETURN LOWER(TRIM(stored_answer)) = LOWER(TRIM(submitted_answer));
END;
$$;



--
-- Name: verify_hint_answer_secure(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_hint_answer_secure(user_email text, submitted_answer text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  stored_hash text;
  computed_hash text;
BEGIN
  -- Get the stored hint answer (hashed or unhashed)
  SELECT p.hint_answer INTO stored_hash
  FROM public.profiles p
  JOIN auth.users u ON p.id = u.id
  WHERE u.email = user_email;
  
  IF stored_hash IS NULL THEN
    RETURN false;
  END IF;
  
  -- Compute hash of submitted answer
  computed_hash := public.hash_hint_answer(submitted_answer);
  
  -- Check if stored value is already hashed or plaintext
  IF stored_hash LIKE 'hash:%' THEN
    -- Compare hashed values
    RETURN stored_hash = computed_hash;
  ELSE
    -- Legacy: compare with plaintext (and update to hash on next opportunity)
    RETURN LOWER(TRIM(stored_hash)) = LOWER(TRIM(submitted_answer));
  END IF;
END;
$$;



--
-- Name: verify_hint_answer_with_rate_limit(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_hint_answer_with_rate_limit(user_email text, submitted_answer text, user_ip text DEFAULT NULL::text, user_agent_str text DEFAULT NULL::text) RETURNS TABLE(is_valid boolean, is_locked boolean, attempts_remaining integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  stored_hash TEXT;
  computed_hash TEXT;
  recent_attempts INTEGER;
  answer_matches BOOLEAN := false;
BEGIN
  -- Check if account is locked
  IF public.is_account_locked(user_email) THEN
    RETURN QUERY SELECT false, true, 0;
    RETURN;
  END IF;
  
  -- Count recent failed attempts in last hour
  SELECT COUNT(*) INTO recent_attempts
  FROM public.password_reset_attempts
  WHERE email = user_email
    AND attempted_at > NOW() - INTERVAL '1 hour'
    AND was_successful = false;
  
  -- If already 4 failed attempts, this is the last one before lockout
  IF recent_attempts >= 4 THEN
    -- Log the attempt as failed (will trigger lockout)
    INSERT INTO public.password_reset_attempts (email, was_successful, ip_address, user_agent)
    VALUES (user_email, false, user_ip, user_agent_str);
    
    RETURN QUERY SELECT false, true, 0;
    RETURN;
  END IF;
  
  -- Get the stored hint answer hash
  SELECT p.hint_answer INTO stored_hash
  FROM public.profiles p
  JOIN auth.users u ON p.id = u.id
  WHERE u.email = user_email;
  
  IF stored_hash IS NULL THEN
    -- Log failed attempt for non-existent user
    INSERT INTO public.password_reset_attempts (email, was_successful, ip_address, user_agent)
    VALUES (user_email, false, user_ip, user_agent_str);
    
    RETURN QUERY SELECT false, false, (4 - recent_attempts);
    RETURN;
  END IF;
  
  -- Compute hash of submitted answer
  computed_hash := public.hash_hint_answer(submitted_answer);
  
  -- Check if stored value is already hashed or plaintext
  IF stored_hash LIKE 'hash:%' THEN
    answer_matches := stored_hash = computed_hash;
  ELSE
    -- Legacy: compare with plaintext
    answer_matches := LOWER(TRIM(stored_hash)) = LOWER(TRIM(submitted_answer));
  END IF;
  
  -- Log the attempt
  INSERT INTO public.password_reset_attempts (email, was_successful, ip_address, user_agent)
  VALUES (user_email, answer_matches, user_ip, user_agent_str);
  
  -- Return result with attempts remaining
  IF answer_matches THEN
    RETURN QUERY SELECT true, false, 5;
  ELSE
    RETURN QUERY SELECT false, false, (4 - recent_attempts);
  END IF;
END;
$$;



