--
-- Name: activity_daily_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.activity_daily_summary AS
 SELECT v.user_id,
    ae.activity_date AS date,
    count(*) AS total_activities,
    count(*) FILTER (WHERE ((ae.check_out_time IS NOT NULL) OR (ae.completed_at IS NOT NULL) OR (ae.status = 'closed'::text))) AS completed_activities,
    COALESCE(sum(ae.duration_minutes), (0)::bigint) AS total_activity_minutes,
    COALESCE(sum(ae.duration_minutes) FILTER (WHERE ((ae.check_out_time IS NOT NULL) OR (ae.completed_at IS NOT NULL) OR (ae.status = 'closed'::text))), (0)::bigint) AS completed_activity_minutes,
    round(COALESCE(sum(
        CASE
            WHEN ((ae.check_out_time IS NOT NULL) OR (ae.completed_at IS NOT NULL) OR (ae.status = 'closed'::text)) THEN COALESCE(t.productivity_weight, 1.0)
            ELSE (0)::numeric
        END), (0)::numeric), 2) AS activity_points
   FROM ((public.activity_events ae
     JOIN public.visits v ON (((v.id = ae.visit_id) AND (v.visit_type = 'activity'::text))))
     LEFT JOIN public.activity_types t ON ((t.name = ae.activity_type)))
  GROUP BY v.user_id, ae.activity_date;



