--
-- Name: activity_type_productivity; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.activity_type_productivity AS
 SELECT v.user_id,
    ae.activity_date AS date,
    ae.activity_type,
    COALESCE(t.productivity_weight, 1.0) AS weight,
    t.is_sales_activity,
    count(*) AS activities,
    count(*) FILTER (WHERE ((ae.check_out_time IS NOT NULL) OR (ae.completed_at IS NOT NULL) OR (ae.status = 'closed'::text))) AS completed,
    COALESCE(sum(ae.duration_minutes), (0)::bigint) AS minutes,
    round(((count(*) FILTER (WHERE ((ae.check_out_time IS NOT NULL) OR (ae.completed_at IS NOT NULL) OR (ae.status = 'closed'::text))))::numeric * COALESCE(t.productivity_weight, 1.0)), 2) AS points
   FROM ((public.activity_events ae
     JOIN public.visits v ON (((v.id = ae.visit_id) AND (v.visit_type = 'activity'::text))))
     LEFT JOIN public.activity_types t ON ((t.name = ae.activity_type)))
  GROUP BY v.user_id, ae.activity_date, ae.activity_type, t.productivity_weight, t.is_sales_activity;



