--
-- Name: analytics_productivity_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.analytics_productivity_summary WITH (security_invoker='true') AS
 WITH beat_retailers AS (
         SELECT DISTINCT bp.user_id,
            bp.plan_date AS activity_date,
            r.id AS retailer_id
           FROM (public.beat_plans bp
             JOIN public.retailers r ON (((bp.beat_id = r.beat_id) AND (bp.user_id = r.user_id))))
        ), visit_status AS (
         SELECT v.user_id,
            v.planned_date AS activity_date,
            v.retailer_id,
                CASE
                    WHEN (max(
                    CASE
                        WHEN (v.status = 'productive'::text) THEN 3
                        WHEN (v.no_order_reason IS NOT NULL) THEN 2
                        WHEN (v.status = 'unproductive'::text) THEN 1
                        ELSE 0
                    END) = 3) THEN 'productive'::text
                    WHEN (max(
                    CASE
                        WHEN (v.no_order_reason IS NOT NULL) THEN 2
                        WHEN (v.status = 'unproductive'::text) THEN 1
                        ELSE 0
                    END) >= 1) THEN 'unproductive'::text
                    ELSE 'planned'::text
                END AS visit_status
           FROM public.visits v
          GROUP BY v.user_id, v.planned_date, v.retailer_id
        ), confirmed_orders AS (
         SELECT DISTINCT o.user_id,
            o.order_date AS activity_date,
            o.retailer_id
           FROM public.orders o
          WHERE (o.status = 'confirmed'::text)
        ), all_retailers AS (
         SELECT beat_retailers.user_id,
            beat_retailers.activity_date,
            beat_retailers.retailer_id
           FROM beat_retailers
        UNION
         SELECT visit_status.user_id,
            visit_status.activity_date,
            visit_status.retailer_id
           FROM visit_status
        UNION
         SELECT confirmed_orders.user_id,
            confirmed_orders.activity_date,
            confirmed_orders.retailer_id
           FROM confirmed_orders
        ), retailer_productivity AS (
         SELECT ar.user_id,
            ar.activity_date,
            ar.retailer_id,
                CASE
                    WHEN ((co.retailer_id IS NOT NULL) OR (vs.visit_status = 'productive'::text)) THEN 1
                    ELSE 0
                END AS is_productive,
                CASE
                    WHEN ((co.retailer_id IS NULL) AND (vs.visit_status = 'unproductive'::text)) THEN 1
                    ELSE 0
                END AS is_unproductive
           FROM ((all_retailers ar
             LEFT JOIN visit_status vs ON (((ar.user_id = vs.user_id) AND (ar.activity_date = vs.activity_date) AND (ar.retailer_id = vs.retailer_id))))
             LEFT JOIN confirmed_orders co ON (((ar.user_id = co.user_id) AND (ar.activity_date = co.activity_date) AND (ar.retailer_id = co.retailer_id))))
        ), daily_summary AS (
         SELECT rp.user_id,
            rp.activity_date,
            count(DISTINCT rp.retailer_id) AS planned,
            count(DISTINCT
                CASE
                    WHEN (rp.is_productive = 1) THEN rp.retailer_id
                    ELSE NULL::uuid
                END) AS productive,
            count(DISTINCT
                CASE
                    WHEN (rp.is_unproductive = 1) THEN rp.retailer_id
                    ELSE NULL::uuid
                END) AS unproductive
           FROM retailer_productivity rp
          GROUP BY rp.user_id, rp.activity_date
        )
 SELECT ds.activity_date,
    ds.user_id,
    p.full_name AS user_name,
    p.username,
    ds.planned,
    ds.productive,
    ds.unproductive,
    GREATEST((0)::bigint, ((ds.planned - ds.productive) - ds.unproductive)) AS pending,
    round((((ds.productive)::numeric / (NULLIF(ds.planned, 0))::numeric) * (100)::numeric), 2) AS ptv_pct,
    round((((ds.productive)::numeric / (NULLIF((ds.productive + ds.unproductive), 0))::numeric) * (100)::numeric), 2) AS vto_pct
   FROM (daily_summary ds
     LEFT JOIN public.profiles p ON ((ds.user_id = p.id)));



