    new_retailer_starting_score numeric(3,1) DEFAULT 6.0 NOT NULL,
    payment_term_days integer DEFAULT 30 NOT NULL,
    credit_multiplier numeric(4,2) DEFAULT 1.5 NOT NULL,
    weight_growth_rate numeric(3,1) DEFAULT 4.0 NOT NULL,
    weight_repayment_dso numeric(3,1) DEFAULT 4.0 NOT NULL,
    weight_order_frequency numeric(3,1) DEFAULT 2.0 NOT NULL,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    territory_ids text[] DEFAULT '{}'::text[] NOT NULL,
    is_active boolean DEFAULT true,
    config_name text,
    target_growth_rate_percent numeric DEFAULT 10.0,
    target_order_frequency numeric DEFAULT 2.0,
    CONSTRAINT credit_management_config_new_retailer_starting_score_check CHECK (((new_retailer_starting_score >= (0)::numeric) AND (new_retailer_starting_score <= (10)::numeric))),
    CONSTRAINT credit_management_config_scoring_mode_check CHECK ((scoring_mode = ANY (ARRAY['manual'::text, 'ai_driven'::text]))),
    CONSTRAINT credit_management_config_weight_growth_rate_check CHECK (((weight_growth_rate >= (0)::numeric) AND (weight_growth_rate <= (10)::numeric))),
    CONSTRAINT credit_management_config_weight_order_frequency_check CHECK (((weight_order_frequency >= (0)::numeric) AND (weight_order_frequency <= (10)::numeric))),
    CONSTRAINT credit_management_config_weight_repayment_dso_check CHECK (((weight_repayment_dso >= (0)::numeric) AND (weight_repayment_dso <= (10)::numeric))),
    CONSTRAINT total_weight_check CHECK ((((weight_growth_rate + weight_repayment_dso) + weight_order_frequency) = 10.0))
);



