--
-- Name: field_productivity_daily; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.field_productivity_daily AS
 WITH sales AS (
         SELECT visits.user_id,
            visits.planned_date AS date,
            count(*) FILTER (WHERE (visits.status = 'productive'::text)) AS productive_sales_visits,
            count(*) FILTER (WHERE (visits.status = ANY (ARRAY['productive'::text, 'unproductive'::text]))) AS total_sales_visits
           FROM public.visits
          WHERE ((COALESCE(visits.status, ''::text) <> 'cancelled'::text) AND (COALESCE(visits.visit_type, ''::text) <> 'activity'::text))
          GROUP BY visits.user_id, visits.planned_date
        ), act AS (
         SELECT activity_daily_summary.user_id,
            activity_daily_summary.date,
            activity_daily_summary.total_activities,
            activity_daily_summary.completed_activities,
            activity_daily_summary.completed_activity_minutes,
            activity_daily_summary.activity_points
           FROM public.activity_daily_summary
        )
 SELECT COALESCE(s.user_id, a.user_id) AS user_id,
    COALESCE(s.date, a.date) AS date,
    COALESCE(s.productive_sales_visits, (0)::bigint) AS productive_sales_visits,
    COALESCE(s.total_sales_visits, (0)::bigint) AS total_sales_visits,
    COALESCE(a.total_activities, (0)::bigint) AS total_activity_visits,
    COALESCE(a.completed_activities, (0)::bigint) AS completed_activities,
    COALESCE(a.completed_activity_minutes, (0)::bigint) AS activity_minutes,
    COALESCE(a.activity_points, (0)::numeric) AS activity_points,
    ((COALESCE(s.productive_sales_visits, (0)::bigint))::numeric + COALESCE(a.activity_points, (0)::numeric)) AS overall_field_productivity
   FROM (sales s
     FULL JOIN act a ON (((a.user_id = s.user_id) AND (a.date = s.date))));



