-- Name: joint_sales_feedback; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.joint_sales_feedback (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    visit_id uuid,
    retailer_id uuid NOT NULL,
    manager_id uuid NOT NULL,
    fse_user_id uuid NOT NULL,
    beat_plan_id uuid,
    feedback_date date DEFAULT CURRENT_DATE NOT NULL,
    branding_rating integer,
    retailing_rating integer,
    pricing_feedback_rating integer,
    schemes_rating integer,
    competition_rating integer,
    product_feedback_rating integer,
    sampling_rating integer,
    distributor_feedback_rating integer,
    sales_trends_rating integer,
    future_growth_rating integer,
    branding_status text,
    shelf_visibility text,
    pricing_compliance text,
    scheme_awareness text,
    competition_presence text,
    sampling_status text,
    distributor_service text,
    sales_trend text,
    growth_potential text,
    retailer_notes text,
    conversation_highlights text,
    action_items text,
    additional_notes text,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    retailing_feedback text,
    placement_feedback text,
    sales_increase_feedback text,
    new_products_introduced text,
    competition_knowledge text,
    trends_feedback text,
    product_quality_feedback text,
    service_feedback text,
    schemes_feedback text,
    pricing_feedback text,
    consumer_feedback text,
    joint_sales_impact text,
    order_increase_amount numeric(10,2) DEFAULT 0,
    product_packaging_feedback text,
    product_sku_range_feedback text,
    promotion_vs_competition text,
    product_usp_feedback text,
    willingness_to_grow_range text,
    monthly_potential_6months numeric DEFAULT 0,
    CONSTRAINT joint_sales_feedback_branding_rating_check CHECK (((branding_rating >= 1) AND (branding_rating <= 5))),
    CONSTRAINT joint_sales_feedback_competition_rating_check CHECK (((competition_rating >= 1) AND (competition_rating <= 5))),
    CONSTRAINT joint_sales_feedback_distributor_feedback_rating_check CHECK (((distributor_feedback_rating >= 1) AND (distributor_feedback_rating <= 5))),
    CONSTRAINT joint_sales_feedback_future_growth_rating_check CHECK (((future_growth_rating >= 1) AND (future_growth_rating <= 5))),
    CONSTRAINT joint_sales_feedback_pricing_feedback_rating_check CHECK (((pricing_feedback_rating >= 1) AND (pricing_feedback_rating <= 5))),
    CONSTRAINT joint_sales_feedback_product_feedback_rating_check CHECK (((product_feedback_rating >= 1) AND (product_feedback_rating <= 5))),
    CONSTRAINT joint_sales_feedback_retailing_rating_check CHECK (((retailing_rating >= 1) AND (retailing_rating <= 5))),
    CONSTRAINT joint_sales_feedback_sales_trends_rating_check CHECK (((sales_trends_rating >= 1) AND (sales_trends_rating <= 5))),
    CONSTRAINT joint_sales_feedback_sampling_rating_check CHECK (((sampling_rating >= 1) AND (sampling_rating <= 5))),
    CONSTRAINT joint_sales_feedback_schemes_rating_check CHECK (((schemes_rating >= 1) AND (schemes_rating <= 5)))
);



