--
-- Name: report_subscriptions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.report_subscriptions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    report_definition_id uuid NOT NULL,
    cadence text NOT NULL,
    fire_day text,
    fire_time time without time zone DEFAULT '08:00:00'::time without time zone NOT NULL,
    timezone text DEFAULT 'Asia/Kolkata'::text NOT NULL,
    recipient_user_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    attachment_format text DEFAULT 'excel'::text NOT NULL,
    push_to_phone boolean DEFAULT true NOT NULL,
    scope text DEFAULT 'shared'::text NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    last_fired_at timestamp with time zone,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    recipient_mode text DEFAULT 'named_users'::text NOT NULL,
    period_basis text DEFAULT 'current'::text NOT NULL,
    last_scheduled_fire_at timestamp with time zone,
    last_scheduled_period_key text,
    pdf_template jsonb DEFAULT '{}'::jsonb NOT NULL,
    respect_hierarchy boolean DEFAULT true NOT NULL,
    admin_scope text DEFAULT 'global'::text NOT NULL,
    ai_enabled boolean DEFAULT false NOT NULL,
    ai_prompt text,
    CONSTRAINT report_subscriptions_admin_scope_chk CHECK ((admin_scope = ANY (ARRAY['global'::text, 'own_hierarchy'::text]))),
    CONSTRAINT report_subscriptions_ai_complete_chk CHECK (((ai_enabled = false) OR (btrim(COALESCE(ai_prompt, ''::text)) <> ''::text))),
    CONSTRAINT report_subscriptions_attachment_format_check CHECK ((attachment_format = ANY (ARRAY['excel'::text, 'pdf'::text, 'summary_only'::text]))),
    CONSTRAINT report_subscriptions_cadence_check CHECK ((cadence = ANY (ARRAY['today'::text, 'daily'::text, 'weekday'::text, 'weekly'::text, 'monthly'::text]))),
    CONSTRAINT report_subscriptions_period_basis_check CHECK ((period_basis = ANY (ARRAY['current'::text, 'previous'::text]))),
    CONSTRAINT report_subscriptions_recipient_mode_check CHECK ((recipient_mode = ANY (ARRAY['named_users'::text, 'all_managers'::text]))),
    CONSTRAINT report_subscriptions_scope_check CHECK ((scope = ANY (ARRAY['shared'::text, 'per_recipient'::text]))),
    CONSTRAINT report_subscriptions_status_check CHECK ((status = ANY (ARRAY['active'::text, 'paused'::text, 'draft'::text])))
);



--
-- Name: COLUMN report_subscriptions.respect_hierarchy; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.report_subscriptions.respect_hierarchy IS 'Scope each recipient''s report to their own subtree in employees.manager_id. System admins bypass. Turn off only for deliberately org-wide reports.';



--
-- Name: COLUMN report_subscriptions.admin_scope; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.report_subscriptions.admin_scope IS 'What a System Administrator recipient receives when respect_hierarchy is true: global = organisation-wide, own_hierarchy = only their own reporting tree. Ignored when respect_hierarchy is false.';



--
-- Name: COLUMN report_subscriptions.ai_enabled; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.report_subscriptions.ai_enabled IS 'When true, generate-report asks the AI to summarise this run''s rows and puts the result in the notification, the summary_only body and the PDF. Never replaces the report data.';



--
-- Name: COLUMN report_subscriptions.ai_prompt; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.report_subscriptions.ai_prompt IS 'What the author wants summarised, e.g. "Call out the biggest drop versus usual and who needs attention."';



