--

CREATE POLICY obr_select ON public.order_backdate_requests FOR SELECT TO authenticated USING (((user_id = auth.uid()) OR public.user_has_permission(auth.uid(), 'order_backdate'::text, 'can_view_all'::text) OR (EXISTS ( SELECT 1
   FROM public.approval_steps s
  WHERE ((s.approval_request_id = order_backdate_requests.approval_request_id) AND (s.approver_id = auth.uid()))))));



