--

CREATE POLICY order_items_select_admin_or_manager ON public.order_items FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1
   FROM public.orders o
  WHERE ((o.id = order_items.order_id) AND ((o.user_id = auth.uid()) OR public.is_subordinate_of(auth.uid(), o.user_id) OR public.user_has_beat_access(auth.uid(), o.beat_id) OR (auth.uid() = o.owner_id_snapshot) OR public.is_system_admin(auth.uid()))))));



